window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0035", [{"word":"accurately","ipa_uk":"/əˈkjʊrətli/","ipa_us":"/ˈækjərətli/","definition_zh":"准确地；精确地；如实无误地","definition_en":"in a way that is correct in every detail, matches the facts, or hits the intended point exactly","core_image":"箭落在靶心，刻度线与落点完全对齐","scene":"实验台前，学生把量筒放在水平面上，视线与凹液面最低处齐平。The two readings matched exactly, and the supervisor said that the volume had been measured accurately.","sceneCN":"这里 accurately 是「准确地、精确地」（第 1 个义项：测量上没有误差）；句意：两次读数完全一致，导师说这个体积测得准确。图中可辨识物件：量筒、凹液面、记录本、复核者、水平台面。","pos":[{"tag":"adv.","zh":"准确地；精确地"},{"tag":"adv.","zh":"如实无误地"},{"tag":"adv.","zh":"恰好地；分毫不差地"}],"collocations":[{"phrase":"accurately describe","zh":"准确描述"},{"phrase":"accurately measure","zh":"精确测量"},{"phrase":"accurately predict","zh":"准确预测"},{"phrase":"accurately reflect","zh":"如实反映"},{"phrase":"report accurately","zh":"如实报道"}],"forms":[{"label":"原级（副词）","form":"accurately"},{"label":"比较级（更准确）","form":"more accurately"},{"label":"最高级（最准确）","form":"most accurately"}],"derivatives":[{"word":"accurate","pos":"adj.","zh":"准确的；精确的"},{"word":"accuracy","pos":"n.","zh":"准确；精确度"},{"word":"inaccurate","pos":"adj.","zh":"不准确的"},{"word":"inaccuracy","pos":"n.","zh":"不准确；误差"},{"word":"accurateness","pos":"n.","zh":"准确（较少用）"}],"senses":[{"no":"01","title":"Without error in measurement","titleCN":"测量上没有误差","definition":"in a way that gives a correct value or reading, within the limits of the instrument","definitionCN":"以给出正确数值或读数的方式，且在仪器精度范围内","example":"The thermometer measures body temperature accurately to within 0.1°C.","exampleCN":"这支体温计测量体温的误差在 0.1°C 以内。","why":"Accurate comes from Latin accuratus, 'prepared with care', from cura 'care'. Measurement is the modern test of that care: the reading must match the scale, and the old sense of careful preparation becomes numerical correctness.","whyCN":"accurate 来自拉丁语 accuratus“精心准备的”，词根是 cura“关心、照料”。测量是这种“用心”的现代检验：读数必须与刻度相符，古老的“精心准备”于是变成数值上的正确。"},{"no":"02","title":"True to the facts","titleCN":"与事实相符","definition":"of a report, account, or description, in a way that does not distort what happened","definitionCN":"指报道、叙述或描述不扭曲已发生之事","example":"The article accurately describes what the witnesses saw.","exampleCN":"这篇文章准确描述目击者看到的情况。","why":"A carelessly prepared account misses details; a carefully prepared one keeps them. The word moves from the making of a thing to the telling of a thing, but the standard is the same: nothing may be left out or added.","whyCN":"粗心准备的叙述会漏掉细节，用心准备的则保留细节。这个词从“制作某物”移到“讲述某事”，但标准不变：不能漏，也不能添。"},{"no":"03","title":"Hitting the intended point","titleCN":"命中预定之点","definition":"of a throw, shot, or movement, in a way that reaches the exact intended place","definitionCN":"指投掷、射击或动作抵达预定的确切位置","example":"The arrow flew accurately into the centre of the target.","exampleCN":"箭准确地飞入靶心。","why":"Before instruments, accuracy was a bodily virtue: the hand sends the object where the eye intends. The same word covers a thermometer and an arrow because both close the gap between intention and result.","whyCN":"在仪器之前，准确是一种身体德性：手把物件送到眼睛想去的地方。同一个词既管温度计也管箭，因为两者都在缩小“意图”与“结果”之间的缝隙。"},{"no":"04","title":"Faithful reproduction","titleCN":"忠实复制","definition":"of a copy, translation, or recording, in a way that preserves the original's details","definitionCN":"指复制品、翻译或录音保留原件的细节","example":"The recording accurately captures the timbre of the original performance.","exampleCN":"这段录音准确捕捉了原演的音色。","why":"A copy is 'prepared' from an original, and care means fidelity. Accuracy here is not sameness of material but sameness of information: the copy may be in another medium yet carry the same detail.","whyCN":"复制品是依原件“制作”的，用心就意味着忠实。这里的准确不是材料相同，而是信息相同：复制品可以换一种媒介，却承载同样的细节。"},{"no":"05","title":"Exactly in time","titleCN":"时间上分毫不差","definition":"of timing, in a way that matches a schedule or expected moment precisely","definitionCN":"指时间安排与计划或预期时刻精确吻合","example":"The satellite clock keeps time accurately for decades.","exampleCN":"这颗卫星的时钟能精确走时数十年。","why":"Time is measured by regular motion, so accuracy becomes the match between a device's rhythm and the rhythm it is meant to follow. A clock that drifts is 'careless' in the oldest Latin sense.","whyCN":"时间由规则运动来测量，因此准确就是装置的节奏与它应当跟随的节奏相合。走快的钟，在拉丁语最古老的意义上就是“不用心”。"},{"no":"06","title":"Correct in language","titleCN":"语言上正确","definition":"of speech or writing, in a way that follows the rules of grammar, spelling, or pronunciation","definitionCN":"指口语或书面语符合语法、拼写或发音规则","example":"She pronounced the technical terms accurately.","exampleCN":"她准确地读出了那些术语的发音。","why":"Language has its own scale: rules of grammar and sound. Speaking accurately is measuring one's output against that scale, which is why the word can mean 'correctly' without meaning 'truthfully'.","whyCN":"语言有自己的刻度：语法与语音规则。准确地说，就是拿自己的输出去对这把尺，因此这个词可以表示“正确”，却不表示“真实”。"},{"no":"07","title":"Right within an error margin","titleCN":"在误差范围内正确","definition":"of a model or prediction, in a way that falls within an accepted margin of error","definitionCN":"指模型或预测落在可接受的误差范围内","example":"The model accurately predicts demand within five percent.","exampleCN":"该模型对需求的预测误差在百分之五以内。","why":"Science rarely claims perfect correspondence; it claims accuracy within a tolerance. The word shifts from 'no error' to 'error small enough', which is the sense most technical writing now uses.","whyCN":"科学很少声称完全对应，只声称在容差内准确。这个词从“没有误差”转为“误差足够小”，这是现代技术写作最常用的意义。"},{"no":"08","title":"Seeing oneself truthfully","titleCN":"如实看待自己","definition":"of self-assessment, in a way that does not exaggerate or undervalue one's abilities","definitionCN":"指自我评估不夸大也不低估自己的能力","example":"Good leaders assess their own limits accurately.","exampleCN":"好的领导者会准确评估自己的局限。","why":"The care behind accurate can be turned inward: to measure oneself without flattery. This sense is moral rather than instrumental, but it keeps the same image of a reading matched to a scale.","whyCN":"accurate 背后的“用心”可以转向内部：不带奉承地衡量自己。这个义项是道德性的而非工具性的，但仍保留“读数与刻度相合”的同一画面。"}],"etymology":{"intro":{"en":"Accurately is a derived adverb: accurate plus the native suffix -ly. Accurate itself comes from Latin accuratus 'prepared with care', so the word's oldest idea is care, not precision.","cn":"accurately 是派生副词：accurate 加本族后缀 -ly。accurate 本身来自拉丁语 accuratus“精心准备的”，因此这个词最古老的概念是“用心”，而不是“精确”。"},"items":[{"era":"LATIN","en":"Accuratus is the past participle of accurare 'to take care of, prepare carefully', from ad- 'to' plus cura 'care, concern'.","cn":"accuratus 是 accurare“照料、精心准备”的过去分词，由 ad-“向”加 cura“关心、照料”构成。"},{"era":"17C.","en":"English borrows accurate in the 1610s, meaning 'done with care, exact'. The Latin participle supplies both the adjective and the noun accuracy.","cn":"英语于 1610 年代借入 accurate，意为“用心做的、精确的”。拉丁分词同时提供形容词与名词 accuracy。"},{"era":"-LY","en":"The adverb suffix -ly comes from Old English -lice, from lic 'body, form'. It originally meant 'in the manner of', and later became the general adverb ending.","cn":"副词后缀 -ly 来自古英语 -lice，词源是 lic“身体、形态”。它最初表示“以……的方式”，后来成为一般副词词尾。"},{"era":"18C.–19C.","en":"As instruments and statistics develop, accuracy is redefined as closeness to a true value. The adverb becomes standard in measurement, navigation, and later in model evaluation.","cn":"随着仪器与统计学发展，accuracy 被重新定义为“接近真值”。这个副词成为测量、航海，后来是模型评估中的标准用语。"},{"era":"MODERN","en":"Technical writing adds the tolerance sense: accurate within a margin. The moral sense survives in phrases such as assess oneself accurately.","cn":"技术写作增加了容差义：在误差范围内准确。道德义则保留在 assess oneself accurately 这类短语中。"}]},"similar":{"note":{"en":"The first group shares the ac-/accur- shape or the same root; the second compares adverbs of correctness.","cn":"第一组共享 ac-/accur- 外形或同一词根；第二组比较表示“正确”的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"accurate","ipa":"/əˈkjʊrət/","tag":"base adjective","definition":"correct in detail. It is the adjective from which the adverb is formed.","definitionCN":"细节正确。它是构成该副词的原形容词。"},{"word":"accuracy","ipa":"/əˈkjʊrəsi/","tag":"derived noun","definition":"the quality of being correct. It is the noun of the same Latin base.","definitionCN":"正确的性质。它是同一拉丁词基的名词。"},{"word":"accurate","ipa":"/əˈkjʊrət/","tag":"spelling","definition":"Note that the adverb keeps the e of accurate before -ly: accurately, not accuratly.","definitionCN":"注意副词在 -ly 前保留 accurate 的 e：accurately，而不是 accuratly。"},{"word":"curate","ipa":"/ˈkjʊreɪt/","tag":"spelling","definition":"to select and organize content, or a clergyman. Its cura is 'care', the same root, but the word means caring for a collection.","definitionCN":"挑选并组织内容，或指牧师。其 cura 也是“照料”，词根相同，但词义是照料一个藏品。"}]},{"heading":"NEAR MEANING","entries":[{"word":"precisely","ipa":"/prɪˈsaɪsli/","tag":"exactness","definition":"in exact terms. It stresses definiteness and exact boundaries more than factual truth.","definitionCN":"以精确的措辞。它比事实真实性更强调明确性与确切边界。"},{"word":"correctly","ipa":"/kəˈrektli/","tag":"rule","definition":"in accordance with a rule or standard. It is broader and can refer to behaviour, while accurately often refers to facts or measurements.","definitionCN":"依照规则或标准。它更宽泛，可指行为，而 accurately 常指事实或测量。"},{"word":"exactly","ipa":"/ɪkˈsæktli/","tag":"no deviation","definition":"with no deviation at all. It is stronger and often absolute, while accurately allows a small error margin.","definitionCN":"完全没有偏差。它更强，常是绝对的，而 accurately 允许小误差。"},{"word":"faithfully","ipa":"/ˈfeɪθfəli/","tag":"fidelity","definition":"in a loyal and exact way, especially of a copy or account. It adds the idea of keeping faith with an original.","definitionCN":"忠诚而精确地，尤指复制或叙述。它增加“对原件守信”的意思。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on cura 'care' and the -ly ending, then three abstract images about matching a reading to a scale.","cn":"先用五个围绕 cura“用心”与 -ly 词尾的挂钩，再用三个关于“读数与刻度相合”的抽象画面。"},"normal":[{"en":"accurate is 'made with care': cura is care, so accurately is 'carefully' turned into 'correctly'.","cn":"accurate 是“用心做成的”：cura 是用心，因此 accurately 就是“用心”变成“正确”。"},{"en":"accurately keeps the e: accurate + ly, never accuratly.","cn":"accurately 保留 e：accurate + ly，绝不写成 accuratly。"},{"en":"An arrow, a thermometer and a witness can all be accurate: each closes a gap between intention and result.","cn":"箭、温度计与目击者都可以 accurate：三者都在缩小意图与结果之间的缝。"},{"en":"In science, accurately often means 'within tolerance', not 'perfectly'.","cn":"在科学里，accurately 常指“在容差内”，而不是“完美”。"},{"en":"Accuracy is the noun, inaccurate the negation, inaccuracy the error itself.","cn":"accuracy 是名词，inaccurate 是否定形容词，inaccuracy 是误差本身。"}],"abstract":[{"en":"Accuracy is a relation between a claim and a world that does not offer a second chance.","cn":"准确是主张与一个不给第二次机会的世界之间的关系。"},{"en":"Care and correctness are the same word here: the careful hand is the hand that arrives.","cn":"在这里，用心与正确是同一个词：用心的手，就是能抵达的手。"},{"en":"A perfectly accurate answer to the wrong question is still a failure.","cn":"对错误问题的完美准确回答，仍然是失败。"}]},"examples":[{"en":"The survey accurately reflects the views of the whole town.","cn":"这项调查准确反映了全镇的看法。"},{"en":"He can accurately repeat a melody after hearing it once.","cn":"他听一遍就能准确复述一段旋律。"},{"en":"No model can accurately predict every storm.","cn":"没有模型能准确预测每一场风暴。"}],"dict_mnemonic":{"note":"accurate（用心的、精确的）+ -ly（副词）→ 精确地。词根 cura 是“用心”：用心做，才做得准。","text":"ad（向）+ cura（用心）→ accuratus（精心做的）→ accurate + -ly → 准确地","word":"accurately"},"root":"拉丁 accuratus“精心准备的”（accurare = ad- 向 + cura 用心）→ 英语 accurate（17 世纪）+ 本族副词后缀 -ly（古英语 -lice）→ accurately。","sensesIntro":{"en":"The senses move from measured values, to factual accounts, to aimed movement, to faithful copies, to exact timing, to correct language, to accuracy within tolerance, and finally to truthful self-assessment.","cn":"这些义项从测量值，走到事实叙述、瞄准的动作、忠实的复制、精确的计时、正确的语言、容差内的准确，最后落到如实的自我评估。"},"semanticMap":{"core":{"en":"An arrow at the centre of the target, the scale and the landing point in one line","cn":"箭落在靶心，刻度与落点成一条线"},"chain":["WITH CARE","MEASURED","EXACT","TRUE TO FACT","FAITHFUL COPY","TRUSTED"],"branches":[{"senses":"01 · 05","en":"Instrumental accuracy: a value read correctly, and a rhythm kept without drift.","cn":"工具性准确：正确读出的数值，与不走样的节奏。"},{"senses":"02 · 08","en":"Truth about the world and truth about oneself: the report and the mirror.","cn":"关于世界与关于自己的真实：报道与镜子。"},{"senses":"03 · 04","en":"Closing a gap: the thrown object reaches its mark, the copy keeps its original.","cn":"缩小缝隙：投出的物件抵达目标，复制品保住原件。"},{"senses":"06","en":"A standard: the grammar book decides what counts as correct language.","cn":"标准：语法书判定语言的对错。"},{"senses":"07","en":"A tolerance: a model need not touch the truth, only fall inside the error bar.","cn":"容差：模型不必贴住真值，只需落在误差棒之内。"}]},"affixes":{"intro":{"en":"Accurately is a transparent derivative: the adjective accurate plus the adverb suffix -ly, with accuracy and the negative inaccuracy alongside.","cn":"accurately 是透明的派生词：形容词 accurate 加副词后缀 -ly，旁边还有名词 accuracy 与否定形式 inaccuracy。"},"latinIntro":{"en":"Latin cura 'care' is the base of accuratus. The prefix ad- adds direction ('toward'), and the participle ending -atus makes an adjective; English then adds its own -ly.","cn":"拉丁语 cura“用心”是 accuratus 的词基。前缀 ad- 增加方向“朝向”，分词词尾 -atus 构成形容词；英语再加自己的 -ly。"},"items":[{"word":"accurately","structure":"accurate + -ly (adverb)","meaning":"in an exact or correct way","meaningCN":"准确地；精确地","example":"The event was accurately reported.","exampleCN":"这件事得到了准确报道。"},{"word":"accurate","structure":"ad- + cura + -atus (adjective)","meaning":"done with care; exact","meaningCN":"用心做的；精确的","example":"The clock is accurate.","exampleCN":"这个钟走时准确。"},{"word":"accuracy","structure":"accurate + -acy (abstract noun)","meaning":"the quality of being exact","meaningCN":"准确；精确度","example":"Accuracy matters in navigation.","exampleCN":"航海中的精确度很重要。"},{"word":"inaccurate","structure":"in- (not) + accurate","meaning":"not exact; wrong in detail","meaningCN":"不准确的","example":"The first report was inaccurate.","exampleCN":"最初的报道不准确。"},{"word":"inaccuracy","structure":"in- + accuracy","meaning":"an error or lack of exactness","meaningCN":"不准确；误差","example":"The audit found several inaccuracies.","exampleCN":"审计发现了几处不准确之处。"},{"word":"accurateness","structure":"accurate + -ness (state noun)","meaning":"the state of being exact","meaningCN":"准确的性质（较少用）","example":"The accurateness of the drawing was praised.","exampleCN":"这幅图的准确受到称赞。"},{"word":"cura","structure":"Latin noun","meaning":"care, concern","meaningCN":"关心；照料","example":"Cura is the root of accurate.","exampleCN":"cura 是 accurate 的词根。"},{"word":"cure","structure":"cura + -e (via French)","meaning":"to heal, or a remedy","meaningCN":"治愈；疗法","example":"The same cura gives English cure.","exampleCN":"同一个 cura 也给出英语 cure。"},{"word":"curious","structure":"cura + -iosus","meaning":"careful, then eager to know","meaningCN":"仔细的，后转为好奇的","example":"Curious also descends from cura.","exampleCN":"curious 也源自 cura。"}],"latinEntries":[{"word":"cura","structure":"Latin noun","meaning":"care, concern, attention","meaningCN":"关心；照料；注意","example":"Cura is the base of accuratus.","exampleCN":"cura 是 accuratus 的词基。"},{"word":"accurare","structure":"ad- (to) + cura (care)","meaning":"to take care of, prepare carefully","meaningCN":"照料；精心准备","example":"Accurare gives the participle accuratus.","exampleCN":"accurare 给出分词 accuratus。"},{"word":"accuratus","structure":"accurare + -atus (past participle)","meaning":"prepared with care, exact","meaningCN":"精心准备的；精确的","example":"Accuratus is the direct source of accurate.","exampleCN":"accuratus 是 accurate 的直接来源。"}]}},{"word":"achievement","ipa_uk":"/əˈtʃiːvmənt/","ipa_us":"/əˈtʃiːvmənt/","definition_zh":"成就；成绩；达成；实现","definition_en":"the act of reaching a goal through effort, or a notable result that has been reached","core_image":"把一件难事推到终点，旗子插在山顶，鞋已经磨破","scene":"山顶的风里插着一面旗，旁边是磨破的鞋和被翻烂的计划本。Reaching the top after years of work was an achievement he could point to, with only the flag and the worn shoes to prove it.","sceneCN":"这里 achievement 是「经过努力达成的成就」（第 1 个义项：经过努力达成目标）；句意：多年之后登上山顶，是他能指着说的成就，只有旗子和磨破的鞋作证。图中可辨识物件：旗子、磨破的鞋、计划本、山顶。","pos":[{"tag":"n.","zh":"成就；成绩（可数）"},{"tag":"n.","zh":"达成；实现（不可数）"},{"tag":"n.","zh":"学业表现；成就水平"}],"collocations":[{"phrase":"sense of achievement","zh":"成就感"},{"phrase":"academic achievement","zh":"学业成绩"},{"phrase":"achievement test","zh":"成就测验；学业测验"},{"phrase":"a great achievement","zh":"一项伟大成就"},{"phrase":"achievement gap","zh":"成绩差距"}],"forms":[{"label":"单数（一个成就）","form":"achievement"},{"label":"复数（多个成就）","form":"achievements"},{"label":"动词（原形）","form":"achieve"}],"derivatives":[{"word":"achieve","pos":"v.","zh":"达成；实现；取得"},{"word":"achievable","pos":"adj.","zh":"可实现的"},{"word":"achiever","pos":"n.","zh":"有成就的人"},{"word":"underachievement","pos":"n.","zh":"学业低于预期；未充分发挥"},{"word":"overachievement","pos":"n.","zh":"超出预期的成就"}],"senses":[{"no":"01","title":"Reaching a goal through effort","titleCN":"经过努力达成目标","definition":"the act of successfully reaching a goal that required effort or persistence","definitionCN":"成功达到一个需要努力或坚持的目标的行为","example":"Finishing the marathon was a real achievement for her.","exampleCN":"跑完马拉松对她来说是一项真正的成就。","why":"Achieve comes from Old French achever, 'to come to a head', from the phrase à chief 'to a head'. The word begins with arrival at an end point, and effort is what makes that arrival an achievement rather than an accident.","whyCN":"achieve 来自古法语 achever“到达头部、完成”，源出短语 à chief“到头”。这个词的起点是抵达终点，而努力使这次抵达成为成就，而不是偶然。"},{"no":"02","title":"A notable result","titleCN":"值得称道的成果","definition":"a concrete result or feat that is impressive and worth recognizing","definitionCN":"令人印象深刻、值得认可的具体成果或功绩","example":"The bridge was an engineering achievement of its decade.","exampleCN":"这座桥是那个年代的一项工程成就。","why":"Once 'coming to a head' is done, the finished thing stands as evidence. The noun shifts from the act to the object produced, which is why achievements can be listed, awarded, and remembered.","whyCN":"一旦“到头”完成，成品就作为证据立在那里。名词从动作转到产出的物件，因此成就可以被列出、颁奖、纪念。"},{"no":"03","title":"Academic attainment","titleCN":"学业成就","definition":"measured performance in school or study, often as scores or qualifications","definitionCN":"在学校或学习中被测量的表现，常以分数或学历表示","example":"The program is designed to raise achievement in reading.","exampleCN":"该项目旨在提高阅读成绩。","why":"Education needs a word for reaching a standard, not merely attending. Achievement becomes a measurable level, and the phrase achievement gap names the distance between groups.","whyCN":"教育需要一个词来表示“达到标准”，而不只是“上过学”。achievement 于是成为可测量的水平，而 achievement gap 命名群体之间的距离。"},{"no":"04","title":"Completion of a task","titleCN":"任务的完成","definition":"the successful completion of a specific task or process","definitionCN":"特定任务或流程的成功完成","example":"The achievement of the merger took two years of negotiation.","exampleCN":"这项合并的完成花了两年谈判。","why":"Here the word is uncountable and process-oriented: not the trophy but the finishing. The old French sense of 'bring to an end' is closest to the surface in this usage.","whyCN":"这里这个词不可数，且指向过程：不是奖杯，而是完成本身。在这个用法里，古法语“带到终点”的意思最贴近表面。"},{"no":"05","title":"A record or peak performance","titleCN":"纪录或巅峰表现","definition":"a result that surpasses previous levels and therefore becomes a benchmark","definitionCN":"超过以往水平、因而成为基准的结果","example":"Her jump was the highest achievement of the season.","exampleCN":"她的一跳是本赛季的最高成绩。","why":"When results are ranked, achievement acquires a comparative edge: the end point is also a height. The word then measures not just completion but how far the completion went.","whyCN":"当成绩被排名，成就就有了比较的锋芒：终点同时也是一种高度。这个词于是不只衡量“完成了没有”，还衡量“完成得有多远”。"},{"no":"06","title":"A personal milestone","titleCN":"个人里程碑","definition":"a stage in personal development that marks meaningful progress","definitionCN":"个人发展中标志有意义进步的阶段","example":"Learning to cook for himself was a small but important achievement.","exampleCN":"学会给自己做饭是一项微小但重要的成就。","why":"The end point can be internal: a skill, a habit, a step toward independence. The word scales down without losing its structure, because achievement is defined by the distance travelled, not by public notice.","whyCN":"终点可以是内在的：一项技能、一个习惯、迈向独立的一步。这个词可以缩小尺度而不丢结构，因为成就由走过的距离定义，而不是由公众是否看见定义。"},{"no":"07","title":"The feeling of having achieved","titleCN":"成就感","definition":"the satisfaction or pride that follows a completed effort","definitionCN":"努力完成之后产生的满足或自豪","example":"The students felt a strong sense of achievement after the exhibition.","exampleCN":"展览结束后，学生们感到强烈的成就感。","why":"The noun can name an inner state as well as an outer result. 'Sense of achievement' turns the completed act into a feeling, which is why the phrase is common in education and psychology.","whyCN":"这个名词既能命名外在结果，也能命名内在状态。sense of achievement 把完成的行为变成一种感受，因此这个短语常用于教育与心理学。"},{"no":"08","title":"Official recognition of a feat","titleCN":"对功绩的正式认可","definition":"a formal honour or award given for a notable accomplishment","definitionCN":"因显著成就而给予的正式荣誉或奖励","example":"The medal recognized his achievement in rescue work.","exampleCN":"这枚奖章认可了他在救援工作中的成就。","why":"Institutions attach recognition to results, and the word can name the recognition itself. This is the furthest drift from 'bring to a head': the act is now represented by a token held in the hand.","whyCN":"机构把认可附着在结果上，这个词也能命名认可本身。这是离“带到终点”最远的漂移：行为如今由手中一枚象征物来代表。"}],"etymology":{"intro":{"en":"Achievement is a derived noun: the verb achieve plus the Latin-French suffix -ment. Achieve meant 'bring to a head, finish', so the noun's core is arrival at an end, not praise.","cn":"achievement 是派生名词：动词 achieve 加拉丁-法语后缀 -ment。achieve 意为“到达头部、完成”，因此这个词的核心是抵达终点，而不是赞美。"},"items":[{"era":"OLD FRENCH","en":"Achever 'to finish, come to a head' comes from the phrase à chief 'to a head', where chief is from Latin caput 'head'. The image is a thing brought to its top or end.","cn":"achever“完成、到达头部”来自短语 à chief“到头”，其中 chief 出自拉丁语 caput“头”。画面是把一件事推到顶端或终点。"},{"era":"LATE 14C.","en":"English borrows achieve as a verb meaning 'to finish, accomplish'. The noun achievement follows, first meaning the act of finishing.","cn":"英语于 14 世纪晚期借入动词 achieve，意为“完成、做成”。名词 achievement 随后出现，最初指完成的行为。"},{"era":"-MENT","en":"The suffix -ment comes from Latin -mentum through French. It forms nouns of result or action, so achievement can name either the finishing or the thing finished.","cn":"后缀 -ment 经法语来自拉丁语 -mentum，构成结果或动作名词，因此 achievement 既能指完成过程，也能指完成之物。"},{"era":"16C.–18C.","en":"The noun widens to feats, honours, and heraldic symbols. A completed deed becomes a public mark, and the word acquires its celebratory tone.","cn":"16 至 18 世纪，这个词扩展到功绩、荣誉与纹章符号。完成的行为变成公共标记，词也随之带上庆贺语气。"},{"era":"20C.","en":"Education and psychology make achievement measurable: achievement tests, achievement gaps, sense of achievement. The old end point becomes a score or a feeling.","cn":"20 世纪，教育与心理学使 achievement 可测量：成就测验、成绩差距、成就感。古老的终点变成分数或感受。"}]},"similar":{"note":{"en":"The first group shares the achieve- shape or the same root; the second compares words for results and success.","cn":"第一组共享 achieve- 外形或同一词根；第二组比较表示“结果与成功”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"achieve","ipa":"/əˈtʃiːv/","tag":"base verb","definition":"to reach a goal. It is the verb behind the noun.","definitionCN":"达到目标。它是该名词背后的动词。"},{"word":"achievable","ipa":"/əˈtʃiːvəbl/","tag":"derived form","definition":"able to be reached. It is achieve + -able, not a separate root.","definitionCN":"能够达到的。它是 achieve + -able，不是另一个词根。"},{"word":"achiever","ipa":"/əˈtʃiːvə/","tag":"derived form","definition":"a person who achieves. It is the agent noun.","definitionCN":"有成就的人。它是施事名词。"},{"word":"chief","ipa":"/tʃiːf/","tag":"same root","definition":"a leader, or main. It comes from Latin caput 'head', the same element as in à chief.","definitionCN":"首领，或主要的。它来自拉丁语 caput“头”，与 à chief 中的成分相同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"accomplishment","ipa":"/əˈkʌmplɪʃmənt/","tag":"completion","definition":"the successful completion of something. It is close to achievement but slightly more formal and process-focused.","definitionCN":"某事的成功完成。它接近 achievement，但更正式，也更重过程。"},{"word":"feat","ipa":"/fiːt/","tag":"deed","definition":"an impressive act, especially one requiring skill or courage. It names the deed, not the status gained.","definitionCN":"令人赞叹的行为，尤需技巧或勇气。它命名行为，而不是获得的地位。"},{"word":"success","ipa":"/səkˈses/","tag":"outcome","definition":"the favourable result of an attempt. It is broader and includes luck, while achievement stresses effort.","definitionCN":"尝试的有利结果。它更宽泛，也包含运气，而 achievement 强调努力。"},{"word":"attainment","ipa":"/əˈteɪnmənt/","tag":"standard","definition":"the reaching of a standard, especially in education. It is the measured cousin of achievement.","definitionCN":"达到某一标准，尤指教育。它是 achievement 的可测量近亲。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on 'to a head' and -ment, then three abstract images about arrival at an end.","cn":"先用五个围绕“到头”与 -ment 的挂钩，再用三个关于“抵达终点”的抽象画面。"},"normal":[{"en":"achieve = à chief = to a head: bring the work to its top, and it is finished.","cn":"achieve = à chief = 到头：把工作推到顶端，它就完成了。"},{"en":"Chief and achieve share caput 'head', so a chief is literally the head.","cn":"chief 与 achieve 共享 caput“头”，因此 chief 字面上就是“头”。"},{"en":"-ment turns the verb into both the act and the result: the finishing and the finished thing.","cn":"-ment 把动词变成动作与结果两者：完成过程与完成之物。"},{"en":"An achievement test measures how far a student has come, not how hard they tried.","cn":"成就测验量的是学生走了多远，而不是多努力。"},{"en":"Sense of achievement is the inner echo of the outer arrival.","cn":"成就感是外在抵达在内心的回声。"}],"abstract":[{"en":"Achievement is distance made visible: the goal was elsewhere, and now it is here.","cn":"成就让距离变得可见：目标原在别处，现在到了眼前。"},{"en":"Effort is part of the definition, which is why inherited advantages do not feel like achievements.","cn":"努力是定义的一部分，因此继承来的优势不让人觉得是成就。"},{"en":"Every achievement creates a new baseline, and the next goal starts from the flag you just planted.","cn":"每项成就都创造新的基线，下一个目标从你刚插下的旗子开始。"}]},"examples":[{"en":"The team's achievement was measured in years, not weeks.","cn":"这个团队的成就以年计，而不是以周计。"},{"en":"She listed her achievements in three clear lines.","cn":"她用三行清楚地列出了自己的成就。"},{"en":"Raising achievement in rural schools remains the hardest task.","cn":"提高农村学校的学业成绩仍是最难的任务。"}],"dict_mnemonic":{"note":"achieve（à chief，到头、完成）+ -ment（名词）→ 把事推到终点的结果 → 成就。chief 与 caput“头”同源。","text":"à chief（到头）+ -ment → 完成的行为或结果 → 成就、成绩、达成","word":"achievement"},"root":"古法语 achever“完成、到头”（à chief = 到头，chief 出自拉丁 caput“头”）→ 英语 achieve + 拉丁-法语后缀 -ment → achievement（14 世纪晚期）。","sensesIntro":{"en":"The senses move from the act of reaching a goal, to the result itself, to measured school performance, to the completion of a process, to a record height, to a private milestone, to the feeling that follows, and finally to the formal recognition of a feat.","cn":"这些义项从达成目标的动作，走到结果本身、可测量的学业表现、流程的完成、创纪录的高度、私人里程碑、随之而来的感受，最后是对功绩的正式认可。"},"semanticMap":{"core":{"en":"A flag on the summit, with worn boots and a used-up plan at its base","cn":"山顶的旗，以及旗下的磨破的鞋与翻烂的计划本"},"chain":["TO A HEAD","FINISH","ACCOMPLISH","RESULT","MEASURED LEVEL","RECOGNITION"],"branches":[{"senses":"01 · 02","en":"The act and the object: finishing the climb, and the flag that remains.","cn":"动作与物件：完成攀登，与留下的旗。"},{"senses":"03","en":"School measurement: scores and degrees turn achievement into comparable numbers.","cn":"学校的测量：分数与学历把成就变成可比的数字。"},{"senses":"04 · 06","en":"Completion at two scales: a public process finished, and a private step taken.","cn":"两种尺度的完成：公共流程结束，与私人一步迈出。"},{"senses":"07 · 08","en":"The inner and outer reward: a feeling, and a medal.","cn":"内在与外在回报：一种感受，与一枚奖章。"},{"senses":"05","en":"Beyond the scale: a record is effort measured to an unprecedented height.","cn":"刻度之外：纪录是努力被量到前所未有的高度。"}]},"affixes":{"intro":{"en":"Achievement's family is built on the verb achieve: the adjective of possibility, the person, and the two prefixes under- and over- that measure performance against expectation.","cn":"achievement 的词族建立在动词 achieve 上：可能性形容词、指人名词，以及衡量表现是否达预期的 under- 与 over- 两个前缀。"},"latinIntro":{"en":"The base is Old French achever, from à chief 'to a head', with chief from Latin caput. The noun suffix -ment is Latin -mentum. The word is therefore French in form with a Latin head inside it.","cn":"词基是古法语 achever，来自 à chief“到头”，其中 chief 出自拉丁语 caput。名词后缀 -ment 是拉丁语 -mentum。因此这个词是法语外形，内里藏着一颗拉丁语的“头”。"},"items":[{"word":"achievement","structure":"achieve + -ment (result noun)","meaning":"the act or result of reaching a goal","meaningCN":"达成目标的行为或结果","example":"The award honoured her achievement.","exampleCN":"这个奖项表彰了她的成就。"},{"word":"achieve","structure":"Old French achever (to a head)","meaning":"to reach a goal through effort","meaningCN":"经过努力达到目标","example":"They achieved what seemed impossible.","exampleCN":"他们做到了看似不可能的事。"},{"word":"achievable","structure":"achieve + -able (adjective)","meaning":"possible to reach","meaningCN":"可实现的","example":"The target is achievable this year.","exampleCN":"这个目标今年可以实现。"},{"word":"achiever","structure":"achieve + -er (agent)","meaning":"a person who achieves","meaningCN":"有成就的人","example":"She is a high achiever.","exampleCN":"她是一个高成就者。"},{"word":"underachievement","structure":"under- (below) + achievement","meaning":"performance below ability","meaningCN":"成绩低于能力；未充分发挥","example":"The school studies underachievement in boys.","exampleCN":"这所学校研究男生的学业低表现。"},{"word":"overachievement","structure":"over- (beyond) + achievement","meaning":"performance beyond expectation","meaningCN":"超出预期的成就","example":"Overachievement can hide anxiety.","exampleCN":"超常成就可能掩盖焦虑。"},{"word":"achieve","structure":"a- + chief (head)","meaning":"to bring to a head","meaningCN":"推到头部；完成","example":"The old verb meant 'to finish'.","exampleCN":"这个古动词意为“完成”。"},{"word":"chief","structure":"Latin caput (head)","meaning":"leader; principal","meaningCN":"首领；主要的","example":"Chief keeps the 'head' image.","exampleCN":"chief 保留着“头”的画面。"},{"word":"cape","structure":"Latin caput (head)","meaning":"a headland; a cloak","meaningCN":"海角；披肩","example":"Cape also descends from caput.","exampleCN":"cape 也源自 caput。"}],"latinEntries":[{"word":"caput","structure":"Latin noun","meaning":"head","meaningCN":"头","example":"Caput is inside à chief and chief.","exampleCN":"caput 藏在 à chief 与 chief 里。"},{"word":"ad caput","structure":"ad (to) + caput (head)","meaning":"to the head, to the top","meaningCN":"到头；到顶端","example":"The French phrase à chief descends from this idea.","exampleCN":"法语短语 à chief 源自这一概念。"},{"word":"chef","structure":"French from Latin caput","meaning":"head, leader; cook","meaningCN":"首领；厨师长","example":"Chef is the same 'head' word in French.","exampleCN":"chef 是法语中同一个“头”词。"}]}},{"word":"acidic","ipa_uk":"/əˈsɪdɪk/","ipa_us":"/əˈsɪdɪk/","definition_zh":"酸性的；酸味的；尖刻的；酸绿的","definition_en":"having the properties of an acid, tasting sour, or sharply critical in tone","core_image":"舌尖被柠檬刺了一下，金属表面冒出细密气泡","scene":"实验台上，一片石灰石被滴上醋，表面冒出细密气泡，试纸转成红色。Vinegar on limestone bubbles and turns the paper red, and the cut lemon beside it is acidic too.","sceneCN":"这里 acidic 是「酸性的」（第 1 个义项：具有酸的化学性质）；句意：醋滴在石灰石上起泡、试纸变红，旁边切开的柠檬也是酸性的。图中可辨识物件：石灰石、滴管、气泡、pH 试纸、柠檬。","pos":[{"tag":"adj.","zh":"酸性的；含酸的"},{"tag":"adj.","zh":"酸味的"},{"tag":"adj.","zh":"尖刻的；带酸味的（言辞）"}],"collocations":[{"phrase":"acidic soil","zh":"酸性土壤"},{"phrase":"acidic solution","zh":"酸性溶液"},{"phrase":"acidic taste","zh":"酸味"},{"phrase":"acidic water","zh":"酸性水"},{"phrase":"acidic deposition","zh":"酸性沉降"}],"forms":[{"label":"比较级（更酸）","form":"more acidic"},{"label":"最高级（最酸）","form":"most acidic"},{"label":"名词（加 -ity）","form":"acidity"}],"derivatives":[{"word":"acid","pos":"n./adj.","zh":"酸；酸性的"},{"word":"acidity","pos":"n.","zh":"酸度；酸性"},{"word":"acidify","pos":"v.","zh":"使酸化；变酸"},{"word":"acidification","pos":"n.","zh":"酸化过程"},{"word":"nonacidic","pos":"adj.","zh":"非酸性的"}],"senses":[{"no":"01","title":"Having the chemistry of an acid","titleCN":"具有酸的化学性质","definition":"in chemistry, having a pH below 7 and able to react with a base","definitionCN":"化学中指 pH 低于 7，能与碱反应","example":"The solution turned acidic after the gas was added.","exampleCN":"通入气体后，溶液变成酸性。","why":"Acid comes from Latin acidus 'sour', from acere 'to be sour'. Chemistry keeps the taste word but replaces the tongue with a scale: acidic now means a pH reading, not a sensation.","whyCN":"acid 来自拉丁语 acidus“酸的”，再上溯 acere“发酸”。化学保留了味觉词，却用刻度取代了舌头：acidic 现在指 pH 读数，而不是感觉。"},{"no":"02","title":"Sour to the taste","titleCN":"尝起来发酸","definition":"having a sharp sour taste, like lemon or vinegar","definitionCN":"具有尖锐的酸味，如柠檬或醋","example":"The unripe fruit is too acidic to eat raw.","exampleCN":"未熟的果实太酸，不能生吃。","why":"This is the oldest layer: acidus is literally 'sour'. Before chemistry, the word named what the mouth does when it tightens, and the suffix -ic simply makes the quality an adjective.","whyCN":"这是最古老的一层：acidus 字面就是“酸的”。在化学之前，这个词命名的是嘴收紧时的反应，而后缀 -ic 只是把这个性质变成形容词。"},{"no":"03","title":"Corrosive or etching","titleCN":"有腐蚀性或蚀刻力","definition":"able to dissolve metal, stone, or other material through chemical reaction","definitionCN":"能通过化学反应溶解金属、石头或其他材料","example":"Acidic cleaners can damage marble surfaces.","exampleCN":"酸性清洁剂会损伤大理石表面。","why":"Sourness and corrosion are the same chemical power seen at two scales: the tongue feels it, the stone gives way. The adjective extends from taste to damage because acids remove material.","whyCN":"酸味与腐蚀是同一种化学力量在两个尺度上的表现：舌头感觉到它，石头则为它让路。形容词从味觉扩展到破坏，因为酸会移走材料。"},{"no":"04","title":"Sharp in tone","titleCN":"语气尖刻","definition":"of speech or writing, sharply critical and biting","definitionCN":"指言辞尖锐批评、带刺","example":"Her acidic review of the novel spared nothing.","exampleCN":"她对这部小说的尖刻评论毫不留情。","why":"A sour taste makes the face contract; a sour remark makes the listener contract. The metaphor is old and physical: acidity in the mouth becomes acidity in the voice.","whyCN":"酸味让脸皱起来；酸话让听者皱眉。这个比喻古老而身体化：嘴里的酸变成声音里的酸。"},{"no":"05","title":"Low-pH soil","titleCN":"低 pH 的土壤","definition":"of soil, having a low pH that affects which plants can grow","definitionCN":"指土壤 pH 偏低，影响可生长的植物种类","example":"Blueberries grow best in acidic soil.","exampleCN":"蓝莓在酸性土壤中长得最好。","why":"Agriculture turns the chemical scale into a land quality. Acidic soil is not merely sour; it is a habitat with a restricted list of possible crops, so the word becomes agronomic.","whyCN":"农业把化学刻度变成土地品质。酸性土壤不只是“酸”，它是一种只容许有限作物生存的生境，因此这个词成了农学词。"},{"no":"06","title":"Acid deposition in the environment","titleCN":"环境中的酸性沉降","definition":"of rain, fog, or deposition, containing acids formed from pollution","definitionCN":"指雨、雾或沉降物含有污染形成的酸","example":"Acidic rain slowly leached nutrients from the forest floor.","exampleCN":"酸性雨水慢慢淋失了林地养分。","why":"Environmental science compounds the adjective with weather. The phrase keeps the chemical sense but adds a source: pollution turns ordinary rain into an acidic agent that works over decades.","whyCN":"环境科学把这个形容词与天气组合。这个短语保留化学义，又加上来源：污染把普通雨水变成一种以数十年为尺度起作用的酸性介质。"},{"no":"07","title":"Acid-forming in the body","titleCN":"体内成酸的","definition":"of food or metabolism, tending to produce acid rather than alkaline conditions","definitionCN":"指食物或代谢倾向产生酸，而非碱性环境","example":"High-protein diets are described as acidic.","exampleCN":"高蛋白饮食被描述为偏酸性。","why":"Nutrition uses the adjective for a net effect rather than a taste: a food can be alkaline in the mouth and acidic after metabolism. The word now measures a process, not a flavour.","whyCN":"营养学用这个形容词表示净效应，而不是味道：一种食物入口可以是碱性，代谢后却偏酸。这个词此时衡量过程，而不是风味。"},{"no":"08","title":"A bright, synthetic colour","titleCN":"刺目的合成色","definition":"of a colour, unnaturally bright and sharp, especially a vivid green or yellow","definitionCN":"指颜色不自然地鲜亮刺眼，尤指鲜绿或鲜黄","example":"The poster used an acidic green that hurt the eyes.","exampleCN":"海报用了一种刺眼的酸绿，看得眼睛发痛。","why":"Twentieth-century colour writing borrows the mouth's reaction for the eye's: an acidic shade is one that seems to sting. The metaphor is synaesthetic, but it keeps the original 'sharp' core.","whyCN":"20 世纪的色彩写作把嘴的反应借给眼睛：酸色就是看起来会刺人的颜色。这个比喻是通感的，但仍保留最原始的“尖锐”核心。"}],"etymology":{"intro":{"en":"Acidic is a derived adjective: acid plus the Latin suffix -ic. Acid goes back to Latin acidus 'sour', from acere 'to be sour', and the deeper root is the PIE word for 'sharp'.","cn":"acidic 是派生形容词：acid 加拉丁后缀 -ic。acid 上溯拉丁语 acidus“酸的”，来自 acere“发酸”，更深的词根是原始印欧语中表示“尖锐”的词。"},"items":[{"era":"LATIN","en":"Acidus 'sour, tart' comes from acere 'to be sour, to be sharp'. The same family gives acer 'sharp' and acies 'edge'.","cn":"acidus“酸的、尖酸的”来自 acere“发酸、尖锐”。同一词族还给出 acer“尖锐的”与 acies“刃”。"},{"era":"PIE *AK-","en":"The root is generally reconstructed as PIE *ak- 'sharp, pointed', seen in Latin acer and Greek akis 'point'. The asterisk marks a reconstructed form.","cn":"其词根一般重构为原始印欧语 *ak-“尖锐、带尖”，见于拉丁语 acer 与希腊语 akis“尖”。星号表示重构形式。"},{"era":"-IC","en":"The suffix -ic comes from Latin -icus and Greek -ikos, meaning 'pertaining to'. It turns the noun acid into an adjective describing its quality.","cn":"后缀 -ic 来自拉丁语 -icus 与希腊语 -ikos，意为“与……有关的”。它把名词 acid 变成描述其性质的形容词。"},{"era":"17C.","en":"Chemistry adopts acid for the class of sour substances, and acidic appears for the quality. The taste sense is now backed by reactions and, later, by pH.","cn":"17 世纪，化学用 acid 指一类酸味物质，acidic 则指其性质。味觉义此时有了反应作为依据，后来又有 pH。"},{"era":"19C.–20C.","en":"The adjective spreads to soil, rain, metabolism, and finally to colour and tone. Each extension keeps the 'sharp, biting' core rather than the laboratory definition.","cn":"19 至 20 世纪，这个形容词扩展到土壤、雨水、代谢，最后到颜色与语气。每次扩展保留的都是“尖锐、刺人”的核心，而不是实验室定义。"}]},"similar":{"note":{"en":"The first group shares the acid- shape or the same 'sharp' root; the second compares words for sour and biting qualities.","cn":"第一组共享 acid- 外形或同一“尖锐”词根；第二组比较表示“酸与尖刻”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"acid","ipa":"/ˈæsɪd/","tag":"base noun","definition":"a sour chemical substance. It is the noun behind acidic and names the class.","definitionCN":"一种酸味化学物质。它是 acidic 背后的名词，命名这一类物质。"},{"word":"acidity","ipa":"/əˈsɪdəti/","tag":"derived noun","definition":"the degree of acid strength. It is the abstract noun of the same adjective.","definitionCN":"酸的程度。它是同一形容词的抽象名词。"},{"word":"acute","ipa":"/əˈkjuːt/","tag":"same root","definition":"sharp, severe, or sudden. It comes from the same 'sharp' root but describes severity, not sourness.","definitionCN":"尖锐的、严重的或急性的。它来自同一“尖锐”词根，但描述严重程度，而非酸味。"},{"word":"acrid","ipa":"/ˈækrɪd/","tag":"same root","definition":"bitter or pungent in smell or taste. It shares the sharp root but stresses a harsh, stinging quality.","definitionCN":"气味或味道苦涩刺鼻。它共享尖锐词根，但强调刺人的 harsh 感。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sour","ipa":"/saʊə/","tag":"taste","definition":"having a tart taste, or turned bad. It is the everyday taste word, while acidic is technical or literary.","definitionCN":"有酸味，或变坏。它是日常味觉词，而 acidic 更技术化或文学化。"},{"word":"tart","ipa":"/tɑːt/","tag":"pleasantly sour","definition":"pleasantly sharp in taste. It is milder and often approving, unlike acidic which can imply damage.","definitionCN":"味道清爽地酸。它更温和，常带赞许，而 acidic 可暗示损害。"},{"word":"corrosive","ipa":"/kəˈrəʊsɪv/","tag":"damage","definition":"able to eat away material. It stresses the destructive effect, while acidic names the chemical quality.","definitionCN":"能侵蚀材料。它强调破坏效果，而 acidic 命名化学性质。"},{"word":"biting","ipa":"/ˈbaɪtɪŋ/","tag":"tone","definition":"sharply critical or cold. It is used of wind and remarks, while acidic often keeps a flavour metaphor.","definitionCN":"尖刻批评或寒冷刺骨。它用于风与言语，而 acidic 常保留味道比喻。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on the 'sharp' root and the pH scale, then three abstract images about a quality that stings.","cn":"先用五个围绕“尖锐”词根与 pH 刻度的挂钩，再用三个关于“会刺人的性质”的抽象画面。"},"normal":[{"en":"acid, acute, acrid all share 'sharp': acid is sharp on the tongue, acute is sharp in severity, acrid is sharp in the nose.","cn":"acid、acute、acrid 都共享“尖锐”：acid 尖在舌上，acute 尖在程度上，acrid 尖在鼻子里。"},{"en":"-ic means 'pertaining to': acidic is simply 'of the nature of acid'.","cn":"-ic 意为“与……有关”：acidic 就是“具有酸的性质”。"},{"en":"pH below 7 is the modern definition; the tongue's contraction is the old one.","cn":"pH 低于 7 是现代定义；舌头皱起是古老定义。"},{"en":"Acidic soil is a chemical fact that becomes a farming constraint.","cn":"酸性土壤是一个化学事实，随后变成农业限制。"},{"en":"An acidic remark and an acidic green both sting, one the ear and one the eye.","cn":"尖刻的话与刺眼的酸绿都会刺人，一个刺耳，一个刺眼。"}],"abstract":[{"en":"Acidity is a scale, but the word never quite forgets the face it makes.","cn":"酸性是一个刻度，但这个词从未完全忘记它让人做出的表情。"},{"en":"The same property that flavours food can dissolve stone: intensity is a matter of dose.","cn":"给食物调味的同一性质也能溶解石头：强度只是剂量问题。"},{"en":"Borrowing a taste word for a tone shows how quickly the body becomes a metaphor.","cn":"把味觉词借给语气，说明身体多快就变成了比喻。"}]},"examples":[{"en":"The lake became acidic after decades of industrial fallout.","cn":"经过数十年工业沉降，湖水变酸了。"},{"en":"Add lime to acidic soil before planting.","cn":"种植前要在酸性土壤中加石灰。"},{"en":"His acidic wit made even his targets laugh.","cn":"他尖刻的机智连被他调侃的人都笑了。"}],"dict_mnemonic":{"note":"acid（酸）+ -ic（形容词）→ 酸性的。词根 ac- 是“尖锐”：酸在舌上尖，酸话在耳里尖。","text":"acid（酸）+ -ic（与……有关的）→ 有酸的性质 → 酸性的、酸味的、尖刻的","word":"acidic"},"root":"拉丁 acidus“酸的”＝acere“发酸、尖锐”（原始印欧语 *ak-“尖锐”）→ 英语 acid + 拉丁-希腊后缀 -ic → acidic。","sensesIntro":{"en":"The senses start with the pH scale, then return to the tongue, move to corrosion, to a biting tone, to soil and rain, to metabolism, and finally to a colour that seems to sting the eye.","cn":"这些义项从 pH 刻度开始，回到舌头，再转到腐蚀、尖刻语气、土壤与雨水、代谢，最后落到一种似乎会刺眼的颜色。"},"semanticMap":{"core":{"en":"A drop of vinegar on limestone, the surface hissing into foam","cn":"一滴醋落在石灰石上，表面嘶嘶起泡"},"chain":["SHARP","SOUR","ACID","LOW pH","CORROSIVE","BITING"],"branches":[{"senses":"01","en":"THE SCALE: a pH reading below seven.","cn":"刻度：pH 读数低于七。"},{"senses":"03 · 06","en":"Damage at two scales: a cleaner eating marble, and rain eating a forest floor.","cn":"两种尺度的损害：清洁剂侵蚀大理石，雨水侵蚀林地。"},{"senses":"04 · 08","en":"Synaesthetic bite: a sour remark and a sour green.","cn":"通感的刺：酸话与酸绿。"},{"senses":"05 · 07","en":"Acidity as a condition: soil that limits crops, and a diet that shifts the body's balance.","cn":"作为条件的酸性：限制作物的土壤，与改变身体平衡的饮食。"},{"senses":"02","en":"THE TONGUE: sourness is chemistry’s first blow to taste.","cn":"舌头：酸味是化学打给味觉的第一记。"}]},"affixes":{"intro":{"en":"Acidic's family is built on acid: the abstract noun of degree, the verb and process of making acid, and the negative form.","cn":"acidic 的词族建立在 acid 上：程度抽象名词、使酸化的动词与过程，以及否定形式。"},"latinIntro":{"en":"Latin acidus 'sour' plus the suffix -icus gives the adjective pattern behind acidic. The same 'sharp' root produces acer, acute, and acrid, so the family is wider than the chemistry lab.","cn":"拉丁语 acidus“酸的”加后缀 -icus 给出 acidic 背后的形容词模式。同一个“尖锐”词根还产生 acer、acute、acrid，因此这个词族比化学实验室更广。"},"items":[{"word":"acidic","structure":"acid + -ic (adjective)","meaning":"having the quality of acid","meaningCN":"具有酸的性质","example":"The soil here is acidic.","exampleCN":"这里的土壤是酸性的。"},{"word":"acid","structure":"Latin acidus (sour)","meaning":"a sour substance; sour","meaningCN":"酸；酸性的","example":"Acid reacts with metal.","exampleCN":"酸与金属反应。"},{"word":"acidity","structure":"acidic + -ity (abstract noun)","meaning":"the degree of acid strength","meaningCN":"酸度；酸性","example":"Winemakers measure acidity carefully.","exampleCN":"酿酒师会仔细测量酸度。"},{"word":"acidify","structure":"acid + -ify (verb)","meaning":"to make or become acid","meaningCN":"使酸化；变酸","example":"Pollution acidifies the rain.","exampleCN":"污染使雨水酸化。"},{"word":"acidification","structure":"acidify + -ation (process noun)","meaning":"the process of becoming acid","meaningCN":"酸化过程","example":"Ocean acidification threatens reefs.","exampleCN":"海洋酸化威胁珊瑚礁。"},{"word":"nonacidic","structure":"non- (not) + acidic","meaning":"not acid in quality","meaningCN":"非酸性的","example":"Use a nonacidic cleaner on stone.","exampleCN":"石材上要用非酸性清洁剂。"},{"word":"acute","structure":"Latin acutus (sharpened)","meaning":"sharp, severe, or sudden","meaningCN":"尖锐的；严重的；急性的","example":"Acute keeps the 'sharp' core.","exampleCN":"acute 保留着“尖锐”核心。"},{"word":"acrid","structure":"Latin acer (sharp) + -id","meaning":"bitter or pungent","meaningCN":"苦涩刺鼻的","example":"The smoke was acrid.","exampleCN":"烟味刺鼻。"},{"word":"acerbic","structure":"Latin acerbus (harsh) + -ic","meaning":"sharp and bitter in tone","meaningCN":"尖酸刻薄的","example":"His acerbic humour stung.","exampleCN":"他尖酸的幽默扎人。"}],"latinEntries":[{"word":"acidus","structure":"acere (be sour) + -idus","meaning":"sour, tart","meaningCN":"酸的；尖酸的","example":"Acidus is the source of acid.","exampleCN":"acidus 是 acid 的来源。"},{"word":"acere","structure":"Latin verb","meaning":"to be sour or sharp","meaningCN":"发酸；尖锐","example":"Acere connects acid and acute.","exampleCN":"acere 连接 acid 与 acute。"},{"word":"acer","structure":"Latin adjective","meaning":"sharp, keen","meaningCN":"尖锐的；敏锐的","example":"Acer is behind acrid and acerbic.","exampleCN":"acer 是 acrid 与 acerbic 背后的词。"}]}},{"word":"acknowledgment","ipa_uk":"/əkˈnɒlɪdʒmənt/","ipa_us":"/əkˈnɑːlɪdʒmənt/","definition_zh":"承认；认可；致谢；回执","definition_en":"a statement that something is true or that someone deserves credit, or a signal confirming that something has been received","core_image":"收到一封重要的信，回一张签收条：我看见了，也承认它到了","scene":"会议结束时，主持人把每个人的贡献逐一点名。Naming each person's contribution out loud was a public acknowledgment, and the receipt on the screen did the same for a message.","sceneCN":"这里 acknowledgment 是「承认、公开认可」（第 3 个义项：认可某人的贡献）；句意：把每个人的贡献当众点名是一种公开认可，屏幕上那条回执对一条消息做的也是同一件事。图中可辨识物件：会议桌、点名名单、屏幕上的回执提示、记录本。","pos":[{"tag":"n.","zh":"承认；认可（可数/不可数）"},{"tag":"n.","zh":"致谢；鸣谢"},{"tag":"n.","zh":"回执；收到的确认"}],"collocations":[{"phrase":"acknowledgment of receipt","zh":"收到回执"},{"phrase":"in acknowledgment of","zh":"为答谢；作为对……的承认"},{"phrase":"formal acknowledgment","zh":"正式承认"},{"phrase":"acknowledgments section","zh":"（书籍）致谢部分"},{"phrase":"message acknowledgment","zh":"消息回执"}],"forms":[{"label":"单数（一次承认）","form":"acknowledgment"},{"label":"复数（多次承认／致谢）","form":"acknowledgments"},{"label":"动词（原形）","form":"acknowledge"},{"label":"过去分词（被动／完成）","form":"acknowledged"}],"derivatives":[{"word":"acknowledge","pos":"v.","zh":"承认；确认收到；致谢"},{"word":"acknowledged","pos":"adj.","zh":"公认的；已确认的"},{"word":"unacknowledged","pos":"adj.","zh":"未被承认的；未得回应的"},{"word":"acknowledgement","pos":"n.","zh":"（英式拼法）承认；致谢"},{"word":"acknowledgeable","pos":"adj.","zh":"可被承认的（罕用）"}],"senses":[{"no":"01","title":"Admitting that something is true","titleCN":"承认某事为真","definition":"a statement or act showing that one accepts a fact as true","definitionCN":"表明自己接受某一事实为真的陈述或行为","example":"There was a general acknowledgment that the plan had failed.","exampleCN":"大家普遍承认这个计划失败了。","why":"Acknowledge began as oncnāwan, 'to recognize, know'. To admit a fact is to say that you now know it and will not pretend otherwise, so the noun is a public form of recognition.","whyCN":"acknowledge 最初是 oncnāwan“认出、知道”。承认一个事实，就是说自己已经知道，并且不再假装不知道，因此这个名词是“认出”的公开形式。"},{"no":"02","title":"Admitting one's own fault","titleCN":"承认自己的过错","definition":"an admission that one has done something wrong or made a mistake","definitionCN":"承认自己做了错事或犯了错误","example":"His acknowledgment of the error came only after the audit.","exampleCN":"审计之后，他才承认了这个错误。","why":"Recognition turns inward: the known fact is one's own act. The -ledge ending, borrowed from knowledge, reinforces the sense of owning a piece of knowledge about oneself.","whyCN":"“认出”转向内部：被知道的事实是自己的行为。借自 knowledge 的 -ledge 词尾加强了“拥有一份关于自己的知识”的感觉。"},{"no":"03","title":"Recognizing someone's contribution","titleCN":"认可某人的贡献","definition":"an expression of credit or respect for a person's help, status, or achievement","definitionCN":"对某人的帮助、地位或成就表示认可与尊重","example":"The director received an award in acknowledgment of her years of service.","exampleCN":"这位主管因多年服务而获奖，得到认可。","why":"What is recognized here is not a fact but a person's worth. Acknowledgment makes the recognition public, which is why it often appears with awards, prefaces, and speeches.","whyCN":"这里被“认出”的不是事实，而是某人的价值。承认使这种认出变得公开，因此它常与奖项、前言、演讲一起出现。"},{"no":"04","title":"Confirming that something arrived","titleCN":"确认某物已送达","definition":"a formal signal that a letter, message, or delivery has been received","definitionCN":"表示信件、消息或货物已经收到的正式信号","example":"Please return the signed form as acknowledgment of receipt.","exampleCN":"请把签好的表格寄回，作为收到回执。","why":"Communication needs proof that the message crossed the gap. Acknowledgment becomes a token: the words 'I have it' are replaced by a document or a signal that can be checked later.","whyCN":"通信需要证明消息越过了那道缝。acknowledgment 于是成为凭证：“我收到了”这句话被一份可事后核查的文件或信号取代。"},{"no":"05","title":"The thanks page of a book","titleCN":"书籍的致谢页","definition":"a section, usually at the front or back of a book, thanking those who helped","definitionCN":"书籍前后用于感谢帮助者的部分","example":"She names the archivists in the acknowledgments.","exampleCN":"她在致谢部分列出了档案管理员的姓名。","why":"A book is a collaborative object that carries one author's name. The acknowledgments section is where the hidden recognition is printed, turning private gratitude into a permanent public record.","whyCN":"书是协作的产物，却只署一个作者的名字。致谢部分就是隐藏的“认出”被印出来的地方，把私人的感激变成永久的公共记录。"},{"no":"06","title":"A signal that data arrived","titleCN":"数据到达的信号","definition":"in computing, a message sent back to confirm that data or a request was received","definitionCN":"计算机中返回以确认数据或请求已收到的消息","example":"The server waits for an acknowledgment before sending the next packet.","exampleCN":"服务器在发送下一个数据包前会等待一个确认。","why":"Networks inherit the postal receipt: a packet without an acknowledgment is only a guess. The word's old sense of 'confirming arrival' becomes a protocol event.","whyCN":"网络继承了邮政回执：没有确认的数据包只是一次猜测。这个词古老的“确认抵达”义变成一个协议事件。"},{"no":"07","title":"Diplomatic recognition","titleCN":"外交上的承认","definition":"a formal act by which one state recognizes another state or government","definitionCN":"一国正式承认另一国或其政府的行为","example":"The treaty was followed by mutual acknowledgment of the new state.","exampleCN":"条约签订后，双方承认了这个新国家。","why":"At the level of states, recognition is a legal act with consequences: a government that is acknowledged can sign, sue, and be sued. The noun becomes an instrument of international law.","whyCN":"在国家层面，承认是有法律后果的行为：被承认的政府可以签约、起诉与被起诉。这个名词于是成为国际法工具。"},{"no":"08","title":"A legal admission of a claim","titleCN":"法律上对债务或主张的承认","definition":"a formal statement, especially in law, admitting that a debt, right, or claim exists","definitionCN":"法律中正式承认债务、权利或主张存在","example":"The debtor signed an acknowledgment of the debt.","exampleCN":"债务人签署了一份债务承认书。","why":"Law converts a spoken admission into evidence. An acknowledgment stops the person from later denying the claim, so the word becomes a written act rather than a state of mind.","whyCN":"法律把口头承认变成证据。承认书使当事人日后不能否认该主张，因此这个词变成书面行为，而不是心理状态。"}],"etymology":{"intro":{"en":"Acknowledgment is a double derivative: the verb acknowledge plus -ment. Acknowledge itself is a Middle English reshaping of Old English oncnāwan 'to recognize', with -ledge inserted by analogy with knowledge.","cn":"acknowledgment 是双重派生：动词 acknowledge 加 -ment。acknowledge 本身是中古英语对古英语 oncnāwan“认出”的改写，其中 -ledge 是类比 knowledge 插进去的。"},"items":[{"era":"OLD ENGLISH","en":"Oncnāwan means 'to know, recognize, understand', from on- plus cnāwan 'to know'. The core is recognition, not confession.","cn":"oncnāwan 意为“知道、认出、理解”，由 on- 加 cnāwan“知道”构成。核心是“认出”，不是“忏悔”。"},{"era":"MIDDLE ENGLISH","en":"The verb becomes aknowen, then acknowledge. The -ledge element is inserted in the 16th century by association with knowledge; it is not an independent suffix with meaning.","cn":"这个动词先作 aknowen，后作 acknowledge。16 世纪时，因与 knowledge 联想而插入 -ledge 成分；它并不是一个有独立含义的后缀。"},{"era":"-MENT","en":"The noun suffix -ment comes from Latin -mentum through French and forms nouns of action or result. Acknowledgment can therefore name both the act of recognizing and the document that records it.","cn":"名词后缀 -ment 经法语来自拉丁语 -mentum，构成动作或结果名词。因此 acknowledgment 既能指“认出”的行为，也能指记录它的文件。"},{"era":"16C.–17C.","en":"The noun spreads from personal admission to formal receipt and to credit for help. Legal and commercial uses fix the documentary sense.","cn":"16 至 17 世纪，这个名词从个人承认扩展到正式回执与对帮助的致谢。法律与商业用法固定了它的文书义。"},{"era":"20C.","en":"Computing adds the packet acknowledgment, and diplomacy keeps the state-recognition sense. The word now covers a feeling, a paragraph, a receipt, and a protocol signal.","cn":"20 世纪，计算机增加了数据包确认，外交保留国家承认义。这个词如今覆盖一种态度、一段文字、一张回执，以及一个协议信号。"}]},"similar":{"note":{"en":"The first group shares the acknowledg- shape or the same 'know' root; the second compares words for admitting and recognizing.","cn":"第一组共享 acknowledg- 外形或同一“知道”词根；第二组比较表示“承认与认可”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"acknowledge","ipa":"/əkˈnɒlɪdʒ/","tag":"base verb","definition":"to admit or confirm. It is the verb behind the noun.","definitionCN":"承认或确认。它是该名词背后的动词。"},{"word":"acknowledged","ipa":"/əkˈnɒlɪdʒd/","tag":"derived form","definition":"recognized or confirmed. It is the past participle used as an adjective.","definitionCN":"被认可的或已确认的。它是过去分词作形容词。"},{"word":"knowledge","ipa":"/ˈnɒlɪdʒ/","tag":"analogy source","definition":"what one knows. Its -ledge was borrowed into acknowledge by analogy, not as a suffix.","definitionCN":"所知之事。它的 -ledge 是被类比借进 acknowledge 的，并不是后缀。"},{"word":"unacknowledged","ipa":"/ˌʌnəkˈnɒlɪdʒd/","tag":"derived form","definition":"not admitted or not responded to. The prefix un- negates the participle.","definitionCN":"未被承认或未得回应的。前缀 un- 否定该分词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"admission","ipa":"/ədˈmɪʃn/","tag":"confession","definition":"a statement that something is true, especially something damaging. It is more focused on guilt than acknowledgment.","definitionCN":"某事实为真的陈述，尤指不利事实。它比 acknowledgment 更聚焦于过错。"},{"word":"recognition","ipa":"/rɪˈkɒɡnɪʃn/","tag":"status","definition":"the act of identifying or honouring someone. It is broader and can mean mere identification.","definitionCN":"识别或表彰某人的行为。它更宽泛，也可仅指识别。"},{"word":"confirmation","ipa":"/ˌkɒnfəˈmeɪʃn/","tag":"receipt","definition":"proof that an arrangement or message is valid. It is the documentary cousin of acknowledgment.","definitionCN":"安排或消息有效的证明。它是 acknowledgment 的文书近亲。"},{"word":"credit","ipa":"/kredɪt/","tag":"attribution","definition":"public acknowledgement of someone's contribution. It focuses on who gets the praise.","definitionCN":"公开认可某人的贡献。它聚焦于谁获得赞誉。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on 'recognize' and the borrowed -ledge, then three abstract images about making knowledge public.","cn":"先用五个围绕“认出”与借来的 -ledge 的挂钩，再用三个关于“把知道变成公开”的抽象画面。"},"normal":[{"en":"acknowledge began as 'recognize': on + cnāwan, to know. Admitting is saying 'I know this' out loud.","cn":"acknowledge 最初是“认出”：on + cnāwan，知道。承认就是大声说“我知道这件事”。"},{"en":"The -ledge is borrowed from knowledge: it looks like a suffix but is a piece of analogy.","cn":"-ledge 是从 knowledge 借来的：它看起来像后缀，其实是一块类比。"},{"en":"A receipt is an acknowledgment in paper form; a packet acknowledgment is the same in wire form.","cn":"回执是纸上的承认；数据包确认是线路上的同一种承认。"},{"en":"Book acknowledgments make gratitude permanent, which is why they are printed rather than spoken.","cn":"书籍致谢让感激永久化，因此它被印出来，而不是说出来。"},{"en":"British spelling often uses acknowledgement; American usually keeps acknowledgment.","cn":"英式拼法常用 acknowledgement；美式通常保留 acknowledgment。"}],"abstract":[{"en":"Recognition is the first form of justice: to acknowledge someone is to admit they exist in the record.","cn":"认可是正义的第一种形式：承认某人，就是承认他存在于记录之中。"},{"en":"An acknowledgment does not create the fact; it only removes the possibility of pretending.","cn":"承认并不创造事实，它只是移除了“假装不知道”的可能。"},{"en":"Every message needs a return signal, and every person needs one too.","cn":"每条消息都需要一个返回信号，每个人也需要一个。"}]},"examples":[{"en":"The report opens with an acknowledgment of the limits of the data.","cn":"报告开头承认了数据的局限。"},{"en":"She received a letter in acknowledgment of her donation.","cn":"她收到一封感谢捐款的信。"},{"en":"The system logs every acknowledgment from the remote device.","cn":"系统记录远程设备发回的每一次确认。"}],"dict_mnemonic":{"note":"a + knowledge 的影子 + -ment：把“知道”摆到明面上 → 承认；收到消息回一句，就是回执；在书末谢人，就是致谢。","text":"a-（使）+ know（知道）+ -ledge（借自 knowledge）+ -ment → 使知道成为公开确认 → 承认、致谢、回执","word":"acknowledgment"},"root":"古英语 oncnāwan“认出、知道”（on- + cnāwan）→ 中古英语 aknowen → 16 世纪类比 knowledge 插入 -ledge → acknowledge + -ment（拉丁 -mentum）→ acknowledgment。","sensesIntro":{"en":"The senses all make recognition public: a fact admitted, a fault owned, a person credited, a delivery confirmed, a helper thanked in print, a packet confirmed, a state recognized, and a debt admitted in writing.","cn":"所有义项都在把“认出”变成公开：被承认的事实、被认领的过错、被致谢的人、被确认的送达、被印出来感谢的帮助者、被确认的数据包、被承认的国家，以及被书面承认的债务。"},"semanticMap":{"core":{"en":"A signed receipt returned to the sender: I have it, and I will not pretend otherwise","cn":"寄回给发件人的签收条：我收到了，也不会假装没有"},"chain":["KNOW","RECOGNIZE","ADMIT","CERTIFY","THANK","RECOGNIZE STATUS"],"branches":[{"senses":"01","en":"TOWARD A FACT: recognising and accepting something true.","cn":"对事实：认出并接受一件真事。"},{"senses":"03 · 05","en":"Public credit: spoken thanks, and the printed acknowledgments page.","cn":"公开的致谢：口头感谢，与印出的致谢页。"},{"senses":"04 · 06","en":"Confirmation in two media: paper receipt and network signal.","cn":"两种媒介的确认：纸质回执与网络信号。"},{"senses":"07 · 08","en":"Legal recognition: a state acknowledged, and a debt admitted.","cn":"法律上的承认：被承认的国家，与被承认的债务。"},{"senses":"02","en":"TOWARD ONESELF: admitting a fault is an inward reckoning.","cn":"对自己：承认过错是向内的一次交代。"}]},"affixes":{"intro":{"en":"Acknowledgment's family is small and transparent: the verb, its participle, the negative, the variant spelling, and the rare adjective of possibility.","cn":"acknowledgment 的词族小而透明：动词、分词、否定形式、变体拼法，以及罕见的可能性形容词。"},"latinIntro":{"en":"The core is native Old English cnāwan 'to know'. Latin contributes only the noun suffix -mentum through French; the -ledge element is an English analogical insertion, not a Latin affix.","cn":"核心是本族古英语 cnāwan“知道”。拉丁语只经法语贡献了名词后缀 -mentum；-ledge 成分是英语的类比插入，不是拉丁词缀。"},"items":[{"word":"acknowledgment","structure":"acknowledge + -ment (result noun)","meaning":"an act of admitting, crediting, or confirming","meaningCN":"承认、致谢或确认的行为","example":"The acknowledgment arrived by post.","exampleCN":"回执通过邮件寄到。"},{"word":"acknowledge","structure":"on- + cnāwan (know) + analogical -ledge","meaning":"to admit, confirm, or thank","meaningCN":"承认；确认；致谢","example":"He acknowledged the mistake.","exampleCN":"他承认了错误。"},{"word":"acknowledged","structure":"acknowledge + -ed (participle)","meaning":"recognized or confirmed","meaningCN":"公认的；已确认的","example":"She is an acknowledged expert.","exampleCN":"她是公认的专家。"},{"word":"unacknowledged","structure":"un- (not) + acknowledged","meaning":"not admitted or not answered","meaningCN":"未被承认的；未得回应的","example":"The letter remained unacknowledged.","exampleCN":"那封信一直没有回音。"},{"word":"acknowledgement","structure":"British spelling variant","meaning":"same as acknowledgment","meaningCN":"与 acknowledgment 同义的英式拼法","example":"The British form keeps the e.","exampleCN":"英式拼法保留了 e。"},{"word":"acknowledgeable","structure":"acknowledge + -able","meaning":"able to be acknowledged","meaningCN":"可被承认的（罕用）","example":"The claim is acknowledgeable in principle.","exampleCN":"这一主张原则上可以被承认。"},{"word":"knowledge","structure":"know + -ledge","meaning":"what is known","meaningCN":"知识；所知之事","example":"The -ledge of knowledge was borrowed.","exampleCN":"knowledge 的 -ledge 被借用了。"},{"word":"know","structure":"Old English cnāwan","meaning":"to have knowledge of","meaningCN":"知道；认识","example":"Know is the oldest layer of acknowledge.","exampleCN":"know 是 acknowledge 最古老的一层。"},{"word":"recognize","structure":"re- (again) + cognizance (know)","meaning":"to identify as known","meaningCN":"认出；认可","example":"Recognize is the closest synonym of acknowledge.","exampleCN":"recognize 是 acknowledge 最接近的同义词。"}],"latinEntries":[{"word":"cognoscere","structure":"co- (together) + gnoscere (know)","meaning":"to learn, get to know","meaningCN":"得知；认识","example":"Cognoscere stands behind recognize.","exampleCN":"cognoscere 是 recognize 背后的词。"},{"word":"mentum","structure":"Latin noun suffix","meaning":"result or means of an action","meaningCN":"动作的结果或手段","example":"-mentum became English -ment.","exampleCN":"-mentum 变成英语 -ment。"},{"word":"agnitio","structure":"ad- + gnoscere + -tio","meaning":"recognition, acknowledgment","meaningCN":"认出；承认","example":"Agnitio is a Latin cousin of acknowledgment.","exampleCN":"agnitio 是 acknowledgment 的拉丁近亲。"}]}},{"word":"acquaintance","ipa_uk":"/əˈkweɪntəns/","ipa_us":"/əˈkweɪntəns/","definition_zh":"熟人；相识；了解；略微知道","definition_en":"a person one knows slightly, the state of knowing someone or something, or a limited familiarity with a subject","core_image":"走廊里点头、停半步、寒暄两句就各自走开——知道名字，却不知道对方住在哪里","scene":"走廊里两人点头、停半步、寒暄两句就各自走开。They knew each other's names and offices but not where the other lived; to each other they were no more than an acquaintance.","sceneCN":"这里 acquaintance 是「熟人、点头之交」（第 1 个义项：略微认识的人）；句意：他们知道彼此的名字和办公室，却不知道对方住在哪里；对彼此来说，只算个熟人。图中可辨识物件：走廊、两人、点头动作、各自离开的方向。","pos":[{"tag":"n.","zh":"熟人；相识的人（可数）"},{"tag":"n.","zh":"认识；相识（不可数）"},{"tag":"n.","zh":"了解；略微的知识"}],"collocations":[{"phrase":"make acquaintance","zh":"结识；认识"},{"phrase":"a nodding acquaintance","zh":"点头之交；略知一二"},{"phrase":"business acquaintance","zh":"生意上的熟人"},{"phrase":"acquaintance with","zh":"对……的了解"},{"phrase":"old acquaintance","zh":"旧相识"}],"forms":[{"label":"单数（一个熟人）","form":"acquaintance"},{"label":"复数（多个熟人）","form":"acquaintances"},{"label":"动词（原形）","form":"acquaint"}],"derivatives":[{"word":"acquaint","pos":"v.","zh":"使认识；使熟悉"},{"word":"acquainted","pos":"adj.","zh":"相识的；熟悉的"},{"word":"acquaintanceship","pos":"n.","zh":"相识关系"},{"word":"unacquainted","pos":"adj.","zh":"不认识的；不熟悉的"},{"word":"reacquaint","pos":"v.","zh":"重新认识；使重新熟悉"}],"senses":[{"no":"01","title":"A person known slightly","titleCN":"略微认识的人","definition":"someone one knows by name or by sight but not as a close friend","definitionCN":"知道名字或见过面、但并非密友的人","example":"He is an acquaintance from the gym, not a friend.","exampleCN":"他是我在健身房认识的熟人，不是朋友。","why":"Acquaint comes from a causative Latin verb meaning 'make known'. An acquaintance is the product of that act: someone has been made known to you, but only to the edge of familiarity.","whyCN":"acquaint 来自一个使动拉丁动词，意为“使知道”。acquaintance 就是这一动作的产物：有人被“让你知道”了，但只到熟悉的边缘。"},{"no":"02","title":"The state of knowing someone","titleCN":"相识的状态","definition":"the relationship or condition of knowing a person, especially without closeness","definitionCN":"认识某人的关系或状态，尤指并不亲近","example":"Their acquaintance began at a conference in Vienna.","exampleCN":"他们的相识始于维也纳的一次会议。","why":"The noun can name the relation rather than the person. This is the abstract side of the same causative verb: making known creates a link, and the link itself is called an acquaintance.","whyCN":"这个名词可以命名关系，而不是人。这是同一使动动词的抽象面：使知道创造了一条连接，而这条连接本身就叫 acquaintance。"},{"no":"03","title":"Familiarity with a subject","titleCN":"对某领域的了解","definition":"a working knowledge of a field, enough to use it but not expert depth","definitionCN":"对某一领域的可用知识，足够使用但未达专家深度","example":"Her acquaintance with Latin is enough to read inscriptions.","exampleCN":"她对拉丁语的了解足以读铭文。","why":"The object of 'making known' can be a subject as well as a person. Here acquaintance measures a body of knowledge, and the word implies a threshold rather than mastery.","whyCN":"“使知道”的对象可以是学科，也可以是人。这里的 acquaintance 衡量的是知识量，暗示的是“入门门槛”，而不是精通。"},{"no":"04","title":"The act of first meeting","titleCN":"初次结识","definition":"the occasion of being introduced to someone, in phrases such as make acquaintance","definitionCN":"被介绍给某人的场合，用于 make acquaintance 等短语","example":"I made his acquaintance at the reception.","exampleCN":"我在招待会上结识了他。","why":"The phrase keeps the causative force visible: you 'make' an acquaintance because the relationship is something brought into being, not merely discovered.","whyCN":"这个短语让使动力量保持可见：你“make”一个 acquaintance，因为这段关系是被造就的，而不只是被发现的。"},{"no":"05","title":"Superficial knowledge","titleCN":"浅层的了解","definition":"a slight or partial knowledge of something, often in the phrase a nodding acquaintance","definitionCN":"对某事物的轻微或部分了解，常见于 a nodding acquaintance","example":"I have only a nodding acquaintance with statistics.","exampleCN":"我对统计学只是略知一二。","why":"A nod is the smallest public recognition: enough to acknowledge a face, not enough to converse. The phrase turns that gesture into a measure of knowledge, and the word becomes almost an insult when applied to a field.","whyCN":"点头是最小的公开“认出”：足以承认一张脸，却不足以交谈。这个短语把这个动作变成知识尺度，用于学科时几乎带贬义。"},{"no":"06","title":"A circle of useful contacts","titleCN":"一群可用的人脉","definition":"the body of people one knows across a profession or social circle, viewed collectively","definitionCN":"在职业或社交圈中认识的一群人，作为整体看待","example":"Her acquaintances in publishing helped her find a printer.","exampleCN":"她在出版界认识的熟人帮她找到了印刷商。","why":"A set of weak links is still a network. The word can collect acquaintances into a resource, which is why it often appears in business contexts without the warmth of friendship.","whyCN":"一组弱连接仍然是一张网。这个词可以把熟人聚成一种资源，因此在商业语境中常出现，却不带友谊的温度。"},{"no":"07","title":"Knowledge of a fact","titleCN":"对事实的知晓","definition":"in formal or older usage, awareness or knowledge of a fact or circumstance","definitionCN":"正式或较早用法中，对事实或情况的知晓","example":"The lawyer had acquaintance with the details of the case.","exampleCN":"这位律师了解案件的细节。","why":"This sense is closest to the verb's original 'make known': to have acquaintance with a fact is to have been informed of it. Modern English often prefers 'knowledge' here.","whyCN":"这个义项最接近动词原义“使知道”：have acquaintance with a fact 就是“被告知过这件事”。现代英语在此更常用 knowledge。"},{"no":"08","title":"Experience of something difficult","titleCN":"对艰难事物的体验","definition":"personal familiarity with an experience, especially one that changes one's judgment","definitionCN":"对某种经历的个人熟悉，尤指会改变判断的经历","example":"Acquaintance with danger makes some people cautious and others reckless.","exampleCN":"与危险打过交道，会让一些人谨慎，让另一些人鲁莽。","why":"Here acquaintance is not information but lived contact. The word extends from knowing a person to knowing a condition, and the old 'make known' becomes 'be brought face to face with'.","whyCN":"这里的 acquaintance 不是信息，而是亲身接触。这个词从“认识一个人”扩展到“认识一种处境”，古老的“使知道”变成“被带到面对面”。"}],"etymology":{"intro":{"en":"Acquaintance is a derived noun: acquaint plus -ance. Acquaint comes from Old French acointier, from Late Latin accognitare 'make known', built on cognoscere 'to know'.","cn":"acquaintance 是派生名词：acquaint 加 -ance。acquaint 来自古法语 acointier，再上溯晚期拉丁语 accognitare“使知道”，其词基是 cognoscere“知道”。"},"items":[{"era":"LATE LATIN","en":"Accognitare is a causative verb: ad- 'to' plus cognoscere 'to know', so it means 'cause to know, make acquainted'. The causative shape explains why acquaintance implies an act of introduction.","cn":"accognitare 是使动词：ad-“向”加 cognoscere“知道”，意为“使知道、使相识”。使动形态解释了为什么 acquaintance 隐含一次介绍行为。"},{"era":"OLD FRENCH","en":"Acointier 'to make known, get to know' passes into Middle English as aquenten and then acquaint. The reflexive 'acquaint oneself with' preserves the original 'make known to oneself'.","cn":"古法语 acointier“使知道、结识”进入中古英语作 aquenten，后作 acquaint。反身形式 acquaint oneself with 保留原义“使自己知道”。"},{"era":"-ANCE","en":"The suffix -ance comes from Latin -antia, forming nouns of state or quality. It turns the verb into the state of being acquainted, and then by concrete shift into the person known.","cn":"后缀 -ance 来自拉丁语 -antia，构成状态或性质名词。它把动词变成“相识的状态”，再经具体化转指被认识的人。"},{"era":"16C.","en":"Acquaintance is recorded both as the relation and as the person. The phrase make acquaintance fixes the act of introduction.","cn":"16 世纪，acquaintance 既记录关系，也记录人。短语 make acquaintance 固定了“介绍结识”的行为。"},{"era":"18C.–19C.","en":"The word develops its graded sense: nodding acquaintance, slight acquaintance, a wide acquaintance. Familiarity becomes measurable, and the noun can even describe knowledge of a field.","cn":"18 至 19 世纪，这个词发展出程度义：点头之交、略微相识、交游广阔。熟悉变得可测量，名词甚至可以描述对某一领域的知识。"}]},"similar":{"note":{"en":"The first group shares the acquaint- shape or the 'know' root; the second compares words for people one knows and familiarity.","cn":"第一组共享 acquaint- 外形或“知道”词根；第二组比较表示“认识的人与熟悉”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"acquaint","ipa":"/əˈkweɪnt/","tag":"base verb","definition":"to make someone familiar with something. It is the verb behind the noun.","definitionCN":"使某人熟悉某事。它是该名词背后的动词。"},{"word":"acquainted","ipa":"/əˈkweɪntɪd/","tag":"derived form","definition":"familiar with someone or something. It is the past participle used as an adjective.","definitionCN":"与某人或某事熟悉的。它是过去分词作形容词。"},{"word":"unacquainted","ipa":"/ˌʌnəˈkweɪntɪd/","tag":"derived form","definition":"not familiar. The prefix un- negates the participle.","definitionCN":"不熟悉的。前缀 un- 否定该分词。"},{"word":"cognizance","ipa":"/ˈkɒɡnɪzəns/","tag":"same root","definition":"awareness or knowledge. It comes from the same cognoscere, but belongs to legal and formal registers.","definitionCN":"知晓或认识。它来自同一个 cognoscere，但属法律与正式语域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"friend","ipa":"/frend/","tag":"closeness","definition":"a person one knows, likes, and trusts. It implies emotional closeness that acquaintance excludes.","definitionCN":"认识、喜欢并信任的人。它含情感亲近，而 acquaintance 不含。"},{"word":"contact","ipa":"/ˈkɒntækt/","tag":"usefulness","definition":"a person one knows for practical purposes. It is more instrumental than acquaintance.","definitionCN":"因实际目的而认识的人。它比 acquaintance 更工具化。"},{"word":"familiarity","ipa":"/ˌfæmɪliˈærəti/","tag":"knowledge","definition":"the state of knowing something well. It is broader and can be positive, while acquaintance often signals a limit.","definitionCN":"对某事物了解得好的状态。它更宽泛且可带正面色彩，而 acquaintance 常标记限度。"},{"word":"colleague","ipa":"/kəˈliːɡ/","tag":"work","definition":"a person one works with. It names a role, not a degree of closeness.","definitionCN":"与自己在同一处工作的人。它命名角色，而不是亲近程度。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on 'make known' and the -ance noun, then three abstract images about the edge of familiarity.","cn":"先用五个围绕“使知道”与 -ance 名词的挂钩，再用三个关于“熟悉边缘”的抽象画面。"},"normal":[{"en":"acquaint is causative: to acquaint is to make someone known, so an acquaintance is someone who has been made known to you.","cn":"acquaint 是使动：使某人被知道，因此 acquaintance 就是被“让你知道”的人。"},{"en":"The -ance turns the act into a state: from 'introduce' to 'the relation of knowing'.","cn":"-ance 把动作变成状态：从“介绍”变成“相识关系”。"},{"en":"A nodding acquaintance is measured by the smallest recognition: a nod, not a conversation.","cn":"点头之交由最小的“认出”来衡量：一个点头，而不是一场交谈。"},{"en":"Acquaintance with Latin is knowledge of a subject; acquaintance with danger is experience of a condition.","cn":"acquaintance with Latin 是对学科的知识；acquaintance with danger 是对处境的体验。"},{"en":"Business acquaintances are contacts, not friends: the word keeps its distance.","cn":"生意上的熟人是联系人，不是朋友：这个词保持距离。"}],"abstract":[{"en":"An acquaintance is a person known enough to greet and not enough to rely on.","cn":"熟人就是熟到可以打招呼、却没熟到可以依靠的人。"},{"en":"Weak ties are the bridges of a society: acquaintances connect circles that friends never could.","cn":"弱连接是社会的桥：熟人连接了朋友永远连不到的圈子。"},{"en":"Familiarity has a threshold, and acquaintance names the near side of it.","cn":"熟悉有一个门槛，而 acquaintance 命名门槛的近侧。"}]},"examples":[{"en":"She invited acquaintances from work but not her closest friends.","cn":"她请了工作上的熟人，却没请最亲近的朋友。"},{"en":"My acquaintance with the city is limited to two streets.","cn":"我对这座城市的了解只限于两条街。"},{"en":"They renewed an old acquaintance at the station.","cn":"他们在车站重叙旧识。"}],"dict_mnemonic":{"note":"acquaint（使知道）+ -ance（状态）→ 被“让你知道”的人或关系 → 熟人、相识、了解。点头之交就是最低限度的 acquaintance。","text":"ac-（向）+ cognoscere（知道）→ 使知道 → acquaintance：熟人、相识、略知","word":"acquaintance"},"root":"晚期拉丁 accognitare“使知道”（ad- + cognoscere 知道）→ 古法语 acointier → 中古英语 acquaint + -ance（拉丁 -antia）→ acquaintance。","sensesIntro":{"en":"The senses start with the person known slightly, move to the relationship, to knowledge of a field, to the act of meeting, to superficial knowledge, to a circle of contacts, to knowledge of a fact, and finally to lived experience of a condition.","cn":"这些义项从略微认识的人开始，转到相识关系、对领域的了解、结识的动作、浅层知识、一群人脉、对事实的知晓，最后落到对某种处境的亲身经验。"},"semanticMap":{"core":{"en":"A nod in a corridor: enough recognition to stop for a second, not enough to stay","cn":"走廊里的一个点头：足以停下半秒，不足以留下"},"chain":["MAKE KNOWN","BE INTRODUCED","KNOW SLIGHTLY","RELATION","FAMILIARITY","LIMITED KNOWLEDGE"],"branches":[{"senses":"01 · 02","en":"The person and the relation: someone known, and the link itself.","cn":"人与关系：被认识的人，与连接本身。"},{"senses":"03 · 07","en":"Knowledge of a field and of a fact: two objects of 'being made known'.","cn":"对领域与对事实的知识：“被使知道”的两种对象。"},{"senses":"04 · 05","en":"The beginning and the limit: first introduction, and the nodding minimum.","cn":"起点与限度：初次结识，与点头的最低量。"},{"senses":"06","en":"A circle of weak ties: the people one knows in a profession or social world.","cn":"一群弱连接：职业或社交圈里认识的一群人。"},{"senses":"08","en":"Acquaintance with a condition: having faced hardship is itself a kind of knowing it.","cn":"与处境的相识：经历过艰难，便算与它熟识。"}]},"affixes":{"intro":{"en":"Acquaintance's family is built on acquaint: the participle, the negative, the relationship noun, and the verb of renewing familiarity.","cn":"acquaintance 的词族建立在 acquaint 上：分词、否定形式、关系名词，以及重新建立熟悉的动词。"},"latinIntro":{"en":"Late Latin accognitare 'make known' is ad- plus cognoscere 'know'. The noun suffix -antia becomes English -ance. The causative prefix and the 'know' root together explain the word's mixture of introduction and limited knowledge.","cn":"晚期拉丁语 accognitare“使知道”是 ad- 加 cognoscere“知道”。名词后缀 -antia 变成英语 -ance。使动前缀与“知道”词根共同解释了这个词为何同时含“介绍”与“有限知识”。"},"items":[{"word":"acquaintance","structure":"acquaint + -ance (state noun)","meaning":"a slight acquaintance; the state of knowing","meaningCN":"熟人；相识；了解","example":"He is an old acquaintance.","exampleCN":"他是一位旧识。"},{"word":"acquaint","structure":"ad- + cognoscere (know)","meaning":"to make familiar","meaningCN":"使认识；使熟悉","example":"Please acquaint me with the facts.","exampleCN":"请让我了解事实。"},{"word":"acquainted","structure":"acquaint + -ed (participle)","meaning":"familiar with","meaningCN":"相识的；熟悉的","example":"Are you acquainted with her?","exampleCN":"你认识她吗？"},{"word":"acquaintanceship","structure":"acquaintance + -ship (relationship)","meaning":"the state of being acquaintances","meaningCN":"相识关系","example":"Their acquaintanceship lasted years.","exampleCN":"他们的相识关系持续了多年。"},{"word":"unacquainted","structure":"un- (not) + acquainted","meaning":"not familiar","meaningCN":"不认识的；不熟悉的","example":"I am unacquainted with the procedure.","exampleCN":"我不熟悉这个程序。"},{"word":"reacquaint","structure":"re- (again) + acquaint","meaning":"to make familiar again","meaningCN":"使重新熟悉；重新认识","example":"The reunion reacquainted old friends.","exampleCN":"聚会让老友重新熟络。"},{"word":"cognoscere","structure":"co- + gnoscere (know)","meaning":"to learn, know","meaningCN":"得知；认识","example":"Cognoscere is the root of acquaint.","exampleCN":"cognoscere 是 acquaint 的词根。"},{"word":"cognizance","structure":"cognoscere + -ance","meaning":"awareness, jurisdiction","meaningCN":"知晓；管辖权","example":"The court took cognizance of the case.","exampleCN":"法院受理了此案。"},{"word":"notice","structure":"noscere (know) + -itia","meaning":"attention, announcement","meaningCN":"注意；通知","example":"Notice shares the 'know' root.","exampleCN":"notice 共享“知道”词根。"}],"latinEntries":[{"word":"cognoscere","structure":"co- (together) + gnoscere (know)","meaning":"to get to know, learn","meaningCN":"逐渐知道；认识","example":"Cognoscere is behind acquaint and cognition.","exampleCN":"cognoscere 是 acquaint 与 cognition 背后的词。"},{"word":"accognitare","structure":"ad- (to) + cognoscere","meaning":"to make known, cause to know","meaningCN":"使知道；使认识","example":"Accognitare is the causative source.","exampleCN":"accognitare 是使动来源。"},{"word":"notitia","structure":"noscere + -itia","meaning":"knowledge, notice","meaningCN":"知识；通知","example":"Notitia is a cousin through the same root.","exampleCN":"notitia 是同一词根的近亲。"}]}},{"word":"adaptation","ipa_uk":"/ˌædæpˈteɪʃn/","ipa_us":"/ˌædæpˈteɪʃn/","definition_zh":"适应；改编；改编作品；改造","definition_en":"the process of changing to fit new conditions, a trait that helps survival, or a work rewritten for a new medium","core_image":"把一件不合身的外套改到合身：收腰、改袖，穿的人终于能抬手","scene":"同一周，一位编剧把小说改成舞台剧。The playwright cut the narration and added dialogue, and the stage version was an adaptation of a novel that half the audience had read.","sceneCN":"这里 adaptation 是「改编作品」（第 4 个义项：由原作改写而成的作品）；句意：编剧删去叙述、加上对白，这个舞台版本是一部小说的改编作品，半数观众读过原著。图中可辨识物件：剧本、舞台、旧外套、针线。","pos":[{"tag":"n.","zh":"适应；适应性变化（可数/不可数）"},{"tag":"n.","zh":"改编；改编作品"},{"tag":"n.","zh":"改造；改装"}],"collocations":[{"phrase":"adaptation to","zh":"对……的适应"},{"phrase":"film adaptation","zh":"电影改编"},{"phrase":"evolutionary adaptation","zh":"演化适应"},{"phrase":"adaptation process","zh":"适应过程"},{"phrase":"climate adaptation","zh":"气候适应"}],"forms":[{"label":"单数（一次适应／一部改编）","form":"adaptation"},{"label":"复数（多种适应／改编）","form":"adaptations"},{"label":"动词（原形）","form":"adapt"},{"label":"过去分词（被动／完成）","form":"adapted"}],"derivatives":[{"word":"adapt","pos":"v.","zh":"适应；改编；改装"},{"word":"adaptable","pos":"adj.","zh":"能适应的；可改编的"},{"word":"adaptability","pos":"n.","zh":"适应能力"},{"word":"adapted","pos":"adj.","zh":"已适应的；改编的"},{"word":"maladaptation","pos":"n.","zh":"适应不良；错误适应"}],"senses":[{"no":"01","title":"A biological trait that fits","titleCN":"生物上的适应特征","definition":"an inherited feature that helps an organism survive and reproduce in its environment","definitionCN":"帮助生物在环境中生存繁衍的遗传特征","example":"Thick fur is an adaptation to extreme cold.","exampleCN":"厚毛是对极寒的一种适应。","why":"Adaptare means 'fit to', from aptus 'fit'. Biology turns the verb into a countable thing: the fit itself becomes a trait, and natural selection is the tailor.","whyCN":"adaptare 意为“使适合”，来自 aptus“合适的”。生物学把动词变成可数之物：适合本身成为一个特征，而自然选择就是那位裁缝。"},{"no":"02","title":"The process of adjusting","titleCN":"适应的过程","definition":"the gradual process by which an organism or group becomes suited to new conditions","definitionCN":"生物或群体逐渐变得适合新条件的过程","example":"Adaptation to high altitude takes several weeks.","exampleCN":"适应高海拔需要数周时间。","why":"The same word names the process and the product, because fitting is both an activity and a result. In physiology the process sense dominates: the body changes over time, not in a single step.","whyCN":"同一个词既命名过程，也命名产物，因为“适合”既是活动也是结果。在生理学中过程义占主导：身体随时间改变，而不是一步到位。"},{"no":"03","title":"A change in behaviour","titleCN":"行为上的调整","definition":"a change in behaviour that helps an individual cope with a new situation","definitionCN":"帮助个体应对新情境的行为改变","example":"Feeding at night is a behavioural adaptation to heat.","exampleCN":"夜间觅食是对高温的一种行为适应。","why":"Not all fitting is anatomical; an animal can also change what it does. The word extends from body to habit, and adaptation becomes something learned or chosen within a lifetime.","whyCN":"并非所有适合都是解剖上的；动物也能改变自己的行为。这个词从身体扩展到习惯，adaptation 于是成为个体在生命周期内学会或选择的东西。"},{"no":"04","title":"A work rewritten for a new medium","titleCN":"改编作品","definition":"a book, play, or story reworked for film, stage, television, or another medium","definitionCN":"为电影、舞台、电视或其他媒介重新改写的书、戏剧或故事","example":"The film adaptation moved the story to the 1970s.","exampleCN":"这部改编电影把故事移到了 1970 年代。","why":"A novel does not fit a screen, so it must be refitted: scenes cut, dialogue added. The word's tailoring image is unusually literal here, because the new medium has a different shape.","whyCN":"小说不合屏幕的“身”，必须重新改：删场景、加对白。这个词的裁缝画面在这里异常字面，因为新媒介有另一种“身形”。"},{"no":"05","title":"Technical modification","titleCN":"技术改装","definition":"a change made to a device, system, or building so that it can serve a new purpose","definitionCN":"为使装置、系统或建筑服务于新用途而作的改变","example":"The adaptation of the engine to hydrogen took years.","exampleCN":"把引擎改装为烧氢花了数年。","why":"Engineering treats a design as a garment that must fit a new body, whether fuel, climate, or user. Adaptation here is deliberate and documented, unlike biological drift.","whyCN":"工程把设计当作一件必须贴合新“身体”的衣服，不论新身体是燃料、气候还是用户。这里的适应是有意且被记录的，不同于生物的漂变。"},{"no":"06","title":"Sensory adaptation","titleCN":"感官适应","definition":"the diminishing response of a sense organ after prolonged exposure to a stimulus","definitionCN":"感觉器官在长时间暴露于刺激后反应减弱","example":"Adaptation to darkness takes about twenty minutes.","exampleCN":"眼睛适应黑暗大约需要二十分钟。","why":"The eye and ear recalibrate to a constant stimulus, turning down the volume of what does not change. This is fitting in the strictest sense: the response matches the new baseline.","whyCN":"眼睛与耳朵会针对恒定刺激重新校准，把不变之物的音量调低。这是最严格意义上的“适合”：反应匹配了新的基线。"},{"no":"07","title":"Cultural adaptation","titleCN":"文化适应","definition":"the process of learning and adjusting to the norms of a new culture or group","definitionCN":"学习并调整以适应新文化或群体规范的过程","example":"Cultural adaptation includes learning new greetings and new silences.","exampleCN":"文化适应包括学习新的问候方式和新的沉默方式。","why":"A person entering a new society must refit conduct, not anatomy. The word keeps the same 'fit to' structure but the material is behaviour, and the tailor is the community.","whyCN":"进入新社会的人必须重新裁剪行为，而不是解剖结构。这个词保留“使适合”的结构，只是材料变成行为，裁缝变成社群。"},{"no":"08","title":"Climate adaptation","titleCN":"气候适应","definition":"practical measures taken to reduce the harm of climate change that is already occurring","definitionCN":"为减轻已在发生的气候变化危害而采取的实际措施","example":"The city's climate adaptation plan raises the seawall.","exampleCN":"这座城市的气候适应计划加高了海堤。","why":"Policy distinguishes adaptation (living with the change) from mitigation (preventing it). The word becomes a planning category, and the 'fit' is between infrastructure and a future environment.","whyCN":"政策区分 adaptation（与变化共处）与 mitigation（阻止变化）。这个词成为一个规划类别，而“适合”发生在基础设施与未来环境之间。"}],"etymology":{"intro":{"en":"Adaptation is a derived noun: adapt plus -ation. Adapt comes from Latin adaptare 'fit to', from ad- 'to' plus aptare 'fit', and aptus 'fit, suited'. The word's core is tailoring, not survival.","cn":"adaptation 是派生名词：adapt 加 -ation。adapt 来自拉丁语 adaptare“使适合”，由 ad-“向”加 aptare“使合适”，词根 aptus“合适的”。这个词的核心是裁剪，而不是生存。"},"items":[{"era":"LATIN","en":"Adaptare means 'to fit, adjust, make suitable', from ad- 'to' plus aptare 'to fit', itself from aptus 'fit, suited'. The image is a thing made to match another thing.","cn":"adaptare 意为“使适合、调整、使相配”，由 ad-“向”加 aptare“使合适”，后者出自 aptus“合适的”。画面是一件东西被做成与另一件相配。"},{"era":"17C.","en":"English borrows adapt, first meaning 'to fit or suit'. The noun adaptation follows in the same period, naming the act of fitting.","cn":"17 世纪，英语借入 adapt，最初意为“使适合、相配”。名词 adaptation 同期出现，命名“使适合”的行为。"},{"era":"-ATION","en":"The suffix -ation comes from Latin -atio, the noun ending of action and result. It turns adapt into both the process and the product, which is why a trait and a film can both be called an adaptation.","cn":"后缀 -ation 来自拉丁语 -atio，是动作与结果的名词词尾。它把 adapt 变成过程与产物两者，因此一个特征和一部电影都能叫 adaptation。"},{"era":"18C.–19C.","en":"Biology adopts the word for traits and processes that fit organisms to environments. The tailor becomes natural selection.","cn":"18 至 19 世纪，生物学采用这个词，指使生物与环境相合的特征与过程。裁缝变成自然选择。"},{"era":"19C.–20C.","en":"Literature and media use adaptation for works moved to a new medium, while engineering and policy use it for deliberate modification. The same fit-image scales across fields.","cn":"19 至 20 世纪，文学与媒介用 adaptation 指移到新媒介的作品，工程与政策则用它指有意的改装。同一个“适合”画面跨越领域。"}]},"similar":{"note":{"en":"The first group shares the adapt- shape or the 'fit' root; the second compares words for adjustment and reworking.","cn":"第一组共享 adapt- 外形或“适合”词根；第二组比较表示“调整与改写”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adapt","ipa":"/əˈdæpt/","tag":"base verb","definition":"to change to fit. It is the verb behind adaptation.","definitionCN":"为适合而改变。它是 adaptation 背后的动词。"},{"word":"adaptive","ipa":"/əˈdæptɪv/","tag":"derived form","definition":"able to adapt. It is a different suffix: -ive, not -ation.","definitionCN":"能适应的。它用了不同后缀 -ive，而不是 -ation。"},{"word":"adaptable","ipa":"/əˈdæptəbl/","tag":"derived form","definition":"capable of being changed to fit. It adds -able to adapt.","definitionCN":"可被改变以适合的。它在 adapt 上加 -able。"},{"word":"adopt","ipa":"/əˈdɒpt/","tag":"spelling","definition":"to take as one's own. Its root is optare 'choose', not aptare 'fit'.","definitionCN":"采用；收养。其词根是 optare“选择”，不是 aptare“适合”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"adjustment","ipa":"/əˈdʒʌstmənt/","tag":"change","definition":"a small change made to fit a situation. It is often narrower and more mechanical than adaptation.","definitionCN":"为适应情境而作的小改变。它常比 adaptation 更窄、更机械。"},{"word":"modification","ipa":"/ˌmɒdɪfɪˈkeɪʃn/","tag":"alteration","definition":"a change to something's form or function. It stresses the act of altering rather than the resulting fit.","definitionCN":"对形态或功能的改变。它强调改动行为，而不是产生的适合。"},{"word":"version","ipa":"/ˈvɜːʃn/","tag":"media","definition":"a particular form of a work. It is broader than an adaptation and may not involve a change of medium.","definitionCN":"作品的某一形态。它比改编更宽，且未必涉及媒介转换。"},{"word":"acclimation","ipa":"/ˌæklɪˈmeɪʃn/","tag":"physiology","definition":"adjustment to a new climate or condition. It is narrower and usually physiological.","definitionCN":"对新气候或条件的调整。它更窄，通常指生理层面。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on aptus 'fit' and the -ation noun, then three abstract images about making one thing fit another.","cn":"先用五个围绕 aptus“合适”与 -ation 名词的挂钩，再用三个关于“让一物贴合另一物”的抽象画面。"},"normal":[{"en":"adapt = ad + aptus: to fit toward something, like taking in a garment at the waist.","cn":"adapt = ad + aptus：朝某物去适合，像把外套收腰。"},{"en":"-ation turns the fitting into both the process and the product: adapting and the adapted thing.","cn":"-ation 把“适合”变成过程与产物两者：适应行为与适应之物。"},{"en":"A film adaptation is a novel refitted to a screen; the seams are where scenes were cut.","cn":"电影改编是把小说改到屏幕上；接缝处就是删掉场景的地方。"},{"en":"Sensory adaptation turns down the volume of what does not change.","cn":"感官适应会把不变之物的音量调低。"},{"en":"Climate adaptation is the seawall; climate mitigation is the emissions cut. One fits, one prevents.","cn":"气候适应是海堤；气候减缓是减排。一个是“适合”，一个是“阻止”。"}],"abstract":[{"en":"Adaptation is survival by editing: what cannot be changed outside is met by a change inside.","cn":"适应是靠编辑来生存：外面改不了，就在里面改。"},{"en":"Every adaptation is also a loss: fitting one environment makes you less fit for another.","cn":"每次适应也是一种损失：适合一个环境，就较难适合另一个。"},{"en":"The word hides its tailor: we see the trait, not the long process that made it.","cn":"这个词藏起了裁缝：我们看见特征，却看不见做出它的漫长过程。"}]},"examples":[{"en":"The camel's hump is an adaptation to scarce water.","cn":"骆驼的驼峰是对缺水环境的一种适应。"},{"en":"The stage adaptation cut the novel's narrator entirely.","cn":"舞台改编把小说的叙述者整个删掉了。"},{"en":"Adaptation to the new software took the staff a month.","cn":"员工花了一个月适应新软件。"}],"dict_mnemonic":{"note":"adapt（使适合）+ -ation（过程/结果）→ 适应、改编。词根 aptus 是“合适”：裁缝把衣服改到合身，就是最字面的 adaptation。","text":"ad（向）+ aptus（合适）→ adaptare（使适合）→ adapt + -ation → 适应、改编、改造","word":"adaptation"},"root":"拉丁 adaptare“使适合”（ad- 向 + aptare 使合适，aptus 合适的）+ -ation（拉丁 -atio）→ 英语 adaptation（17 世纪）。","sensesIntro":{"en":"The senses all describe a fit: an inherited trait, the process of becoming suited, a behavioural change, a work refitted to a new medium, a technical modification, a sense organ recalibrating, cultural learning, and infrastructure adjusted to a changing climate.","cn":"所有义项都在描述一种“适合”：遗传特征、变得适合的过程、行为改变、改到新媒介的作品、技术改装、感官重新校准、文化学习，以及为变化气候调整的基础设施。"},"semanticMap":{"core":{"en":"A tailor taking in an old coat until the wearer can raise both arms","cn":"裁缝把旧外套收窄，直到穿的人能抬起双臂"},"chain":["FIT TO","ALTER","BECOME SUITED","TRAIT","REWORKED WORK","LIVING WITH CHANGE"],"branches":[{"senses":"01","en":"PRODUCT: a heritable trait that fits its environment.","cn":"产物：一个合身的遗传特征。"},{"senses":"03 · 06","en":"Adjustment inside a lifetime: changed behaviour, and a sense organ turned down.","cn":"生命周期内的调整：改变的行为，与调低音量的感官。"},{"senses":"04 · 05","en":"Deliberate refitting: a story moved to film, and an engine moved to new fuel.","cn":"有意的改装：故事移到电影，引擎移到新燃料。"},{"senses":"07 · 08","en":"Collective fitting: a person learning a culture, and a city learning a new climate.","cn":"集体性的适合：人学习一种文化，城市学习一种新气候。"},{"senses":"02","en":"PROCESS: adaptation is not one decision but a stretch of time in which fit is gradually achieved.","cn":"过程：适应不是一次决定，而是一段逐渐合身的时间。"}]},"affixes":{"intro":{"en":"Adaptation's family is built on adapt: the adjective of capability, the abstract noun of that capability, the participle, and the noun for a failed fit.","cn":"adaptation 的词族建立在 adapt 上：能力形容词、该能力的抽象名词、分词，以及表示“错误适应”的名词。"},"latinIntro":{"en":"Latin aptus 'fit, suited' gives aptare 'to fit', and ad- makes adaptare 'fit to'. English adds -ation for the action noun and -able/-ive for capability. The root is about matching, not about changing for its own sake.","cn":"拉丁语 aptus“合适的”给出 aptare“使合适”，ad- 构成 adaptare“使适合”。英语加 -ation 构成动作名词，加 -able/-ive 表示能力。这个词根讲的是“相配”，不是为变而变。"},"items":[{"word":"adaptation","structure":"adapt + -ation (action/result noun)","meaning":"the process or result of fitting","meaningCN":"适应的过程或结果；改编作品","example":"The adaptation of the play was faithful.","exampleCN":"这部戏剧改编很忠实。"},{"word":"adapt","structure":"ad- (to) + aptare (fit)","meaning":"to make suitable; to rework","meaningCN":"使适合；改编","example":"They adapted the house for a wheelchair.","exampleCN":"他们改装房子以便轮椅通行。"},{"word":"adaptable","structure":"adapt + -able (adjective)","meaning":"able to be changed to fit","meaningCN":"能适应的；可改装的","example":"The tool is adaptable to several tasks.","exampleCN":"这个工具可适应多种任务。"},{"word":"adaptability","structure":"adaptable + -ity (abstract noun)","meaning":"the capacity to adapt","meaningCN":"适应能力","example":"Adaptability is a survival advantage.","exampleCN":"适应能力是一种生存优势。"},{"word":"adapted","structure":"adapt + -ed (participle)","meaning":"made suitable or reworked","meaningCN":"已适应的；改编的","example":"The text is adapted for beginners.","exampleCN":"这篇文本是为初学者改写的。"},{"word":"maladaptation","structure":"mal- (badly) + adaptation","meaning":"a poor or harmful adjustment","meaningCN":"适应不良；错误适应","example":"The behaviour is a maladaptation.","exampleCN":"这种行为是一种适应不良。"},{"word":"apt","structure":"Latin aptus (fit)","meaning":"suitable; likely","meaningCN":"合适的；恰当的","example":"Apt keeps the 'fit' root.","exampleCN":"apt 保留“合适”词根。"},{"word":"aptitude","structure":"aptus + -itude","meaning":"natural ability or fitness","meaningCN":"天资；适宜性","example":"Aptitude is fitness for a task.","exampleCN":"aptitude 是对某项任务的适合。"},{"word":"adaptor","structure":"adapt + -or (agent/instrument)","meaning":"a device that fits one thing to another","meaningCN":"适配器；转接器","example":"The adaptor connects the plug to the socket.","exampleCN":"适配器把插头接到插座。"}],"latinEntries":[{"word":"aptus","structure":"Latin adjective","meaning":"fit, suited, appropriate","meaningCN":"合适的；相配的","example":"Aptus is the root of adapt.","exampleCN":"aptus 是 adapt 的词根。"},{"word":"aptare","structure":"aptus + -are (verb)","meaning":"to fit, adjust","meaningCN":"使合适；调整","example":"Aptare gives the verb inside adaptare.","exampleCN":"aptare 给出 adaptare 中的动词。"},{"word":"adaptare","structure":"ad- (to) + aptare","meaning":"to fit to, adjust","meaningCN":"使适合；调整","example":"Adaptare is the direct source of adapt.","exampleCN":"adaptare 是 adapt 的直接来源。"}]}},{"word":"adaptive","ipa_uk":"/əˈdæptɪv/","ipa_us":"/əˈdæptɪv/","definition_zh":"适应的；有适应能力的；可自我调节的","definition_en":"able to change in order to fit new conditions, or relating to the process of such change","core_image":"一把能随地形改变齿距的钥匙，插进去总能咬住锁芯","scene":"越野车驶过沙地、碎石与泥坑。The suspension softens on sand and hardens on gravel, and the car crosses all three surfaces without changing a single part, because the system is adaptive.","sceneCN":"这里 adaptive 是「能随环境自我调节的」（第 1 个义项：能适应新条件）；句意：悬挂在沙地上变软、在碎石上变硬，这辆车不换一个零件就通过三种地形，因为这套系统能自适应。图中可辨识物件：越野车、沙地、碎石、泥坑、变化中的悬挂。","pos":[{"tag":"adj.","zh":"适应的；有适应能力的"},{"tag":"adj.","zh":"自适应调节的"},{"tag":"adj.","zh":"（生物）适应性的"}],"collocations":[{"phrase":"adaptive system","zh":"自适应系统"},{"phrase":"adaptive behavior","zh":"适应行为"},{"phrase":"adaptive immunity","zh":"适应性免疫"},{"phrase":"adaptive reuse","zh":"适应性再利用（旧建筑改用途）"},{"phrase":"adaptive management","zh":"适应性管理"}],"forms":[{"label":"比较级（更具适应性）","form":"more adaptive"},{"label":"最高级（最具适应性）","form":"most adaptive"},{"label":"副词（加 -ly）","form":"adaptively"},{"label":"名词（加 -ness）","form":"adaptiveness"}],"derivatives":[{"word":"adapt","pos":"v.","zh":"适应；改编"},{"word":"adaptation","pos":"n.","zh":"适应；改编作品"},{"word":"adaptively","pos":"adv.","zh":"以适应的方式"},{"word":"adaptability","pos":"n.","zh":"适应能力"},{"word":"maladaptive","pos":"adj.","zh":"适应不良的"}],"senses":[{"no":"01","title":"Able to adjust to new conditions","titleCN":"能适应新条件","definition":"capable of changing behaviour or structure in order to fit a new situation","definitionCN":"能够改变行为或结构以适应新情境","example":"Small teams are more adaptive than large bureaucracies.","exampleCN":"小团队比大型官僚机构更具适应性。","why":"Adaptive is adapt plus -ive, 'tending to'. The suffix names a disposition rather than a completed act: something adaptive is built to keep fitting, not fitted once.","whyCN":"adaptive 是 adapt 加 -ive“倾向于”。这个后缀命名一种倾向，而不是一次完成的动作：adaptive 的东西被造出来是为了持续适合，而不是适合一次。"},{"no":"02","title":"A trait that raises fitness","titleCN":"提高适应度的性状","definition":"in biology, of a trait, increasing an organism's chance of survival and reproduction","definitionCN":"生物学中指性状提高生物生存与繁殖的机会","example":"Camouflage is adaptive in open grassland.","exampleCN":"在开阔草原上，伪装具有适应性。","why":"Evolution uses the adjective for whatever the environment rewards. 'Adaptive' does not mean 'changed' but 'changed in a way that pays', so the word carries an implicit judgement about fitness.","whyCN":"演化用这个形容词指环境所奖励的任何东西。adaptive 不是“改变过的”，而是“改变得有利的”，因此这个词隐含了对适应度的判断。"},{"no":"03","title":"An immune system that learns","titleCN":"会学习的免疫系统","definition":"of immunity, acquired after exposure and able to recognize a specific pathogen","definitionCN":"指暴露后获得、能识别特定病原体的免疫","example":"Adaptive immunity remembers the virus and responds faster next time.","exampleCN":"适应性免疫记住这种病毒，下次反应更快。","why":"The immune system literally adapts: it edits its repertoire after meeting an antigen. The word's 'fit to' core becomes a memory that is written into cells.","whyCN":"免疫系统确实在适应：遇到抗原后它会编辑自己的库。这个词“使适合”的核心变成写入细胞里的记忆。"},{"no":"04","title":"A system that responds to input","titleCN":"能对输入作出反应的系统","definition":"of software or machinery, changing its behaviour according to signals from its environment","definitionCN":"指软件或机械根据环境信号改变行为","example":"The adaptive controller adjusts the dose as the sensor readings change.","exampleCN":"自适应控制器随传感器读数变化调整剂量。","why":"Engineering makes the adjective technical: a system measures its own performance and corrects it. The fit is now a feedback loop, repeated many times a second.","whyCN":"工程使这个形容词技术化：系统测量自身表现并作出修正。此时的“适合”是一个反馈回路，每秒重复多次。"},{"no":"05","title":"Behaviour that meets a new situation","titleCN":"应对新情境的行为","definition":"of behaviour, flexible and appropriate to an unfamiliar or changing situation","definitionCN":"指行为灵活，适合陌生或变化中的情境","example":"Adaptive behaviour includes asking for help when a plan fails.","exampleCN":"适应行为包括在计划失败时寻求帮助。","why":"Here the flexible thing is not a body or a machine but a response. The word describes a repertoire that can be recombined, which is why it appears in psychology and education.","whyCN":"这里灵活的不是身体或机器，而是反应。这个词描述一套可以被重新组合的行为库，因此常见于心理学与教育学。"},{"no":"06","title":"Adaptive reuse of a building","titleCN":"旧建筑的适应性再利用","definition":"in architecture, the conversion of an old structure for a new use while keeping its fabric","definitionCN":"建筑中指保留旧结构主体、改用新用途","example":"The warehouse's adaptive reuse turned it into a library.","exampleCN":"这座仓库的适应性再利用把它变成了图书馆。","why":"A building cannot be redesigned from scratch without cost, so it is refitted. Adaptive reuse is the tailoring image at architectural scale: keep the coat, change its purpose.","whyCN":"建筑无法不计成本地推倒重来，因此被改装。适应性再利用是建筑尺度上的裁缝画面：保留外套，改变用途。"},{"no":"07","title":"Adaptive management","titleCN":"适应性管理","definition":"in policy and ecology, a way of managing that treats decisions as experiments and adjusts them as evidence arrives","definitionCN":"政策与生态学中把决策当作实验、随证据调整的管理方式","example":"Adaptive management let the park change its burn plan after the first results.","exampleCN":"适应性管理让公园在首批结果出来后修改了烧除计划。","why":"The word turns management into a loop rather than a plan. Each action produces information, and the next action is fitted to that information, so adaptation becomes institutional.","whyCN":"这个词把管理变成回路，而不是计划。每个行动产生信息，下一个行动再适合这些信息，于是适应成为制度性的。"},{"no":"08","title":"Adaptive radiation in evolution","titleCN":"演化中的适应辐射","definition":"in evolution, the rapid diversification of one lineage into many forms that fill different niches","definitionCN":"演化中指一个谱系迅速分化为许多形态，占据不同生态位","example":"The finches are a classic case of adaptive radiation.","exampleCN":"这些雀鸟是适应辐射的经典案例。","why":"Radiation is adaptation multiplied: one body plan is refitted to many diets and habitats. The word describes divergence driven by fitting, not by a single clever change.","whyCN":"辐射是适应乘以许多次：一套身体方案被改到许多食性与栖息地。这个词描述由“适合”驱动的分化，而不是由一次聪明的改变驱动。"}],"etymology":{"intro":{"en":"Adaptive is a derived adjective: adapt plus -ive. The suffix marks a tendency or capacity, so adaptive describes something built to keep fitting rather than something already fitted.","cn":"adaptive 是派生形容词：adapt 加 -ive。这个后缀标记倾向或能力，因此 adaptive 描述“被造来持续适合”的东西，而不是“已经适合”的东西。"},"items":[{"era":"LATIN","en":"Adaptare 'fit to' is ad- 'to' plus aptare 'fit', from aptus 'suited'. The base image is one thing made to match another.","cn":"adaptare“使适合”是 ad-“向”加 aptare“使合适”，出自 aptus“合适的”。基本画面是一件东西被做成与另一件相配。"},{"era":"-IVE","en":"The suffix -ive comes from Latin -ivus, meaning 'tending to, having the nature of'. It turns adapt into a word for a capacity, not a completed action.","cn":"后缀 -ive 来自拉丁语 -ivus，意为“倾向于、具有……性质的”。它把 adapt 变成表示能力的词，而不是完成的动作。"},{"era":"18C.","en":"Adaptive appears in English for things that tend to adapt. Early uses are general; biology later gives the word its strongest home.","cn":"18 世纪，adaptive 出现在英语中，指倾向于适应的东西。早期用法较一般，后来生物学给了这个词最稳固的归宿。"},{"era":"19C.","en":"Evolutionary writing pairs adaptive with fitness: an adaptive trait is one that helps survival. The adjective becomes a judgement about value in an environment.","cn":"19 世纪的演化写作把 adaptive 与适应度配对：适应性状就是有助于生存的性状。这个形容词于是成为对“在某一环境中的价值”的判断。"},{"era":"20C.","en":"Computing, immunology, architecture, and policy each adopt it for self-correcting systems. The common thread is a loop: measure, fit, measure again.","cn":"20 世纪，计算机、免疫学、建筑与政策各自采用它来指自我修正系统。共同线索是一个回路：测量、适合、再测量。"}]},"similar":{"note":{"en":"The first group shares the adapt- shape but differs in suffix; the second compares adjectives of flexibility.","cn":"第一组共享 adapt- 外形，但后缀不同；第二组比较表示“灵活”的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adaptable","ipa":"/əˈdæptəbl/","tag":"capability","definition":"able to be changed to fit. It stresses the capacity of the object, while adaptive stresses the ongoing process or design.","definitionCN":"能被改变以适合。它强调对象的容量，而 adaptive 强调持续的过程或设计。"},{"word":"adaptation","ipa":"/ˌædæpˈteɪʃn/","tag":"derived noun","definition":"the process or result of fitting. It is the noun, not the adjective.","definitionCN":"适合的过程或结果。它是名词，不是形容词。"},{"word":"adapted","ipa":"/əˈdæptɪd/","tag":"derived form","definition":"made suitable. It describes a completed fit, while adaptive describes a continuing capacity.","definitionCN":"被改造成适合的。它描述已完成的适合，而 adaptive 描述持续的能力。"},{"word":"adoptive","ipa":"/əˈdɒptɪv/","tag":"spelling","definition":"related to adoption. Its root is optare 'choose', not aptare 'fit'.","definitionCN":"与收养有关的。其词根是 optare“选择”，不是 aptare“适合”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"flexible","ipa":"/ˈfleksəbl/","tag":"change","definition":"able to bend or change easily. It is broader and physical as well as behavioural.","definitionCN":"容易弯曲或改变的。它更宽泛，既指物理也指行为。"},{"word":"resilient","ipa":"/rɪˈzɪliənt/","tag":"recovery","definition":"able to recover after stress or damage. It stresses bouncing back rather than fitting in.","definitionCN":"在压力或损伤后能恢复。它强调回弹，而不是适合。"},{"word":"versatile","ipa":"/ˈvɜːsətaɪl/","tag":"uses","definition":"able to serve many purposes. It describes range, while adaptive describes response to conditions.","definitionCN":"能用于多种目的。它描述用途范围，而 adaptive 描述对条件的反应。"},{"word":"responsive","ipa":"/rɪˈspɒnsɪv/","tag":"reaction","definition":"reacting quickly and appropriately. It stresses the reaction, while adaptive stresses the resulting fit.","definitionCN":"迅速而适当地反应。它强调反应，而 adaptive 强调由此产生的适合。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on -ive as 'tending to' and the feedback loop, then three abstract images about a design that keeps fitting.","cn":"先用五个围绕 -ive“倾向于”与反馈回路的挂钩，再用三个关于“持续适合的设计”的抽象画面。"},"normal":[{"en":"adapt + -ive = tending to fit: not fitted once, but built to keep fitting.","cn":"adapt + -ive = 倾向于适合：不是适合一次，而是被造来持续适合。"},{"en":"Adaptable is the capacity; adaptive is the working disposition. A towel is adaptable, a thermostat is adaptive.","cn":"adaptable 是容量；adaptive 是运行中的倾向。毛巾是 adaptable，恒温器是 adaptive。"},{"en":"Adaptive immunity is memory written into cells: the body edits itself after meeting a virus.","cn":"适应性免疫是写进细胞的记忆：身体遇见病毒后编辑自己。"},{"en":"Adaptive reuse keeps the warehouse and changes the purpose: the coat stays, the job changes.","cn":"适应性再利用保留仓库、改变用途：外套还在，工作变了。"},{"en":"Adaptive management is a plan that expects to be wrong and has a way to correct itself.","cn":"适应性管理是一个预期自己会错、并且有办法自我纠正的计划。"}],"abstract":[{"en":"An adaptive system pays for flexibility with predictability: it can meet anything, so it is hard to forecast.","cn":"自适应系统用可预测性换取灵活性：它能应对一切，因此难以预报。"},{"en":"Adaptive traits are local solutions: what fits here may be a liability there.","cn":"适应性状是地方性方案：在这里合身，在别处可能成为负担。"},{"en":"The word describes a relationship, not a possession: nothing is adaptive in the abstract, only to something.","cn":"这个词描述关系，而不是属性：没有东西抽象地“有适应性”，只对某物有。"}]},"examples":[{"en":"The course uses adaptive exercises that get harder as the student improves.","cn":"这门课使用自适应练习，学生进步时会变难。"},{"en":"Adaptive traits often arise from small genetic changes.","cn":"适应性状常由微小的基因改变产生。"},{"en":"The old mill's adaptive reuse preserved its water wheel.","cn":"这座旧磨坊的适应性再利用保留了它的水车。"}],"dict_mnemonic":{"note":"adapt（使适合）+ -ive（倾向于）→ 倾向于持续适合的 → 有适应能力的。adaptable 是“能被改”，adaptive 是“自己在改”。","text":"adapt + -ive（有……倾向）→ 能持续调节以适合 → 适应的、自适应的","word":"adaptive"},"root":"拉丁 adaptare“使适合”（ad- + aptus 合适）+ 拉丁后缀 -ivus“倾向于” → 英语 adaptive（18 世纪）。","sensesIntro":{"en":"The senses follow one capacity through different systems: a team that adjusts, a trait that raises fitness, an immune system that remembers, a controller that corrects itself, flexible behaviour, a building refitted, a policy that learns, and a lineage that diversifies.","cn":"这些义项让同一种能力穿过不同系统：会调整的团队、提高适应度的性状、会记忆的免疫系统、自我修正的控制器、灵活的行为、被改用的建筑、会学习的政策，以及分化的谱系。"},"semanticMap":{"core":{"en":"A suspension that changes stiffness as the ground changes beneath it","cn":"随脚下地面变化而改变软硬的悬挂"},"chain":["FIT TO","TENDING TO FIT","SELF-CORRECT","REMEMBER","REFIT","DIVERSIFY"],"branches":[{"senses":"01 · 05","en":"A capacity in organizations and in behaviour: the team and the individual.","cn":"组织与行为中的能力：团队与个人。"},{"senses":"02","en":"THE TRAIT: a feature that raises an organism’s chance of surviving and reproducing.","cn":"性状层面：提高生物生存与繁殖机会的性状。"},{"senses":"03 · 04","en":"Learning systems: immune memory in cells, feedback memory in machines.","cn":"学习系统：细胞里的免疫记忆，机器里的反馈记忆。"},{"senses":"06 · 07","en":"Institutional fitting: a building given a new use, a policy revised by evidence.","cn":"制度性的适合：建筑被赋予新用途，政策随证据修订。"},{"senses":"08","en":"THE RADIATION: one adaptive burst opens many ecological niches.","cn":"谱系的爆发：一次适应辐射打开许多生态位。"}]},"affixes":{"intro":{"en":"Adaptive's family is built on adapt: the noun of process and result, the adverb, the capacity noun, and the negative maladaptive.","cn":"adaptive 的词族建立在 adapt 上：过程与结果名词、副词、能力名词，以及否定的 maladaptive。"},"latinIntro":{"en":"Latin -ivus means 'tending to'. Attached to adaptare 'fit to', it yields a word for a disposition to fit. English also uses -able for capacity and -ation for the act, so the family divides the work neatly.","cn":"拉丁语 -ivus 意为“倾向于”。接在 adaptare“使适合”上，产生表示“适合倾向”的词。英语还用 -able 表容量、-ation 表动作，因此词族分工清楚。"},"items":[{"word":"adaptive","structure":"adapt + -ive (tending to)","meaning":"tending or able to adjust","meaningCN":"倾向或能够适应的","example":"Adaptive software learns from use.","exampleCN":"自适应软件从使用中学习。"},{"word":"adapt","structure":"ad- + aptare (fit)","meaning":"to fit or rework","meaningCN":"适应；改编","example":"The plant adapts to shade.","exampleCN":"这种植物适应荫蔽。"},{"word":"adaptation","structure":"adapt + -ation (action/result noun)","meaning":"the process or product of fitting","meaningCN":"适应过程或产物；改编作品","example":"The adaptation took years.","exampleCN":"这一适应过程花了数年。"},{"word":"adaptively","structure":"adaptive + -ly (adverb)","meaning":"in a way that adjusts","meaningCN":"以适应的方式","example":"The animal responds adaptively to noise.","exampleCN":"这种动物对噪声作出适应性反应。"},{"word":"adaptability","structure":"adaptable + -ity (abstract noun)","meaning":"the capacity to be adapted","meaningCN":"适应能力","example":"Adaptability varies between species.","exampleCN":"不同物种的适应能力不同。"},{"word":"adaptiveness","structure":"adaptive + -ness (state noun)","meaning":"the quality of being adaptive","meaningCN":"适应性","example":"The adaptiveness of the system impressed the team.","exampleCN":"系统的适应性让团队印象深刻。"},{"word":"maladaptive","structure":"mal- (badly) + adaptive","meaning":"fitting poorly or harmfully","meaningCN":"适应不良的","example":"Avoidance can be maladaptive.","exampleCN":"回避可能是一种适应不良。"},{"word":"apt","structure":"Latin aptus (fit)","meaning":"suitable","meaningCN":"合适的","example":"An apt reply fits the moment.","exampleCN":"恰当的回答符合当下情境。"},{"word":"aptitude","structure":"aptus + -itude","meaning":"natural fitness for a task","meaningCN":"天资；适宜性","example":"She showed an aptitude for languages.","exampleCN":"她显示出语言天赋。"}],"latinEntries":[{"word":"aptus","structure":"Latin adjective","meaning":"fit, suited","meaningCN":"合适的；相配的","example":"Aptus underlies adaptive.","exampleCN":"aptus 是 adaptive 的底层词根。"},{"word":"aptare","structure":"aptus + -are","meaning":"to fit, adjust","meaningCN":"使适合；调整","example":"Aptare is the verb inside adaptare.","exampleCN":"aptare 是 adaptare 中的动词。"},{"word":"ivus","structure":"Latin adjective suffix","meaning":"tending to, having the nature of","meaningCN":"倾向于；具有……性质","example":"-ivus became English -ive.","exampleCN":"-ivus 变成英语 -ive。"}]}},{"word":"additional","ipa_uk":"/əˈdɪʃənl/","ipa_us":"/əˈdɪʃənl/","definition_zh":"额外的；附加的；另外的","definition_en":"extra or supplementary, added to what already exists or has been counted","core_image":"在已经装满的箱子上再放一只小盒，箱盖仍能合上","scene":"结账时，账单上已经列了房费。A service charge appeared below the room rate, an additional line that no one had planned for but which still went into the total.","sceneCN":"这里 additional 是「额外的、追加的」（第 1 个义项：超出预期之外的）；句意：房费下面多出一行服务费，这是一行谁都没预料到的额外费用，却仍计入总额。图中可辨识物件：账单、房费行、服务费行、计算器。","pos":[{"tag":"adj.","zh":"额外的；附加的"},{"tag":"adj.","zh":"补充的；另外的"}],"collocations":[{"phrase":"additional information","zh":"补充信息"},{"phrase":"additional cost","zh":"额外费用"},{"phrase":"additional support","zh":"额外支持"},{"phrase":"additional evidence","zh":"补充证据"},{"phrase":"additional charges","zh":"附加费用"}],"forms":[{"label":"原级（形容词）","form":"additional"},{"label":"副词（加 -ly）","form":"additionally"},{"label":"名词（词基）","form":"addition"}],"derivatives":[{"word":"addition","pos":"n.","zh":"增加；加法；附加物"},{"word":"additionally","pos":"adv.","zh":"此外；另外"},{"word":"add","pos":"v.","zh":"添加；相加"},{"word":"additive","pos":"n./adj.","zh":"添加剂；附加的"},{"word":"add-on","pos":"n.","zh":"附加物；附加组件"}],"senses":[{"no":"01","title":"Extra beyond what was expected","titleCN":"超出预期之外的","definition":"added to something already complete or planned, often without being expected","definitionCN":"加在已经完整或已计划的事物之上，常出乎预期","example":"The trip required an additional day because of the storm.","exampleCN":"因为风暴，这趟行程多需要一天。","why":"Addition comes from Latin addere, 'to give to'. Additional marks what has been given on top of the existing amount, so the word always implies a prior sum already in place.","whyCN":"addition 来自拉丁语 addere“给上去”。additional 标记在已有数量之上“再给”的东西，因此这个词总隐含一个已经存在的基数。"},{"no":"02","title":"Supplementary information","titleCN":"补充的信息","definition":"of information or evidence, provided to complete or strengthen what is already known","definitionCN":"指为补全或加强已知内容而提供的信息或证据","example":"The appendix offers additional evidence for the claim.","exampleCN":"附录为这一主张提供了补充证据。","why":"Knowledge is built by adding pieces, and additional marks the piece that arrives after the main argument. It does not replace the original but extends its support.","whyCN":"知识靠添加片段建立，additional 标记在主论证之后到达的那一片。它不替换原文，而是延伸其支撑。"},{"no":"03","title":"A further cost","titleCN":"又一笔费用","definition":"of a charge or cost, added to a price already quoted or paid","definitionCN":"指标价或已付款之外追加的费用","example":"Additional charges apply for late checkout.","exampleCN":"延迟退房会收取额外费用。","why":"Commerce makes the prior sum explicit: a price is quoted, then something is added. Additional is the word that warns the total will not match the first number.","whyCN":"商业把基数说得明确：先报一个价，再加一项。additional 就是提醒“总额不会等于第一个数字”的词。"},{"no":"04","title":"One more item or person","titleCN":"再加一项或一人","definition":"of an item or person, included in a group in addition to those already there","definitionCN":"指在已有成员之外再加入的一项或一人","example":"We need an additional chair for the last guest.","exampleCN":"最后一位客人还需要一把椅子。","why":"A set has a count, and additional raises it by one. The word is counting language: it presupposes a list and marks an entry appended to it.","whyCN":"一个集合有数目，additional 把它加一。这个词是计数语言：它预设一张清单，并标记追加上去的一项。"},{"no":"05","title":"Extra help or resources","titleCN":"额外的帮助或资源","definition":"of support, staff, or resources, supplied beyond the usual or agreed amount","definitionCN":"指超出通常或约定数量提供的支持、人员或资源","example":"The school hired additional tutors for the summer.","exampleCN":"学校在暑期额外聘请了辅导教师。","why":"When the usual provision is not enough, something is given on top. Additional here measures effort, and its use often signals that a baseline was judged insufficient.","whyCN":"当通常供给不够时，就要在其上再给一些。这里的 additional 衡量投入，它的使用常暗示基线被判断为不足。"},{"no":"06","title":"A further requirement","titleCN":"又一项要求","definition":"of a condition or requirement, imposed on top of those already stated","definitionCN":"指在已声明条件之上追加的条件或要求","example":"The visa has additional requirements for minors.","exampleCN":"未成年人签证还有附加要求。","why":"Rules stack: each additional requirement narrows the set of eligible people. The word marks an extra condition that the first reading of the rule did not reveal.","whyCN":"规则会叠加：每项附加要求都缩小合格人群。这个词标记一个在初读规则时没有显示的额外条件。"},{"no":"07","title":"An additional insured party","titleCN":"附加被保险人","definition":"in insurance, a person or organization added to a policy beyond the named insured","definitionCN":"保险中指在记名被保险人之外加入保单的人或组织","example":"The contractor was listed as an additional insured.","exampleCN":"承包商被列为附加被保险人。","why":"Insurance uses additional as a technical term because a policy is a closed list. Adding a party does not rewrite the policy; it appends a protected name to it.","whyCN":"保险把 additional 当作术语，因为保单是一张封闭名单。加入一方并不重写保单，而是把一个受保护的名字追加上去。"},{"no":"08","title":"An extra amount or dose","titleCN":"额外的量或剂量","definition":"of a quantity, especially a dose or portion, exceeding the standard amount","definitionCN":"指超出标准量的数量，尤指剂量或份额","example":"An additional dose may be needed after exposure.","exampleCN":"暴露之后可能需要再补一剂。","why":"Medicine counts quantities against a standard schedule. An additional dose is not a different medicine but the same one given once more, which is the purest 'add to the sum' sense.","whyCN":"医学按标准方案计数。额外一剂不是另一种药，而是同一种药再给一次，这是最纯粹的“加到总数上”的义项。"}],"etymology":{"intro":{"en":"Additional is a derived adjective: addition plus -al. Addition comes from Latin additio, from addere 'to give to', so the word literally marks something given onto an existing amount.","cn":"additional 是派生形容词：addition 加 -al。addition 来自拉丁语 additio，出自 addere“给上去”，因此这个词字面上标记“加在已有数量之上给予”的东西。"},"items":[{"era":"LATIN","en":"Addere means 'to give to, add', from ad- 'to' plus dare 'to give'. Its noun additio is 'a giving to', hence an addition.","cn":"addere 意为“给上去、添加”，由 ad-“向”加 dare“给”构成。其名词 additio 是“给上去”，即增加。"},{"era":"14C.","en":"English borrows addition through French, first in arithmetic and then in general use for anything appended.","cn":"英语经法语借入 addition，先用于算术，后泛指任何被追加的东西。"},{"era":"-AL","en":"The adjective suffix -al comes from Latin -alis, meaning 'relating to'. Additional therefore means 'relating to an addition', not 'being an addition' by etymology.","cn":"形容词后缀 -al 来自拉丁语 -alis，意为“与……有关”。因此 additional 词源上是“与增加有关的”，而不是“本身就是增加物”。"},{"era":"17C.–18C.","en":"The adjective settles into the modern sense 'extra, supplementary'. Commerce and law give it fixed phrases such as additional charges and additional insured.","cn":"17 至 18 世纪，这个形容词稳定为现代义“额外的、补充的”。商业与法律给它固定搭配，如附加费用与附加被保险人。"},{"era":"MODERN","en":"The word now appears wherever a baseline is assumed: data, costs, requirements, staff, doses. Its meaning depends on knowing what the first amount was.","cn":"这个词如今出现在任何预设基线的场合：数据、费用、要求、人员、剂量。它的意思取决于知道第一个数量是多少。"}]},"similar":{"note":{"en":"The first group shares the addit- shape or the 'give to' root; the second compares adjectives of extra quantity.","cn":"第一组共享 addit- 外形或“给上去”词根；第二组比较表示“额外数量”的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"addition","ipa":"/əˈdɪʃn/","tag":"base noun","definition":"the act of adding, or something added. It is the noun behind additional.","definitionCN":"添加的行为，或被添加之物。它是 additional 背后的名词。"},{"word":"additionally","ipa":"/əˈdɪʃənəli/","tag":"derived form","definition":"in addition; also. It is the adverb, often used as a discourse marker.","definitionCN":"此外；另外。它是副词，常用作篇章标记。"},{"word":"additive","ipa":"/ˈædətɪv/","tag":"different suffix","definition":"a substance added, or a property of addition. It uses -ive, not -al.","definitionCN":"被添加的物质，或加和性质。它用 -ive，而不是 -al。"},{"word":"addendum","ipa":"/əˈdendəm/","tag":"same root","definition":"an item added to a document. It is a Latin gerundive, not an English -al derivative.","definitionCN":"文件后追加的项目。它是拉丁语动形词，不是英语 -al 派生词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"extra","ipa":"/ˈekstrə/","tag":"amount","definition":"more than the usual or expected. It is more conversational and can stand alone as a noun.","definitionCN":"超过通常或预期的。它更口语化，也可单独作名词。"},{"word":"supplementary","ipa":"/ˌsʌplɪˈmentri/","tag":"completion","definition":"added to complete or improve something. It stresses completion rather than mere quantity.","definitionCN":"为补全或改进而添加。它强调补全，而不只是数量。"},{"word":"further","ipa":"/ˈfɜːðə/","tag":"degree","definition":"additional in distance or degree. It often modifies abstract nouns such as research or action.","definitionCN":"距离或程度上的进一步。它常修饰研究、行动等抽象名词。"},{"word":"spare","ipa":"/speə/","tag":"reserve","definition":"kept in reserve for extra use. It describes an object held ready, not an amount already counted.","definitionCN":"留作额外使用的。它描述备用物件，而不是已计入的数量。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on addere 'give to' and the -al adjective, then three abstract images about a baseline plus one more.","cn":"先用五个围绕 addere“给上去”与 -al 形容词的挂钩，再用三个关于“基数再加一”的抽象画面。"},"normal":[{"en":"add = ad + dare, 'give to': additional is whatever has been given on top of the existing sum.","cn":"add = ad + dare，“给上去”：additional 就是加在已有总数之上给出的东西。"},{"en":"-al makes it 'relating to an addition', so the word always points back to a baseline.","cn":"-al 使它成为“与增加有关的”，因此这个词总是指回一个基数。"},{"en":"Additional charges, additional evidence, additional insured: each is one more entry on a closed list.","cn":"附加费用、补充证据、附加被保险人：每一项都是封闭名单上多出的一条。"},{"en":"Addition is also the arithmetic operation, so the word carries a counting gesture.","cn":"addition 也是算术中的加法，因此这个词带着计数的动作。"},{"en":"If you cannot say what the first amount was, additional has nothing to attach to.","cn":"如果你说不出第一个数量是多少，additional 就没有附着点。"}],"abstract":[{"en":"Additional is a relational word: it measures a difference, not a thing.","cn":"additional 是关系词：它衡量差值，而不是事物。"},{"en":"Every added requirement narrows the field, even when it looks like a small extra.","cn":"每项附加要求都会缩小范围，即使它看起来只是小小附加。"},{"en":"The word quietly admits that the first plan was not enough.","cn":"这个词悄悄承认了第一个计划不够用。"}]},"examples":[{"en":"We need additional time to test the design.","cn":"我们需要额外的时间测试这个设计。"},{"en":"Additional evidence changed the committee's view.","cn":"补充证据改变了委员会的看法。"},{"en":"The airline charges additional fees for oversized bags.","cn":"航空公司对超大行李收取附加费。"}],"dict_mnemonic":{"note":"add（加）+ -ition（名词）+ -al（形容词）→ 与“添加”有关的 → 额外的。记住它总要有一个已有的基数。","text":"ad（向）+ dare（给）→ addere（给上去）→ addition + -al → 额外的、附加的","word":"additional"},"root":"拉丁 addere“给上去”（ad- 向 + dare 给）→ additio“增加” → 法语 addition → 英语 addition + -al（拉丁 -alis）→ additional。","sensesIntro":{"en":"The senses all add to a prior amount: an extra day, supplementary evidence, a further charge, one more item, extra help, an added requirement, an insured party appended to a policy, and an extra dose.","cn":"所有义项都在一个已有数量上追加：多一天、补充证据、又一笔费用、再加一项、额外帮助、附加要求、追加到保单的一方，以及额外一剂。"},"semanticMap":{"core":{"en":"A small box placed on a full crate, with the lid still able to close","cn":"在装满的箱子上再放一只小盒，箱盖仍能合上"},"chain":["GIVE TO","ADD","INCREASE THE SUM","SUPPLEMENT","ONE MORE ENTRY","EXTRA"],"branches":[{"senses":"01","en":"BEYOND EXPECTATION: one more layer added to what was already complete.","cn":"超出预期：在完整之外再加一层。"},{"senses":"02 · 05","en":"Support of knowledge and support of people: evidence and staff.","cn":"对知识的支撑与对人的支撑：证据与人员。"},{"senses":"03 · 06","en":"Two kinds of burden: a cost and a condition.","cn":"两种负担：费用与条件。"},{"senses":"07 · 08","en":"Technical additions: a name on a policy, a dose on a schedule.","cn":"技术性追加：保单上的名字，方案上的一剂。"},{"senses":"04","en":"AN EXTRA ENTRY: one more item or person beyond those already counted.","cn":"名单上的追加：在已有成员之外多出一项或一人。"}]},"affixes":{"intro":{"en":"Additional's family is built on add: the noun of the act, the adverb, the adjective of additive property, and the compound add-on.","cn":"additional 的词族建立在 add 上：动作名词、副词、加和性质形容词，以及复合词 add-on。"},"latinIntro":{"en":"Latin addere 'give to' is ad- plus dare 'give'. Additio is its action noun, and -alis turns addition into an adjective. The base dare also appears in data, 'things given'.","cn":"拉丁语 addere“给上去”是 ad- 加 dare“给”。additio 是其动作名词，-alis 把 addition 变成形容词。词基 dare 也出现在 data，“被给出的东西”。"},"items":[{"word":"additional","structure":"addition + -al (adjective)","meaning":"relating to an addition; extra","meaningCN":"与增加有关的；额外的","example":"Additional seats were added.","exampleCN":"又增加了一些座位。"},{"word":"addition","structure":"addere + -tion (action noun)","meaning":"the act of adding; something added","meaningCN":"添加的行为；附加物","example":"The addition of a porch changed the house.","exampleCN":"增加一个门廊改变了这栋房子。"},{"word":"additionally","structure":"additional + -ly (adverb)","meaning":"in addition; also","meaningCN":"此外；另外","example":"Additionally, the report lists three risks.","exampleCN":"此外，报告列出了三项风险。"},{"word":"add","structure":"Latin addere (give to)","meaning":"to put together with something else","meaningCN":"添加；相加","example":"Add a pinch of salt.","exampleCN":"加一小撮盐。"},{"word":"additive","structure":"add + -itive (adjective/noun)","meaning":"a substance added; relating to addition","meaningCN":"添加剂；加和的","example":"The additive improves shelf life.","exampleCN":"这种添加剂延长保质期。"},{"word":"add-on","structure":"add + on (compound)","meaning":"an extra item attached to a main product","meaningCN":"附加物；附加组件","example":"The software is sold as an add-on.","exampleCN":"这款软件作为附加组件出售。"},{"word":"addendum","structure":"Latin addere + -ndum","meaning":"something to be added","meaningCN":"追加物；补遗","example":"The contract has an addendum.","exampleCN":"合同有一份补充协议。"},{"word":"data","structure":"Latin dare (give) + -ta","meaning":"things given","meaningCN":"被给出的东西；数据","example":"Data is literally 'given things'.","exampleCN":"data 字面就是“被给出的东西”。"},{"word":"date","structure":"Latin dare (give) + -ta","meaning":"a given time","meaningCN":"给定的时间；日期","example":"Date also comes from dare.","exampleCN":"date 也来自 dare。"}],"latinEntries":[{"word":"dare","structure":"Latin verb","meaning":"to give","meaningCN":"给","example":"Dare is the base of addere.","exampleCN":"dare 是 addere 的词基。"},{"word":"addere","structure":"ad- (to) + dare (give)","meaning":"to give to, add","meaningCN":"给上去；添加","example":"Addere is the source of add.","exampleCN":"addere 是 add 的来源。"},{"word":"additio","structure":"addere + -tio (action noun)","meaning":"a giving to, an addition","meaningCN":"给上去；增加","example":"Additio became English addition.","exampleCN":"additio 变成英语 addition。"}]}},{"word":"additive","ipa_uk":"/ˈædətɪv/","ipa_us":"/ˈædətɪv/","definition_zh":"添加剂；附加的；加性的","definition_en":"a substance added to something in small amounts, or a property in which separate effects simply add together","core_image":"往汤里再撒一撮盐，味道在原有基础上叠加","scene":"食品标签上列着防腐剂、色素、增稠剂。They add almost nothing to the bulk of the food, yet each additive changes its taste or its shelf life.","sceneCN":"这里 additive 是「食品添加剂」（第 1 个义项：少量加入的物质）；句意：它们几乎不占食物的主体，但每一种添加剂都改变口感或保存期。图中可辨识物件：食品标签、配料表、三种添加剂名称、汤锅。","pos":[{"tag":"n.","zh":"添加剂；附加物"},{"tag":"adj.","zh":"附加的；加性的"}],"collocations":[{"phrase":"food additive","zh":"食品添加剂"},{"phrase":"additive effect","zh":"加和效应"},{"phrase":"additive manufacturing","zh":"增材制造（3D 打印）"},{"phrase":"additive colour","zh":"加色"},{"phrase":"additive model","zh":"加性模型"}],"forms":[{"label":"单数（一种添加剂）","form":"additive"},{"label":"复数（多种添加剂）","form":"additives"},{"label":"动词（原形）","form":"add"}],"derivatives":[{"word":"add","pos":"v.","zh":"添加；相加"},{"word":"addition","pos":"n.","zh":"增加；加法"},{"word":"additivity","pos":"n.","zh":"加和性"},{"word":"additive-free","pos":"adj.","zh":"不含添加剂的"},{"word":"superadditive","pos":"adj.","zh":"超加和的"}],"senses":[{"no":"01","title":"A substance added in small amounts","titleCN":"少量加入的物质","definition":"a substance added to food, fuel, or another product in small quantities to change or preserve it","definitionCN":"少量加入食品、燃料或其他产品以改变或保存它的物质","example":"The label lists three additives, including a preservative.","exampleCN":"标签列出了三种添加剂，其中一种是防腐剂。","why":"Additive is add plus -ive, 'tending to add'. The noun use is a concrete shift: the adjective's abstract 'that which adds' becomes a countable substance, small in amount but decisive in effect.","whyCN":"additive 是 add 加 -ive“倾向于添加”。名词用法是具体化转移：形容词抽象的“起添加作用者”变成可数物质，量小却影响明显。"},{"no":"02","title":"Effects that simply add","titleCN":"简单相加的效应","definition":"of two or more effects, combining so that the total is the sum of the separate parts","definitionCN":"指两种或更多效应合并后，总量等于各部分之和","example":"The drugs have an additive effect on blood pressure.","exampleCN":"这些药物对血压有加和效应。","why":"In mathematics and pharmacology, additive marks a relation without interaction: each cause contributes its own amount. The word's counting origin becomes a claim about how causes combine.","whyCN":"在数学与药理学中，additive 标记一种无交互的关系：每个原因贡献自己的量。这个词的计数出身变成关于“原因如何合并”的主张。"},{"no":"03","title":"Additive manufacturing","titleCN":"增材制造","definition":"in engineering, building an object layer by layer rather than cutting it from a block","definitionCN":"工程中指逐层堆叠材料造出物件，而不是从整块材料中切削","example":"Additive manufacturing made the custom alloy part possible.","exampleCN":"增材制造使这个定制合金零件成为可能。","why":"The name contrasts with subtractive machining: instead of removing material, you add it. Additive here describes a process of construction, and the word's 'add' is literal at the scale of layers.","whyCN":"这个名字与减材加工相对：不是移除材料，而是添加材料。这里的 additive 描述建造过程，其“添加”在层片尺度上是字面的。"},{"no":"04","title":"Additive colour mixing","titleCN":"加色混合","definition":"in light, combining coloured beams so that their wavelengths add and the result grows brighter","definitionCN":"指光束合并时波长相加，结果更亮","example":"Screens use additive colour: red, green, and blue light make white.","exampleCN":"屏幕使用加色法：红、绿、蓝光合成白色。","why":"With light, adding colours adds energy, so the mixture moves toward white. With paint, mixing subtracts wavelengths. Additive names the first model and explains why screens and pigments behave oppositely.","whyCN":"对光而言，加色就是加能量，因此混合趋向白色；对颜料而言，混合是减波长。additive 命名第一种模型，也解释了屏幕与颜料为何相反。"},{"no":"05","title":"The additive identity and inverse","titleCN":"加法单位元与逆元","definition":"in algebra, the element that leaves a number unchanged when added (0), or the element that sums with it to zero","definitionCN":"代数中指加上后不改变原数的元素（0），或与原数相加得零的元素","example":"Zero is the additive identity; the additive inverse of five is negative five.","exampleCN":"零是加法单位元；五的加法逆元是负五。","why":"Abstract algebra isolates the pure structure of addition. Additive here does not mean 'extra' but 'belonging to the operation of addition', which is the word's most stripped-down sense.","whyCN":"抽象代数把加法的纯结构孤立出来。这里的 additive 不是“额外”，而是“属于加法运算”，这是这个词最剥离的义项。"},{"no":"06","title":"An additive statistical model","titleCN":"加性统计模型","definition":"in statistics, a model in which the contribution of each factor is added rather than multiplied or interacting","definitionCN":"统计学中每个因素的贡献相加、而非相乘或交互的模型","example":"The additive model explains most of the variation.","exampleCN":"加性模型解释了大部分变异。","why":"A model is additive when its parts can be summed without interaction terms. The word makes a strong assumption about the world: that causes do not amplify or cancel each other beyond simple addition.","whyCN":"当模型各部分可以相加、无需交互项时，它就是加性的。这个词对世界作了强假设：原因之间不会在简单相加之外放大或相互抵消。"},{"no":"07","title":"Additive bilingualism","titleCN":"附加性双语","definition":"in education, learning a second language without losing or weakening the first","definitionCN":"教育中指学习第二语言而不丧失或削弱第一语言","example":"The program aims at additive bilingualism, not replacement.","exampleCN":"该项目目标是附加性双语，而不是替代。","why":"Here adding a language does not subtract another. The word is used to reject a zero-sum model of bilingualism, and additive means 'net gain' rather than 'extra item'.","whyCN":"这里增加一种语言并不减去另一种。这个词用来拒绝零和式双语观，additive 意为“净增益”，而不是“额外项目”。"},{"no":"08","title":"Additive gene effects","titleCN":"加性基因效应","definition":"in genetics, of alleles whose effects combine by simple addition rather than dominance or interaction","definitionCN":"遗传学中指等位基因效应按简单相加组合，而非显性或交互","example":"Height has a large additive genetic component.","exampleCN":"身高有很大的加性遗传成分。","why":"Quantitative genetics decomposes a trait into parts that add. The word lets researchers ask how much each allele contributes, assuming no synergy, which is the same arithmetic as in the statistical model.","whyCN":"数量遗传学把性状分解为可相加的部分。这个词让研究者追问每个等位基因贡献多少，并假设没有协同，这与统计模型中的算术相同。"}],"etymology":{"intro":{"en":"Additive is a derived word: add plus -itive. As an adjective it means 'tending to add'; as a noun it names the thing added. The mathematical senses keep the operation rather than the substance.","cn":"additive 是派生词：add 加 -itive。作形容词意为“倾向于添加”；作名词指被添加之物。数学诸义保留的是“运算”，而不是“物质”。"},"items":[{"era":"LATIN","en":"The base is addere 'to give to', from ad- plus dare 'give'. The suffix -ivus gives adjectives of tendency, and English -itive continues that pattern.","cn":"词基是 addere“给上去”，由 ad- 加 dare“给”构成。后缀 -ivus 构成表倾向的形容词，英语 -itive 延续这一模式。"},{"era":"17C.","en":"Additive appears as an adjective meaning 'that may be added'. The noun use for a substance added develops alongside it.","cn":"17 世纪，additive 作为形容词出现，意为“可被添加的”。指被添加物质的名词用法随之发展。"},{"era":"19C.","en":"Chemistry and industry make the noun concrete: additives are the small ingredients that change a product. Food regulation later turns the word into a label category.","cn":"19 世纪，化学与工业使名词具体化：additive 是改变产品的小配料。食品监管后来把这个词变成标签类别。"},{"era":"19C.–20C.","en":"Mathematics and colour theory use additive for operations and mixtures where parts sum. The word now contrasts with subtractive.","cn":"19 至 20 世纪，数学与色彩理论用 additive 指部分相加的运算与混合。这个词此时与 subtractive 相对。"},{"era":"20C.","en":"Statistics, genetics, and manufacturing extend it to models, gene effects, and layer-by-layer printing. The common core remains: parts that add rather than interact.","cn":"20 世纪，统计学、遗传学与制造业把它扩展到模型、基因效应与逐层打印。共同核心仍是：部分相加，而非交互。"}]},"similar":{"note":{"en":"The first group shares the addit- shape or the 'add' root; the second contrasts additive with related quantitative adjectives.","cn":"第一组共享 addit- 外形或“添加”词根；第二组把 additive 与相关数量形容词对照。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"additional","ipa":"/əˈdɪʃənl/","tag":"different suffix","definition":"extra; supplementary. It uses -al and describes quantity, not a mathematical property.","definitionCN":"额外的；补充的。它用 -al，描述数量，而不是数学性质。"},{"word":"addition","ipa":"/əˈdɪʃn/","tag":"base noun","definition":"the act of adding, or the operation of addition. It is the noun behind additive.","definitionCN":"添加行为，或加法运算。它是 additive 背后的名词。"},{"word":"add","ipa":"/æd/","tag":"base verb","definition":"to put with something else. It is the verb at the root of the family.","definitionCN":"把某物与另一物放在一起。它是词族的根动词。"},{"word":"addendum","ipa":"/əˈdendəm/","tag":"same root","definition":"something added to a document. It is a Latin form, not an -ive derivative.","definitionCN":"文件后追加的内容。它是拉丁语形式，不是 -ive 派生词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"supplement","ipa":"/ˈsʌplɪmənt/","tag":"product","definition":"something added to complete or improve. It is often a separate product, while an additive is mixed in.","definitionCN":"为补全或改进而添加的东西。它常是独立产品，而 additive 是混入的。"},{"word":"ingredient","ipa":"/ɪnˈɡriːdiənt/","tag":"component","definition":"any component of a mixture. It is neutral, while additive implies a small modifying dose.","definitionCN":"混合物的任何成分。它是中性的，而 additive 暗示少量起改良作用的剂量。"},{"word":"cumulative","ipa":"/ˈkjuːmjələtɪv/","tag":"accumulation","definition":"increasing by successive additions. It stresses growth over time, not a mathematical property.","definitionCN":"通过连续添加而增加。它强调随时间增长，而不是数学性质。"},{"word":"multiplicative","ipa":"/ˌmʌltɪˈplɪkətɪv/","tag":"opposite model","definition":"combining by multiplication rather than addition. It is the contrast term in models and colour theory.","definitionCN":"按相乘而非相加组合。它是模型与色彩理论中的对照词。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on add + -itive and the two roles, then three abstract images about parts that sum.","cn":"先用五个围绕 add + -itive 与两种词性的挂钩，再用三个关于“部分相加”的抽象画面。"},"normal":[{"en":"add + -itive = tending to add: as a noun, the thing added; as an adjective, the property of adding.","cn":"add + -itive = 倾向于添加：作名词是被加的东西，作形容词是“相加的性质”。"},{"en":"A food additive is small, but it is not an ingredient in the main sense: it modifies rather than feeds.","cn":"食品添加剂量小，但不是主料意义上的成分：它改良，而不是供养。"},{"en":"Additive colour adds light and moves toward white; subtractive colour removes light and moves toward black.","cn":"加色法加光，趋向白；减色法减光，趋向黑。"},{"en":"Additive manufacturing adds layers; subtractive machining removes them.","cn":"增材制造加层；减材加工去层。"},{"en":"An additive model assumes causes do not amplify each other: the total is just the sum.","cn":"加性模型假定原因不会相互放大：总数只是和。"}],"abstract":[{"en":"Additive is an assumption about the world disguised as a description of it.","cn":"additive 是一个关于世界的假设，却伪装成对世界的描述。"},{"en":"What is added can preserve or transform: a preservative keeps time still, a colour changes it.","cn":"被添加之物可以保存也可以改变：防腐剂让时间停住，色素改变它。"},{"en":"The same word covers a pinch of salt and a layer of metal: scale does not change the arithmetic.","cn":"同一个词覆盖一撮盐与一层金属：尺度不改变算术。"}]},"examples":[{"en":"The additive keeps the fuel from freezing in winter.","cn":"这种添加剂防止燃料在冬天冻结。"},{"en":"The two risks are additive, not multiplicative.","cn":"这两种风险是相加的，不是相乘的。"},{"en":"Additive printing builds the part from powdered metal.","cn":"增材打印用金属粉末逐层造出零件。"}],"dict_mnemonic":{"note":"add（加）+ -itive（倾向/性质）→ 起添加作用的东西或性质 → 添加剂；加性的。名词是“被加进去的”，形容词是“可相加的”。","text":"add + -itive → 添加之物／可相加的性质 → 添加剂、附加的、加性的","word":"additive"},"root":"拉丁 addere“给上去”（ad- + dare 给）+ 拉丁后缀 -ivus“倾向于” → 英语 additive（17 世纪）；名词义 19 世纪具体化为“添加剂”。","sensesIntro":{"en":"The senses split into two families: substances added in small amounts, and properties in which parts sum. Food, fuel, manufacturing, colour, algebra, statistics, bilingualism, and genetics each take one branch.","cn":"这些义项分成两族：少量加入的物质，以及部分相加的性质。食品、燃料、制造、色彩、代数、统计、双语与遗传各取一支。"},"semanticMap":{"core":{"en":"A pinch of salt falling into a pot: the soup is still soup, but the taste has shifted","cn":"一撮盐落进锅里：汤还是汤，味道却变了"},"chain":["ADD","SMALL DOSE","MODIFY","SUM OF PARTS","NO INTERACTION","NET GAIN"],"branches":[{"senses":"01","en":"SUBSTANCE: a small amount added to change or preserve a product.","cn":"物质：少量加入以改变或保存。"},{"senses":"02 · 06","en":"The additive assumption: causes contribute amounts that can be summed.","cn":"加性假设：原因贡献可相加的量。"},{"senses":"03 · 04","en":"Two physical models: layers of material, and beams of light.","cn":"两种物理模型：材料层，与光束。"},{"senses":"05 · 08","en":"Pure structure: the algebra of zero, and the genetics of summed alleles.","cn":"纯结构：零的代数，与相加等位基因的遗传学。"},{"senses":"07","en":"EDUCATIONAL ADDITION: learning a second language without weakening the first.","cn":"教育里的加法：学第二语言而不削弱第一语言。"}]},"affixes":{"intro":{"en":"Additive's family is built on add: the action noun, the quantity adjective, the abstract property, and the negative compound.","cn":"additive 的词族建立在 add 上：动作名词、数量形容词、抽象性质，以及否定复合词。"},"latinIntro":{"en":"Latin addere 'give to' plus -ivus 'tending to' yields the adjective pattern behind additive. The noun use is English, not Latin: Latin had no noun additivum for a food ingredient.","cn":"拉丁语 addere“给上去”加 -ivus“倾向于”给出 additive 背后的形容词模式。名词用法是英语的，不是拉丁语：拉丁语并没有指食品配料的 additivum。"},"items":[{"word":"additive","structure":"add + -itive (adjective/noun)","meaning":"a substance added; relating to addition","meaningCN":"添加剂；加性的","example":"The additive is listed on the label.","exampleCN":"这种添加剂列在标签上。"},{"word":"add","structure":"Latin addere (give to)","meaning":"to put with something else","meaningCN":"添加；相加","example":"Add the numbers.","exampleCN":"把这些数字相加。"},{"word":"addition","structure":"add + -ition (action noun)","meaning":"the act of adding; the operation","meaningCN":"添加；加法","example":"Addition is commutative.","exampleCN":"加法是可交换的。"},{"word":"additivity","structure":"additive + -ity (abstract noun)","meaning":"the property of being additive","meaningCN":"加和性","example":"The additivity of the model was tested.","exampleCN":"该模型的加和性经过了检验。"},{"word":"additive-free","structure":"additive + free (compound adjective)","meaning":"containing no additives","meaningCN":"不含添加剂的","example":"They sell additive-free bread.","exampleCN":"他们出售不含添加剂的面包。"},{"word":"superadditive","structure":"super- (beyond) + additive","meaning":"having effects that exceed simple addition","meaningCN":"超加和的","example":"The interaction was superadditive.","exampleCN":"这种交互是超加和的。"},{"word":"additional","structure":"addition + -al","meaning":"extra; supplementary","meaningCN":"额外的；补充的","example":"Additional tests are needed.","exampleCN":"需要额外测试。"},{"word":"addendum","structure":"addere + -ndum","meaning":"something to be added","meaningCN":"追加物；补遗","example":"The addendum clarifies the term.","exampleCN":"补遗澄清了该条款。"},{"word":"adder","structure":"add + -er (agent)","meaning":"one that adds, or a snake","meaningCN":"添加者；蝰蛇","example":"Adder is the agent noun of add.","exampleCN":"adder 是 add 的施事名词。"}],"latinEntries":[{"word":"addere","structure":"ad- (to) + dare (give)","meaning":"to give to, add","meaningCN":"给上去；添加","example":"Addere gives English add and additive.","exampleCN":"addere 给出英语 add 与 additive。"},{"word":"dare","structure":"Latin verb","meaning":"to give","meaningCN":"给","example":"Dare also gives data.","exampleCN":"dare 也给出 data。"},{"word":"ivus","structure":"Latin adjective suffix","meaning":"tending to","meaningCN":"倾向于","example":"-ivus becomes English -ive/-itive.","exampleCN":"-ivus 变成英语 -ive/-itive。"}]}},{"word":"adequately","ipa_uk":"/ˈædɪkwətli/","ipa_us":"/ˈædɪkwətli/","definition_zh":"充分地；足够地；尚可地","definition_en":"to a degree that is enough for a particular purpose, though not necessarily more than that","core_image":"水刚好淹到刻度线，不多不少，够用即可","scene":"体检单上有一栏“每日饮水”，医生划了一条最低线。The water in the glass came exactly to that line, and the nurse said he had drunk adequately for the day.","sceneCN":"这里 adequately 是「达到足够程度」（第 1 个义项：足以达到目的）；句意：杯里的水面正好压到那条线，护士说他这一天的饮水已经够了。图中可辨识物件：体检单、刻度线、水杯、压线的水面。","pos":[{"tag":"adv.","zh":"充分地；足够地"},{"tag":"adv.","zh":"尚可地；勉强达标地"},{"tag":"adv.","zh":"（法律、医学）已充分（告知、准备）地"}],"collocations":[{"phrase":"adequately prepared","zh":"准备充分"},{"phrase":"adequately funded","zh":"资金充足"},{"phrase":"adequately explained","zh":"解释得足够清楚"},{"phrase":"adequately addressed","zh":"得到充分处理"},{"phrase":"adequately trained","zh":"受过足够训练"}],"forms":[{"label":"原级（副词）","form":"adequately"},{"label":"形容词（词基）","form":"adequate"},{"label":"比较级","form":"more adequately"},{"label":"最高级","form":"most adequately"}],"derivatives":[{"word":"adequate","pos":"adj.","zh":"足够的；适当的"},{"word":"adequacy","pos":"n.","zh":"充分；适当"},{"word":"inadequate","pos":"adj.","zh":"不充分的；不胜任的"},{"word":"inadequacy","pos":"n.","zh":"不足；不胜任"},{"word":"inadequately","pos":"adv.","zh":"不充分地"}],"senses":[{"no":"01","title":"Enough for the purpose","titleCN":"足以达到目的","definition":"to a degree that satisfies a need or requirement, without necessarily exceeding it","definitionCN":"达到满足需要或要求的程度，但不一定超出","example":"The shelter was adequately heated for the winter.","exampleCN":"这处收容所在冬天供暖充足。","why":"Adequately goes back to Latin adaequare, 'make equal to'. The picture is a balance: supply is brought level with demand. Enough is not plenty; it is equality with the requirement.","whyCN":"adequately 源自拉丁语 adaequare“使相等”。画面是一架天平：供给被拉到与需求齐平。够用不是富余，而是与要求相等。"},{"no":"02","title":"At a passable standard","titleCN":"达到及格水准","definition":"of skill or quality, meeting a minimum acceptable level rather than an excellent one","definitionCN":"指技能或质量达到可接受的最低水平，而非优秀水平","example":"She sings adequately, though she will never be a soloist.","exampleCN":"她唱得还算可以，但永远不会成为独唱演员。","why":"Once 'equal to the need' is applied to ability, the bar becomes a minimum grade. The adverb quietly ranks: it reports that the standard was met, not that it was raised.","whyCN":"一旦“与需要相等”用于能力，横杆就变成最低分数线。这个副词在悄悄排序：它报告达标，而不报告拔高。"},{"no":"03","title":"Enough to make a result trustworthy","titleCN":"足以让结果可信","definition":"in research, to a degree that makes a measurement or design reliable","definitionCN":"在研究中对测量或设计达到可靠的程度","example":"The trial was adequately powered to detect a small effect.","exampleCN":"该试验的检验效能足以发现微小效应。","why":"In research, sufficiency becomes statistical: a sample must be equal to the question. Adequate here is a technical threshold, and journals treat it as a gate rather than a compliment.","whyCN":"在研究中，充分性变成统计问题：样本必须与问题相等。这里的 adequate 是一道技术门槛，期刊把它当作准入门槛，而不是赞美。"},{"no":"04","title":"Fully informed or warned","titleCN":"已充分告知或警示","definition":"in law and medicine, given information sufficient for a reasonable person to decide","definitionCN":"法律与医学中指所给信息足以让理性人作出决定","example":"Patients must be adequately informed before consenting.","exampleCN":"患者同意前必须得到充分告知。","why":"Law turns 'equal to the need' into a duty: the information supplied must match what a reasonable person needs in order to choose. Falling short is negligence, not merely a bad explanation.","whyCN":"法律把“与需要相等”变成义务：所给信息必须与理性人作选择所需相匹配。不到位就是过失，而不只是解释得差。"},{"no":"05","title":"Enough preparation or training","titleCN":"准备或训练足够","definition":"of a person or team, equipped with enough instruction or practice to perform a task","definitionCN":"指个人或团队获得足够的指导或练习以完成某项任务","example":"The new staff were adequately trained before the audit.","exampleCN":"新员工在接受审计前受过足够培训。","why":"Training is measured against a task, not against an ideal. Adequately trained means capable of doing the job, and the adverb deliberately leaves excellence outside its scope.","whyCN":"训练是对着任务量的，不是对着理想量的。adequately trained 意为能干活，这个副词有意把“优秀”挡在门外。"},{"no":"06","title":"Funded or paid enough","titleCN":"资金或报酬足额","definition":"of money, covering the obligation or cost without surplus","definitionCN":"指资金覆盖义务或成本而没有富余","example":"The library is adequately funded for routine upkeep.","exampleCN":"图书馆的日常维护资金充足。","why":"Budgets make sufficiency countable. Adequately funded says the money meets the obligation; it is the language of audits and appropriations, not of ambition.","whyCN":"预算让“充分”变得可以计数。adequately funded 意为钱够履行义务；这是审计与拨款的用语，不是雄心的用语。"},{"no":"07","title":"Explained clearly enough","titleCN":"解释得足够清楚","definition":"of an explanation or description, complete enough for a reader to act on it","definitionCN":"指解释或描述完整到读者可以据此行动","example":"The manual adequately describes the installation steps.","exampleCN":"手册对安装步骤的描述足够清楚。","why":"An explanation is adequate when a reader can act on it. The standard is functional: it asks whether the text carries the reader across the gap, not whether the prose is elegant.","whyCN":"解释达到 adequate，是在读者能照着做的时候。标准是功能性的：它问文本能否把读者送到对岸，而不问文笔是否漂亮。"},{"no":"08","title":"Just enough and no more","titleCN":"刚好够，仅此而已","definition":"at the minimum acceptable level, often suggesting that nothing extra was given","definitionCN":"处于可接受的最低水平，常暗示没有给出任何额外的东西","example":"The lighting was adequate but the room still felt dim.","exampleCN":"照明勉强够用，但房间仍显得昏暗。","why":"This is the word at its most reserved. Because adequate means 'equal to', anything above the line becomes invisible; the adverb can therefore sound like faint praise, marking the floor rather than the ceiling.","whyCN":"这是这个词最含蓄的一面。因为 adequate 意为“相等”，线以上的一切都看不见；于是这个副词听起来像勉强的夸奖，标的是地板而不是天花板。"}],"etymology":{"intro":{"en":"Adequately is adequate plus -ly. The base is Latin adaequatus, 'made equal to', and the adverbial suffix is native English, so the word joins a Latin root to an Old English ending.","cn":"adequately 是 adequate 加 -ly。词基是拉丁语 adaequatus“被使与……相等”，副词后缀却是英语本族的，因此这个词把拉丁词根接在古英语词尾上。"},"items":[{"era":"LATIN","en":"Adaequare 'make equal to' is ad- 'to' plus aequare 'make level', from aequus 'level, equal, just'. The root image is a beam brought into balance.","cn":"adaequare“使与……相等”是 ad-“向”加 aequare“使平”，出自 aequus“平的、相等的、公正的”。词根画面是一根被调到水平的天平横梁。"},{"era":"-LY","en":"The suffix -ly is Old English -lice, from līc 'body, form'. It is a native English adverbial ending, unrelated to the Latin -e that other Latin adverbs carry.","cn":"后缀 -ly 是古英语 -lice，出自 līc“身体、形体”。这是英语本族的副词词尾，与其他拉丁副词所带的 -e 没有关系。"},{"era":"17C.","en":"Adequate enters English in the early 1600s as a learned word; the adverb adequately follows and spreads through formal prose.","cn":"adequate 于 17 世纪初作为学术词进入英语；副词 adequately 随后出现，并在正式书面语中扩散。"},{"era":"19C.","en":"Law, medicine, and engineering adopt it as a standard: an informed consent, a trained worker, a funded service. The adverb becomes a way to certify that a bar was cleared.","cn":"19 世纪，法律、医学与工程把它当作标准用语：知情同意、受过训练的工人、有资金的服务。这个副词于是成为“横杆已过”的认证方式。"},{"era":"20C.","en":"Audit culture institutionalizes it: 'adequately controlled', 'adequately documented', 'adequately funded'. Sufficiency is now something a checklist can record.","cn":"20 世纪的审计文化把它制度化：adequately controlled、adequately documented、adequately funded。充分性变成清单可以记录的东西。"}]},"similar":{"note":{"en":"The first group shares the adequ- shape but differs in suffix; the second compares adverbs of sufficiency.","cn":"第一组共享 adequ- 外形，但后缀不同；第二组比较表示“足够”的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adequate","ipa":"/ˈædɪkwət/","tag":"base adjective","definition":"enough for a purpose. It is the base; adequately is simply its adverb of manner.","definitionCN":"足以达到目的的。它是词基；adequately 只是它的方式副词。"},{"word":"adequacy","ipa":"/ˈædɪkwəsi/","tag":"abstract noun","definition":"the state of being enough. It names the condition, while adequately names how something is done.","definitionCN":"足够的状态。它命名状态，而 adequately 命名做事的方式。"},{"word":"inadequately","ipa":"/ɪnˈædɪkwətli/","tag":"negated form","definition":"not enough. The in- prefix reverses the scale, and in law it often signals a failure of duty.","definitionCN":"不够地。in- 前缀把天平反转，在法律语境中常表示义务未履行。"},{"word":"adequateness","ipa":"/ˈædɪkwətnəs/","tag":"rare noun","definition":"the quality of being adequate. It is uncommon because adequacy does the same job.","definitionCN":"充足的品质。它不常见，因为 adequacy 已承担同样功能。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sufficiently","ipa":"/səˈfɪʃəntli/","tag":"quantity","definition":"enough, usually with an emphasis on amount. It is more absolute than adequately and less willing to imply 'barely'.","definitionCN":"足够，通常强调数量。它比 adequately 更绝对，也更不愿暗示“勉强”。"},{"word":"suitably","ipa":"/ˈsuːtəbli/","tag":"fitness","definition":"in a way that fits the purpose or the occasion. It judges fit rather than amount.","definitionCN":"以适合目的或场合的方式。它判断的是适合，而不是数量。"},{"word":"acceptably","ipa":"/əkˈseptəbli/","tag":"social standard","definition":"to a level others will tolerate. It carries a social judgement that adequately often avoids.","definitionCN":"达到他人可容忍的程度。它带有社会评判，而 adequately 常回避这一点。"},{"word":"reasonably","ipa":"/ˈriːznəbli/","tag":"legal standard","definition":"to a degree a sensible person would accept. It is a standard in law, close to adequately in regulatory texts.","definitionCN":"达到理性人会接受的程度。它是法律标准，在监管文本中与 adequately 接近。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on the balance image and the -ly ending, then three abstract images about a floor rather than a ceiling.","cn":"先用五个围绕“天平”画面与 -ly 词尾的挂钩，再用三个关于“地板而非天花板”的抽象画面。"},"normal":[{"en":"ad- + aequus (equal) + -ly = to the level of the need. Water touching the line, not overflowing.","cn":"ad- + aequus（相等）+ -ly = 达到需要的刻度。水压线，而不溢出。"},{"en":"Adequate is equal-to; adequately is the manner of being equal-to. Enough is a balance, not a surplus.","cn":"adequate 是“与……相等”；adequately 是“以相等的方式”。够用是天平，不是盈余。"},{"en":"Adequately trained means able to do the job, not good at it. The adverb keeps excellence outside the door.","cn":"adequately trained 意为能干这活，而不是擅长。这个副词把“优秀”留在门外。"},{"en":"In court, adequately informed is a duty: the information must equal what a reasonable person needs.","cn":"在法庭上，adequately informed 是一项义务：信息必须等于理性人所需。"},{"en":"Note the mixed parentage: a Latin root wearing an Old English -ly. Latin adverbs would have taken -e instead.","cn":"注意混合血统：拉丁词根戴着古英语的 -ly。拉丁副词本会带 -e。"}],"abstract":[{"en":"Sufficiency is relational: nothing is adequate in itself, only adequate for a task, a person, a budget.","cn":"充分性是关系性的：没有东西自身充分，只对某项任务、某个人、某笔预算充分。"},{"en":"A standard that certifies the floor cannot describe the ceiling: adequacy says nothing about how good things could be.","cn":"认证地板的标尺描述不了天花板：充分性对事情能有多好一言不发。"},{"en":"Audit language turns a judgement into a checkbox, and the word loses its balance image to become a signature.","cn":"审计语言把判断变成勾选框，这个词也失去天平画面，变成一个签名。"}]},"examples":[{"en":"The report was adequately sourced but thinly argued.","cn":"这份报告资料来源尚可，但论证单薄。"},{"en":"Witnesses were adequately protected during the trial.","cn":"证人在庭审期间得到了充分保护。"},{"en":"The old bridge is adequately maintained, though not modernized.","cn":"这座旧桥维护得还算到位，只是没有现代化。"}],"dict_mnemonic":{"note":"ad-（向）+ aequus（相等）+ -ly（地）→ 做到与需要相等 → 足够地。注意 -ly 是英语本族词尾，不是拉丁的。","text":"ad- + aequus（相等）+ -ly → 与需要齐平 → 充分地、足够地","word":"adequately"},"root":"拉丁 adaequare“使与……相等”（ad- 向 + aequus 平的、相等的）+ 古英语副词后缀 -ly（-lice）→ 英语 adequately（17 世纪）。","sensesIntro":{"en":"The senses apply one balance image to different scales: a heated shelter, a passable voice, a powered trial, an informed patient, a trained worker, a funded library, a clear manual, and a room that is lit just enough.","cn":"这些义项把同一幅天平画面放在不同尺度上：供暖的收容所、过得去的歌声、有检验效能的试验、被充分告知的病人、受过训练的工人、资金充足的图书馆、清楚的手册，以及照明刚好的房间。"},"semanticMap":{"core":{"en":"Water rising exactly to the marked line on a gauge","cn":"水正好升到仪表上的刻度线"},"chain":["EQUAL TO THE NEED","ENOUGH","PASSABLE","RELIABLE","INFORMED","JUST ENOUGH"],"branches":[{"senses":"01","en":"ENOUGH FOR THE PURPOSE: sufficient to meet the need, not necessarily beyond it.","cn":"达到目的：够用，不必超出。"},{"senses":"02 · 07","en":"Two standards of quality: how well someone performs, how well a text explains.","cn":"两种质量标准：人做得多好，文本解释得多好。"},{"senses":"03 · 06","en":"Measured sufficiency: a sample large enough, a budget large enough.","cn":"可测量的充分：样本够大，预算够用。"},{"senses":"04 · 05","en":"Sufficiency applied to people: informed before consent, trained before work.","cn":"用于人的充分：同意前被告知，上岗前受训。"},{"senses":"08","en":"JUST BARELY: the line met with nothing to spare.","cn":"仅此而已：刚好压线，没有富余。"}]},"affixes":{"intro":{"en":"Adequately's family is built on adequate: the abstract noun, the negated forms, and the Latin root family of aequus.","cn":"adequately 的词族建立在 adequate 上：抽象名词、否定形式，以及 aequus 的拉丁词根家族。"},"latinIntro":{"en":"Latin aequus 'level, equal' is unusually productive: it yields equal, equality, equation, equator, and equivalent. In adaequare the preposition ad- adds direction, so the equality is aimed at something.","cn":"拉丁语 aequus“平的、相等的”产量异常高：它生出 equal、equality、equation、equator、equivalent。在 adaequare 中前缀 ad- 加了方向，因此这种相等是朝着某物的。"},"items":[{"word":"adequately","structure":"adequate + -ly (adverb)","meaning":"in a sufficient manner","meaningCN":"以充分的方式","example":"The room was adequately lit.","exampleCN":"房间照明充足。"},{"word":"adequate","structure":"Latin adaequatus (made equal to)","meaning":"enough, suitable","meaningCN":"足够的；适当的","example":"The supply is adequate for the month.","exampleCN":"供给够这个月用。"},{"word":"adequacy","structure":"adequate + -acy (abstract noun)","meaning":"the state of being enough","meaningCN":"充分；适当","example":"They questioned the adequacy of the sample.","exampleCN":"他们质疑样本是否充分。"},{"word":"inadequate","structure":"in- (not) + adequate","meaning":"not enough, not capable","meaningCN":"不充分的；不胜任的","example":"The lighting was inadequate.","exampleCN":"照明不足。"},{"word":"inadequacy","structure":"in- + adequacy","meaning":"a shortfall or a personal weakness","meaningCN":"不足；不胜任","example":"He felt a sense of inadequacy.","exampleCN":"他感到一种无力感。"},{"word":"equal","structure":"Latin aequalis (of the same level)","meaning":"the same in amount or status","meaningCN":"相等的；平等的","example":"The two sides are equal in strength.","exampleCN":"双方力量相等。"},{"word":"equation","structure":"aequare + -tion","meaning":"a statement that two things are equal","meaningCN":"方程式","example":"Solve the equation for x.","exampleCN":"解出 x 的方程。"},{"word":"equivalent","structure":"aequus + valere (be worth)","meaning":"equal in value or effect","meaningCN":"等值的；等同的","example":"A nod is equivalent to a yes here.","exampleCN":"在这里点头等同于说是。"},{"word":"equilibrium","structure":"aequus + libra (balance)","meaning":"a balanced state","meaningCN":"平衡","example":"The market reached equilibrium.","exampleCN":"市场达到均衡。"}],"latinEntries":[{"word":"aequus","structure":"Latin adjective","meaning":"level, equal, just","meaningCN":"平的；相等的；公正的","example":"Aequus is the root of adequate.","exampleCN":"aequus 是 adequate 的词根。"},{"word":"aequare","structure":"aequus + -are","meaning":"to make level or equal","meaningCN":"使平；使相等","example":"Aequare gives English equate.","exampleCN":"aequare 生出英语 equate。"},{"word":"adaequare","structure":"ad- + aequare","meaning":"to make equal to, come up to","meaningCN":"使与……相等；达到","example":"Adaequare is the direct source of adequate.","exampleCN":"adaequare 是 adequate 的直接来源。"}]}},{"word":"adherence","ipa_uk":"/əˈhɪərəns/","ipa_us":"/əˈhɪrəns/","definition_zh":"坚持；遵守；信奉；（物理）黏附","definition_en":"the act or state of sticking to something—materially, or in the sense of following a rule, belief, or regimen","core_image":"贴纸粘在玻璃上，揭下来还留着一圈胶痕","scene":"实验室的规章贴在墙上，每个人每天照着做。Nobody was punished into it; the staff followed the rules out of habit, and that quiet adherence kept the lab running.","sceneCN":"这里 adherence 是「对规则的遵守、坚持」（第 7 个义项：对规程的严格遵循）；句意：没有人是被罚出来的，实验人员出于习惯照着规章做，这种安静的遵守让实验室一直运转。图中可辨识物件：墙上规章、操作台、实验员、签到表。","pos":[{"tag":"n.","zh":"遵守；坚持（规则、信念）"},{"tag":"n.","zh":"（医）依从性；遵医嘱"},{"tag":"n.","zh":"黏附；附着"}],"collocations":[{"phrase":"strict adherence to","zh":"严格遵守……"},{"phrase":"treatment adherence","zh":"治疗依从性"},{"phrase":"adherence to protocol","zh":"对规程的遵守"},{"phrase":"adherence rate","zh":"依从率"},{"phrase":"adherence to tradition","zh":"对传统的坚守"}],"forms":[{"label":"原级（名词）","form":"adherence"},{"label":"动词（词基）","form":"adhere"},{"label":"形容词／名词（人）","form":"adherent"},{"label":"复数","form":"adherences"}],"derivatives":[{"word":"adhere","pos":"v.","zh":"黏附；坚持；遵守"},{"word":"adherent","pos":"adj./n.","zh":"附着的；拥护者"},{"word":"adhesion","pos":"n.","zh":"黏附（物理）；粘连"},{"word":"adhesive","pos":"adj./n.","zh":"黏合的；黏合剂"},{"word":"nonadherence","pos":"n.","zh":"不依从"}],"senses":[{"no":"01","title":"Loyal attachment to a belief","titleCN":"对信念的坚守","definition":"the state of holding firmly to a belief, practice, or tradition","definitionCN":"坚定持有某种信念、做法或传统的状态","example":"The community's adherence to the old rites surprised the anthropologist.","exampleCN":"这个社群对古老仪式的坚守让人类学家感到惊讶。","why":"Adherence is Latin adhaerere, 'stick to'. The physical image carries over unchanged: a belief is something one clings to, and the noun measures how firmly the grip holds.","whyCN":"adherence 出自拉丁语 adhaerere“黏附于”。物理画面原封不动地延续：信念是人紧抓的东西，而这个名词衡量抓得多牢。"},{"no":"02","title":"Following a treatment plan","titleCN":"遵医嘱执行治疗方案","definition":"in medicine, the extent to which a patient takes medication or follows a regimen as prescribed","definitionCN":"医学中指病人按处方服药或执行方案的程度","example":"Poor adherence to the drug schedule reduced its effect.","exampleCN":"用药时间表执行不佳，削弱了药效。","why":"Medicine borrowed the word because a regimen is a line the patient must stay on. Adherence is now preferred to compliance: it frames the patient as a partner who sticks, not a subject who obeys.","whyCN":"医学借用这个词，因为治疗方案是一条病人必须待在里面的线。现在 adherence 比 compliance 更受青睐：它把病人当作“黏住的伙伴”，而不是“服从的对象”。"},{"no":"03","title":"The state of being physically attached","titleCN":"物理上的黏附状态","definition":"of materials or surfaces, the condition of being stuck or bonded to something","definitionCN":"指材料或表面黏着、结合在另一物上的状态","example":"The adherence of the coating depends on surface roughness.","exampleCN":"涂层的附着力取决于表面粗糙度。","why":"This is the original, material sense. Modern technical English usually gives it to adhesion, while adherence keeps the figurative load—so the two words divided the work rather than changing meaning.","whyCN":"这是原初的、物质性的义项。现代技术英语通常把它交给 adhesion，而 adherence 保留比喻负担——两个词是分工，而不是改变了含义。"},{"no":"04","title":"Observance of agreed terms","titleCN":"对约定条款的遵守","definition":"in law, the fact of acting in accordance with the terms of a contract, treaty, or standard","definitionCN":"法律中指行为符合合同、条约或标准的条款","example":"Adherence to the contract was reviewed each quarter.","exampleCN":"每季度都审查合同的履行情况。","why":"A contract is a set of lines, and parties are held to them. Adherence here is legal: it asks whether conduct stayed attached to the written terms, and it can be tested in a hearing.","whyCN":"合同是一组线，各方被按在线上。这里的 adherence 是法律性的：它问行为是否始终贴着书面条款，并可在听证中被检验。"},{"no":"05","title":"Allegiance to a party or cause","titleCN":"对党派或事业的归附","definition":"the body of supporters of a movement, or their collective loyalty","definitionCN":"指某一运动支持者的群体，或他们的集体忠诚","example":"The sect's adherence grew fastest in the industrial towns.","exampleCN":"该教派的信众在工业城镇增长最快。","why":"The noun can name a following as well as a feeling. Adherence then measures a social fact—how many people are stuck to a movement—not only an inner conviction.","whyCN":"这个名词既可以指一种感情，也可以指一群人。此时的 adherence 衡量一个社会事实——有多少人黏在这个运动上——而不只是内心确信。"},{"no":"06","title":"Attachment of cells or bacteria","titleCN":"细胞或细菌的附着","definition":"in biology, the binding of cells, bacteria, or molecules to a surface or to each other","definitionCN":"生物学中指细胞、细菌或分子结合到表面或彼此结合","example":"Bacterial adherence to the gut wall is the first step of infection.","exampleCN":"细菌附着在肠壁上，是感染的第一步。","why":"Microbiology returns the word to its literal root. A cell that adheres has molecular hooks; the noun names the binding, and blocking that adherence becomes a therapeutic target.","whyCN":"微生物学把这个词送回字面词根。黏附的细胞有分子钩子；名词命名这种结合，而阻断这种附着就成了治疗靶点。"},{"no":"07","title":"Exact compliance with a protocol","titleCN":"对规程的严格遵循","definition":"the quality of following every step of a procedure without deviation","definitionCN":"指不偏离地执行某一程序每一步的品质","example":"Strict adherence to the sterilization steps prevented contamination.","exampleCN":"严格遵循消毒步骤防止了污染。","why":"Strict signals zero tolerance for drift. In a protocol every step is a point of attachment; skip one and the chain of adherence breaks, which is why the word appears in audits.","whyCN":"strict 表示对漂移零容忍。在规程中每一步都是一个附着点；跳过一步，遵守的链条就断了，因此这个词常出现在审计里。"},{"no":"08","title":"A commitment that costs the follower","titleCN":"要付出代价的追随","definition":"the condition of belonging to a group, often with personal consequences","definitionCN":"指归属于某一群体，且常带个人代价","example":"His adherence to the movement cost him his teaching post.","exampleCN":"他对该运动的追随让他丢掉了教职。","why":"Adherence can be a possession a person carries and pays for. The noun then describes an identity held over time rather than a single decision, and the price makes the sticking visible.","whyCN":"adherence 可以是一个人随身携带并为之付出代价的所属物。这个名词于是描述一种长期持有的身份，而不是一次决定；代价让“黏住”变得可见。"}],"etymology":{"intro":{"en":"Adherence is a Latin-derived noun: adhaerere 'stick to' plus the abstract ending -entia. Its base verb is adhere, and its rival adhesion split off to take the physical sense.","cn":"adherence 是拉丁来源的名词：adhaerere“黏附于”加抽象词尾 -entia。它的基础动词是 adhere，而竞争者 adhesion 分出去承担物理义。"},"items":[{"era":"LATIN","en":"Adhaerere 'stick to, cling' is ad- 'to' plus haerere 'to stick, adhere'. The deeper root is commonly reconstructed as PIE *ghais- 'to stick', though the reconstruction is uncertain and the circle of cognates is small.","cn":"adhaerere“黏附、紧贴”是 ad-“向”加 haerere“黏住”。更深词根通常被重构为原始印欧语 *ghais-“黏”，但这一重构并不确定，同源词范围也很小。"},{"era":"-ENTIA","en":"The suffix -entia forms abstract nouns from present participles, so adhaerentia means 'the state of sticking'. English -ence descends from it through French.","cn":"后缀 -entia 从现在分词构成抽象名词，因此 adhaerentia 意为“黏着的状态”。英语 -ence 经由法语由它而来。"},{"era":"14C.","en":"Adherence enters English through Old French adherance and Latin adhaerentia, first for attachment to a faith or a party.","cn":"adherence 经古法语 adherance 与拉丁语 adhaerentia 进入英语，最初指对信仰或党派的归附。"},{"era":"17C.","en":"Adhesion is coined for the material sense, and the two words settle into a division of labour: adhesion for surfaces, adherence for beliefs and rules.","cn":"17 世纪为物质义造出 adhesion，两个词随后稳定分工：adhesion 用于表面，adherence 用于信念与规则。"},{"era":"20C.","en":"Medicine makes adherence a measurable behaviour in clinical trials, replacing the older compliance and giving the word a numerical rate.","cn":"20 世纪，医学把 adherence 变成临床试验中可测量的行为，取代较早的 compliance，并让这个词有了数值化的“率”。"}]},"similar":{"note":{"en":"The first group shares the haer- root and shows how the family divides its labour; the second compares nouns of loyalty and compliance.","cn":"第一组共享 haer- 词根，展示这个词族如何分工；第二组比较表示“忠诚”与“遵守”的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adhesion","ipa":"/əˈhiːʒn/","tag":"physical","definition":"the physical sticking of two surfaces. It kept the material sense that adherence largely gave up.","definitionCN":"两个表面的物理黏合。它保留了 adherence 大体放弃的物质义。"},{"word":"adhere","ipa":"/əˈhɪə/","tag":"base verb","definition":"to stick to, literally or figuratively. Adherence is the noun of this act.","definitionCN":"黏附，字面或比喻皆可。adherence 是这一动作的名词。"},{"word":"adherent","ipa":"/əˈhɪərənt/","tag":"person","definition":"a supporter of a party or idea. It names the person, while adherence names the loyalty.","definitionCN":"党派或思想的拥护者。它命名人，而 adherence 命名忠诚。"},{"word":"adhesive","ipa":"/əˈhiːsɪv/","tag":"substance","definition":"a substance that sticks things together. It is an object, not the relationship.","definitionCN":"把东西粘在一起的物质。它是物件，而不是关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"compliance","ipa":"/kəmˈplaɪəns/","tag":"obedience","definition":"doing what is required. It stresses external requirement, while adherence stresses the grip of the rule on the person.","definitionCN":"按要求去做。它强调外部要求，而 adherence 强调规则对人的抓握。"},{"word":"loyalty","ipa":"/ˈlɔɪəlti/","tag":"allegiance","definition":"faithfulness to a person or group. It is emotional and personal, broader than adherence to a rule.","definitionCN":"对人或群体的忠实。它偏情感与人际，比“对规则的 adherence”更宽。"},{"word":"fidelity","ipa":"/fɪˈdeləti/","tag":"exactness","definition":"faithfulness in detail, as to an original. It often measures accuracy of copying rather than loyalty.","definitionCN":"在细节上忠于原作。它常衡量复制的准确，而不是忠诚。"},{"word":"devotion","ipa":"/dɪˈvəʊʃn/","tag":"commitment","definition":"deep dedication. It is warmer and more voluntary than adherence, which can be procedural.","definitionCN":"深厚的投入。它比 adherence 更温暖、更自愿，而后者可以是程序性的。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on the 'stick to' image and the adherence/adhesion split, then three abstract images about attachment as a relationship.","cn":"先用五个围绕“黏附”画面与 adherence/adhesion 分工的挂钩，再用三个关于“依附作为关系”的抽象画面。"},"normal":[{"en":"ad- (to) + haerere (stick) = stick to. A rule you adhere to is a line you stay glued to.","cn":"ad-（向）+ haerere（黏）= 黏向。你 adhere to 的规则，是你黏住的一条线。"},{"en":"Adherence vs adhesion: adhesion is tape on a surface, adherence is a person on a principle.","cn":"adherence 与 adhesion：adhesion 是贴在表面的胶带，adherence 是贴在原则上的一个人。"},{"en":"Treatment adherence is measured as a rate: how many doses actually got taken.","cn":"治疗依从性被量成一个比率：实际吃了多少剂。"},{"en":"Strict adherence to protocol has no tolerance for drift: one skipped step breaks the chain.","cn":"严格遵循规程对漂移零容忍：跳过一步，链条就断。"},{"en":"Note the small family: adhere, adherent, adhesion, adhesive—same root, four jobs.","cn":"注意这个小家族：adhere、adherent、adhesion、adhesive——同根，四种分工。"}],"abstract":[{"en":"Adherence is a relationship between a person and a text: it exists only while both are held together.","cn":"adherence 是人与文本之间的一种关系：只有两者被拉住时它才存在。"},{"en":"The same word covers glue and faith, which suggests how much of belief is habit rather than argument.","cn":"同一个词覆盖胶水与信仰，这暗示信念中有多少是习惯而非论证。"},{"en":"Measurement changes the thing measured: once adherence becomes a rate, a patient can be scored.","cn":"测量改变被测量之物：一旦 adherence 变成比率，病人就可以被打分。"}]},"examples":[{"en":"Adherence to the safety code is checked before every shift.","cn":"每班开工前都要检查安全规程的遵守情况。"},{"en":"The study tracked adherence to the exercise program for a year.","cn":"该研究追踪了一年里对锻炼计划的执行情况。"},{"en":"The paint's adherence to damp concrete was poor.","cn":"这种漆在潮湿混凝土上的附着力很差。"}],"dict_mnemonic":{"note":"ad-（向）+ haerere（黏住）+ -ence（状态）→ 黏在规则或信念上的状态 → 遵守、坚持。物质义现在多交给 adhesion。","text":"ad- + haerere（黏）+ -ence → 黏住的状态 → 遵守；坚持；黏附","word":"adherence"},"root":"拉丁 adhaerere“黏附于”（ad- 向 + haerere 黏住）+ 拉丁抽象后缀 -entia（经法语 -ance）→ 英语 adherence（14 世纪）。","sensesIntro":{"en":"One 'stick to' image spreads across domains: a tradition held, a drug schedule kept, a coating bonded, a contract observed, a sect followed, a bacterium attached, a protocol obeyed exactly, and a loyalty that costs something.","cn":"同一幅“黏附”画面铺开到各个领域：被坚守的传统、被执行的用药表、被结合的涂层、被遵守的合同、被追随的教派、被附着的细菌、被严格执行的规程，以及要付出代价的忠诚。"},"semanticMap":{"core":{"en":"A sticker pressed onto glass and refusing to lift","cn":"贴纸按在玻璃上，不肯翘起"},"chain":["STICK TO","CLING","LOYALTY","COMPLIANCE","REGIMEN","MEMBERSHIP"],"branches":[{"senses":"01 · 05","en":"Belief and allegiance: what a person holds, and who holds it with them.","cn":"信念与归附：一个人持有什么，以及谁和他一起持有。"},{"senses":"02","en":"TREATMENT: a patient follows the prescribed schedule.","cn":"治疗：病人按处方服药。"},{"senses":"03 · 06","en":"Material sticking at two scales: a coating on a surface, a cell on a wall.","cn":"两个尺度的物质黏附：涂层在表面，细胞在壁上。"},{"senses":"07","en":"PROTOCOL: executing every step without deviation.","cn":"规程：不偏离地执行每一步。"},{"senses":"04 · 08","en":"COSTLY ALLEGIANCE: keeping to a document, or following a group at personal cost.","cn":"有代价的归属：遵守一份文件，或追随一个群体而付出个人代价。"}]},"affixes":{"intro":{"en":"Adherence's family is built on haerere: the verb, the person noun, the physical noun, the adjective, and the negated clinical form.","cn":"adherence 的词族建立在 haerere 上：动词、指人名词、物理名词、形容词，以及临床上的否定形式。"},"latinIntro":{"en":"Latin haerere 'stick' also gives coherent and inherent, where the sticking is metaphorical: parts that stick together, qualities that stick inside. English -ence and -ion divided the abstract and the material results.","cn":"拉丁语 haerere“黏”还生出 coherent 与 inherent，其中的黏是比喻性的：黏在一起的部分，黏在内部的属性。英语的 -ence 与 -ion 分担了抽象结果与物质结果。"},"items":[{"word":"adherence","structure":"ad- + haerere + -ence","meaning":"the act of sticking to","meaningCN":"黏附；遵守","example":"Adherence to the plan was high.","exampleCN":"计划的执行度很高。"},{"word":"adhere","structure":"ad- + haerere (verb)","meaning":"to stick or to follow","meaningCN":"黏附；坚持","example":"The label adheres to the jar.","exampleCN":"标签黏在罐子上。"},{"word":"adherent","structure":"adhere + -ent (person/adj)","meaning":"a supporter; sticking","meaningCN":"拥护者；附着的","example":"He is an adherent of the theory.","exampleCN":"他是这一理论的拥护者。"},{"word":"adhesion","structure":"ad- + haerere + -ion","meaning":"physical sticking","meaningCN":"黏附；粘连","example":"Adhesion depends on the glue.","exampleCN":"黏附取决于胶水。"},{"word":"adhesive","structure":"adhesion + -ive","meaning":"sticking; a glue","meaningCN":"黏合的；黏合剂","example":"Use a strong adhesive.","exampleCN":"使用强力黏合剂。"},{"word":"coherent","structure":"co- (together) + haerere","meaning":"sticking together logically","meaningCN":"连贯的","example":"The argument is coherent.","exampleCN":"论证是连贯的。"},{"word":"inherent","structure":"in- (in) + haerere","meaning":"sticking inside, intrinsic","meaningCN":"内在的；固有的","example":"Risk is inherent in the work.","exampleCN":"风险是这份工作固有的。"},{"word":"nonadherence","structure":"non- (not) + adherence","meaning":"failure to follow a regimen","meaningCN":"不依从","example":"Nonadherence undermines treatment.","exampleCN":"不依从会削弱治疗。"},{"word":"adhesively","structure":"adhesive + -ly","meaning":"in a sticking manner","meaningCN":"以黏合的方式","example":"The layers bond adhesively.","exampleCN":"各层以黏合方式结合。"}],"latinEntries":[{"word":"haerere","structure":"Latin verb","meaning":"to stick, cling","meaningCN":"黏住；紧贴","example":"Haerere is the root of adhere.","exampleCN":"haerere 是 adhere 的词根。"},{"word":"adhaerere","structure":"ad- + haerere","meaning":"to stick to","meaningCN":"黏附于","example":"Adhaerere gives English adhere.","exampleCN":"adhaerere 生出英语 adhere。"},{"word":"adhaerentia","structure":"adhaerens + -ia","meaning":"a sticking state","meaningCN":"黏着的状态","example":"Adhaerentia became adherence.","exampleCN":"adhaerentia 变成 adherence。"}]}},{"word":"adjustment","ipa_uk":"/əˈdʒʌstmənt/","ipa_us":"/əˈdʒʌstmənt/","definition_zh":"调整；调节；适应；理算","definition_en":"a small change made so that something fits, works, or matches a standard or situation","core_image":"把歪挂的画框轻轻推正，只动一厘米","scene":"新椅子坐上去总差一点，师傅拧了拧扶手下的旋钮。The back moved forward by two degrees, and that small adjustment was enough to make the chair comfortable.","sceneCN":"这里 adjustment 是「（小幅）调整」（第 1 个义项：使更合用的微调）；句意：椅背往前挪了两度，这一处小小的调整就让椅子好坐了。图中可辨识物件：办公椅、扶手旋钮、坐姿、水平仪。","pos":[{"tag":"n.","zh":"调整；调节"},{"tag":"n.","zh":"适应；调节过程"},{"tag":"n.","zh":"（账目、理赔）理算；调整额"}],"collocations":[{"phrase":"make an adjustment","zh":"作调整"},{"phrase":"adjustment to","zh":"对……的调整"},{"phrase":"price adjustment","zh":"价格调整"},{"phrase":"structural adjustment","zh":"结构调整"},{"phrase":"adjustment period","zh":"适应期"}],"forms":[{"label":"原级（名词）","form":"adjustment"},{"label":"复数","form":"adjustments"},{"label":"动词（词基）","form":"adjust"},{"label":"形容词","form":"adjustable"}],"derivatives":[{"word":"adjust","pos":"v.","zh":"调整；适应"},{"word":"adjustable","pos":"adj.","zh":"可调节的"},{"word":"adjuster","pos":"n.","zh":"调节器；理算员"},{"word":"readjust","pos":"v.","zh":"重新调整"},{"word":"maladjustment","pos":"n.","zh":"适应不良"}],"senses":[{"no":"01","title":"A small change that improves fit","titleCN":"使更合用的微调","definition":"a minor alteration made so that something works better or fits more closely","definitionCN":"为使某物更好用或更贴合而作的小改动","example":"A minor adjustment to the seat made the long drive comfortable.","exampleCN":"座椅稍作调整，长途驾驶就舒服了。","why":"Adjustment descends from Latin iuxta, 'near'. To adjust is to bring things near to each other; the noun names the act of closing that gap, and it implies the change is small rather than wholesale.","whyCN":"adjustment 源自拉丁语 iuxta“靠近”。adjust 是把两样东西拉近；这个名词命名把缝隙合拢的动作，并暗示改动是小的，而不是推倒重来。"},{"no":"02","title":"Adaptation to a new setting","titleCN":"对新环境的适应","definition":"in psychology, the process of becoming comfortable and functional in a new environment or role","definitionCN":"心理学中指在新环境或新角色中变得自在并能运转的过程","example":"The child's adjustment to the new school took a term.","exampleCN":"孩子适应新学校花了一个学期。","why":"Psychology extends 'bring near' from objects to people and places: a person must be brought into line with a setting. Adjustment here is a process over months, not a single turn of a knob.","whyCN":"心理学把“拉近”从物件扩展到人与场所：一个人必须被调到与某个环境相合。这里的 adjustment 是持续数月的过程，不是拧一下旋钮。"},{"no":"03","title":"A correction to an account or price","titleCN":"账目或价格的调整","definition":"in finance, an entry that corrects or updates a sum, a price, or a balance","definitionCN":"财务中指修正或更新金额、价格或余额的记账","example":"The final invoice included an adjustment for the damaged goods.","exampleCN":"最终账单包含一项针对损坏货物的调整。","why":"Bookkeeping requires the two sides to be brought near to equality. An adjustment is the entry that closes the difference, so the word names both the act and the amount it moves.","whyCN":"记账要求两边被拉到接近相等。adjustment 就是合上差额的那一笔；因此这个词既指动作，也指它移动的金额。"},{"no":"04","title":"A device that sets a mechanism","titleCN":"调节装置","definition":"a knob, screw, or control whose purpose is to set a machine to the wanted position","definitionCN":"用于把机器调到所需位置的旋钮、螺丝或控制器","example":"The thermostat's adjustment is behind the cover plate.","exampleCN":"恒温器的调节装置在盖板后面。","why":"Here adjustment is a part, not an act: a fitting built so that the user can bring the machine near to the desired setting. The noun shifts from event to object.","whyCN":"这里的 adjustment 是零件，而不是动作：一个被造出来让用户把机器拉到所需设定的装置。名词从事件滑向了物件。"},{"no":"05","title":"The settling of an insurance claim","titleCN":"保险理赔的理算","definition":"in insurance, the process of assessing a loss and agreeing the amount to be paid","definitionCN":"保险中指评估损失并商定赔付金额的过程","example":"Loss adjustment took six weeks after the flood.","exampleCN":"洪水过后，损失理算花了六周。","why":"Insurance uses 'adjust' for bringing a claimed loss and a payment into agreement. The noun is institutional: it names a procedure with assessors, figures, and a signature, not a tweak of a dial.","whyCN":"保险用 adjust 表示把申报的损失与赔付拉到一致。这个名词是制度性的：它命名一套有理算员、数字与签字的程序，而不是拧一下旋钮。"},{"no":"06","title":"A statistical correction for bias","titleCN":"统计上的校正","definition":"in statistics, a change to an estimate that removes the distorting effect of a known factor","definitionCN":"统计学中指修正估计值、去除已知因素扭曲效应的处理","example":"The model included an adjustment for age and income.","exampleCN":"模型包含对年龄与收入的校正。","why":"Statistics adjusts when a raw comparison is distorted. The adjustment brings the estimate nearer to the truth by removing the effect of a confounder, so the word keeps its root sense of closing a gap.","whyCN":"当原始比较被扭曲时，统计就要调整。校正通过去除混杂因素的作用，把估计值拉近真相，因此这个词保留了“合拢差距”的词根义。"},{"no":"07","title":"A change of posture or position","titleCN":"姿势或位置的调整","definition":"a quick change in how the body is placed or how something is held","definitionCN":"指身体摆放方式或持物方式的快速改变","example":"He made a quick adjustment of his grip on the rope.","exampleCN":"他迅速调整了握绳的姿势。","why":"The body is the most immediate thing we bring near to a task. This sense is physical and momentary: the change lasts only as long as the hold does.","whyCN":"身体是我们最先拉近任务的东西。这个义项是物理性的、瞬时的：改动只在握持持续期间有效。"},{"no":"08","title":"Structural change in an economy","titleCN":"经济或体系的结构性调整","definition":"in policy, a large rebalancing of an economy or institution to make it sustainable","definitionCN":"政策中指对经济或机构进行大规模再平衡以使其可持续","example":"Structural adjustment required the country to cut subsidies.","exampleCN":"结构调整要求该国削减补贴。","why":"At large scale, adjustment names painful rebalancing: a system is brought near to a sustainable line. The word's smallness disappears, and the change becomes a policy with winners and losers.","whyCN":"在大尺度上，adjustment 指痛苦的再平衡：一个体系被拉到可持续的线上。这个词的“微小”消失了，改动变成一项有赢家有输家的政策。"}],"etymology":{"intro":{"en":"Adjustment is adjust plus -ment. The base came into English from Old French, itself from Late Latin adiuxta 'near to'—so the whole family is built on the idea of being close.","cn":"adjustment 是 adjust 加 -ment。词基经古法语进入英语，而古法语又出自晚期拉丁语 adiuxta“靠近”——整个词族都建立在“接近”这一观念上。"},"items":[{"era":"LATIN","en":"Iuxta 'close by, near' combines with ad- 'to' to give adiuxta 'near to'. The deeper origin of iuxta is commonly linked to a root meaning 'to join', but this is a reconstruction rather than a recorded fact.","cn":"iuxta“在旁边、靠近”与 ad-“向”结合，得到 adiuxta“靠近”。iuxta 的更早来源常被联系到意为“连接”的词根，但这是重构而非有记录的事实。"},{"era":"FRENCH","en":"Old French ajoster, later ajuster, means 'join, bring together' and also 'conform, adapt'. French dropped the Latin -d-, so the word arrived without it.","cn":"古法语 ajoster（后作 ajuster）意为“连接、聚拢”，也有“使符合、适应”之义。法语丢掉了拉丁语的 -d-，因此这个词到达英语时没有它。"},{"era":"-MENT","en":"The suffix -ment comes from Latin -mentum through French -ment. It forms nouns of result or instrument, which is why adjustment can name both a change and a knob.","cn":"后缀 -ment 经法语 -ment 来自拉丁语 -mentum。它构成表示结果或工具的名词，这就是为什么 adjustment 既能指改动，也能指旋钮。"},{"era":"14C.","en":"English ajusten appears in the late 1300s meaning 'to fit, arrange'. The spelling adjust, with -d- restored, is generally attributed to Latin ad- influence rather than to French.","cn":"英语 ajusten 于 14 世纪末出现，意为“使适合、安排”。恢复 -d- 的拼写 adjust，一般认为受拉丁语 ad- 影响，而不是来自法语。"},{"era":"17–20C.","en":"The noun becomes technical in turn: legal and financial settlement in the 17th century, mechanical controls in the 18th, statistical correction and psychological adaptation in the 20th.","cn":"这个名词依次技术化：17 世纪的法律与财务结算，18 世纪的机械控制，20 世纪的统计校正与心理适应。"}]},"similar":{"note":{"en":"The first group shares the adjust- shape and splits act, capacity, person, and repetition; the second compares nouns of change.","cn":"第一组共享 adjust- 外形，并分出动作者、能力、执行者与重复；第二组比较表示“改变”的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adjust","ipa":"/əˈdʒʌst/","tag":"base verb","definition":"to change slightly so as to fit. The noun adjustment is the act or result of this verb.","definitionCN":"为适合而微调。名词 adjustment 是这个动词的动作或结果。"},{"word":"adjustable","ipa":"/əˈdʒʌstəbl/","tag":"capacity","definition":"able to be adjusted. It describes a built-in capacity, not an event.","definitionCN":"可被调节的。它描述内置的能力，而不是一次事件。"},{"word":"adjuster","ipa":"/əˈdʒʌstə/","tag":"person/tool","definition":"a person who settles claims, or a device that adjusts. It splits into human and mechanical roles.","definitionCN":"理赔理算员，或调节装置。它分成人、机两种角色。"},{"word":"readjustment","ipa":"/ˌriːəˈdʒʌstmənt/","tag":"repetition","definition":"a further adjustment after a first one. The re- marks a second closing of the gap.","definitionCN":"第一次调整之后的再次调整。re- 标记缝隙的第二次合拢。"}]},{"heading":"NEAR MEANING","entries":[{"word":"modification","ipa":"/ˌmɒdɪfɪˈkeɪʃn/","tag":"change","definition":"a change to a thing's form. It is broader and can be large, while adjustment usually implies a small correction.","definitionCN":"对事物形态的改动。它更宽，也可以很大，而 adjustment 通常暗示小幅修正。"},{"word":"alteration","ipa":"/ˌɔːltəˈreɪʃn/","tag":"change","definition":"a change that makes something different. It does not carry the sense of fitting a target.","definitionCN":"使某物不同的改变。它不带“对准某个目标”的意思。"},{"word":"calibration","ipa":"/ˌkælɪˈbreɪʃn/","tag":"instrument","definition":"setting an instrument against a standard. It is a technical subclass of adjustment, judged by accuracy.","definitionCN":"按标准校准仪器。它是 adjustment 的技术子类，以准确度为判据。"},{"word":"adaptation","ipa":"/ˌædæpˈteɪʃn/","tag":"fit","definition":"fitting to new conditions over time. It is often larger and slower than an adjustment.","definitionCN":"随时间适应新条件。它通常比一次 adjustment 更大、更慢。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on iuxta 'near' and the smallness of the change, then three abstract images about closing a gap.","cn":"先用五个围绕 iuxta“靠近”与“改动之小”的挂钩，再用三个关于“合拢差距”的抽象画面。"},"normal":[{"en":"iuxta = near. To adjust is to bring two things near; an adjustment is the closing of the gap.","cn":"iuxta = 靠近。adjust 是把两样东西拉近；adjustment 是差距的合拢。"},{"en":"An adjustment is a centimeter, not a remodel. If you rebuild the chair, you are not adjusting it.","cn":"adjustment 是一厘米，不是翻修。若你把椅子重做，就不是在调整它。"},{"en":"The French lost the -d-: ajoster came first, adjust came back later with Latin manners.","cn":"法语丢掉了 -d-：先有 ajoster，adjust 后来带着拉丁式的做派回来。"},{"en":"-ment does double duty: the act of adjusting, and the knob that adjusts.","cn":"-ment 身兼两职：调整这个动作，以及执行调整的旋钮。"},{"en":"Structural adjustment is the same word at national scale: a whole economy brought near to a sustainable line.","cn":"structural adjustment 是同一个词放大到国家尺度：整个经济被拉到可持续的线上。"}],"abstract":[{"en":"Every adjustment assumes a target: without a standard there is nothing to be near to.","cn":"每一次调整都预设一个目标：没有标准，就无所谓靠近。"},{"en":"Small changes are cheap individually and expensive in aggregate: a system adjusted daily never settles.","cn":"小改动单次便宜，累积起来昂贵：天天调整的系统永远安定不下来。"},{"en":"Naming a correction 'adjustment' can soften it: the word makes a cut sound like a fine-tuning.","cn":"把一项削减叫作 adjustment 能起软化作用：这个词让砍削听起来像微调。"}]},"examples":[{"en":"The telescope needs a small adjustment before each observation.","cn":"每次观测前望远镜都需要小幅调整。"},{"en":"Her adjustment to life abroad was harder than expected.","cn":"她适应国外生活比预想的更难。"},{"en":"The company announced a price adjustment for the new year.","cn":"公司宣布了新年度的价格调整。"}],"dict_mnemonic":{"note":"iuxta（靠近）+ ad-（向）+ -ment（名词）→ 把两者拉近的动作 → 调整。法语先丢了 -d-，英语又按拉丁语补回来。","text":"ad- + iuxta（靠近）+ -ment → 拉近、合拢差距 → 调整；适应","word":"adjustment"},"root":"晚期拉丁 adiuxta“靠近”（ad- 向 + iuxta 在旁边）+ 法语 -ment（拉丁 -mentum）→ 英语 adjustment（14 世纪后）。","sensesIntro":{"en":"The senses all close a gap, at different scales: a seat brought to comfort, a child brought into a school, a ledger brought to balance, a knob built to set a machine, a claim settled, a statistic corrected, a grip repositioned, and an economy rebalanced.","cn":"这些义项都在合拢某个差距，只是尺度不同：座椅被调到舒适、孩子被调进学校、账本被调平、旋钮被造来设定机器、理赔被结算、统计被校正、握姿被重新摆放，以及经济被再平衡。"},"semanticMap":{"core":{"en":"A picture frame nudged one centimetre back to level","cn":"画框被推回一厘米以恢复水平"},"chain":["BRING NEAR","MAKE RIGHT","SMALL CHANGE","FIT","RECALIBRATE","SETTLE"],"branches":[{"senses":"01","en":"THE TWEAK: a small change made to fit a purpose better.","cn":"微调：为合用而作的小改动。"},{"senses":"02 · 08","en":"Adaptation at two scales: a person entering a school, an economy entering a new balance.","cn":"两个尺度的适应：一个人进入学校，一个经济进入新平衡。"},{"senses":"03 · 05","en":"Money brought into agreement: an invoice entry, an insurance settlement.","cn":"把钱拉到一致：账单上的一笔，保险的一次理算。"},{"senses":"04 · 06","en":"Instruments and models: a knob that sets a machine, a correction that sets an estimate.","cn":"器械与模型：设定机器的旋钮，校正估计值的处理。"},{"senses":"07","en":"THE BODY: a quick change of posture or of the way something is held.","cn":"身体：姿势与持物方式的快速改变。"}]},"affixes":{"intro":{"en":"Adjustment's family is built on adjust: the verb, the capacity adjective, the person or device noun, and the re- and mal- variants.","cn":"adjustment 的词族建立在 adjust 上：动词、表能力的形容词、指人或装置的名词，以及 re- 与 mal- 的变体。"},"latinIntro":{"en":"The root iuxta 'near' is thin in English but visible in juxtapose, where things are placed side by side. Latin -mentum supplies the result noun, and French supplied the verb in its clipped form.","cn":"词根 iuxta“靠近”在英语里很单薄，但在 juxtapose 中可见——那是把东西并排放置。拉丁语 -mentum 提供结果名词，法语则以截短的形式提供了动词。"},"items":[{"word":"adjustment","structure":"adjust + -ment (result noun)","meaning":"a change or a settling","meaningCN":"调整；理算","example":"The adjustment improved the fit.","exampleCN":"这次调整改善了贴合度。"},{"word":"adjust","structure":"ad- + iuxta (near)","meaning":"to bring near, to set right","meaningCN":"调整；使适应","example":"Adjust the mirror before driving.","exampleCN":"开车前调好后视镜。"},{"word":"adjustable","structure":"adjust + -able","meaning":"able to be adjusted","meaningCN":"可调节的","example":"The seat is adjustable.","exampleCN":"座椅可调节。"},{"word":"adjuster","structure":"adjust + -er (person/tool)","meaning":"one who or that which adjusts","meaningCN":"理算员；调节器","example":"The claim adjuster visited the site.","exampleCN":"理赔员到现场查看。"},{"word":"readjust","structure":"re- (again) + adjust","meaning":"to adjust again","meaningCN":"重新调整","example":"We had to readjust the schedule.","exampleCN":"我们不得不重排日程。"},{"word":"readjustment","structure":"re- + adjustment","meaning":"a second adjustment","meaningCN":"再调整","example":"The readjustment cost another week.","exampleCN":"再调整又花了一周。"},{"word":"maladjustment","structure":"mal- (badly) + adjustment","meaning":"poor adaptation","meaningCN":"适应不良","example":"Maladjustment showed in his grades.","exampleCN":"适应不良体现在他的成绩上。"},{"word":"juxtapose","structure":"iuxta + ponere (place)","meaning":"to place side by side","meaningCN":"并置","example":"The exhibit juxtaposes old and new.","exampleCN":"展览把新旧并置。"},{"word":"juxtaposition","structure":"juxtapose + -ition","meaning":"a side-by-side placing","meaningCN":"并置","example":"The juxtaposition is striking.","exampleCN":"这种并置很醒目。"}],"latinEntries":[{"word":"iuxta","structure":"Latin adverb/preposition","meaning":"close by, near","meaningCN":"在旁边；靠近","example":"Iuxta underlies adjust.","exampleCN":"iuxta 是 adjust 的底层词根。"},{"word":"adiuxta","structure":"ad- + iuxta","meaning":"near to","meaningCN":"靠近……","example":"Adiuxta became Old French ajuster.","exampleCN":"adiuxta 变成古法语 ajuster。"},{"word":"mentum","structure":"Latin noun suffix","meaning":"result or instrument","meaningCN":"结果或工具","example":"-mentum became English -ment.","exampleCN":"-mentum 变成英语 -ment。"}]}},{"word":"administrative","ipa_uk":"/ˌædmɪnɪˈstrətɪv/","ipa_us":"/ˌædmɪnɪˈstrətɪv/","definition_zh":"行政的；管理的；事务性的","definition_en":"relating to the running and management of an organization, especially its procedures and officials rather than its core work","core_image":"大楼最里面那间不生产任何东西、却让所有部门按时运转的办公室","scene":"急诊室里医生在抢救，走廊尽头一间小屋里有人在排班、报耗材、填表格。That room did not treat anyone, but its administrative work kept the resuscitation going.","sceneCN":"这里 administrative 是「行政管理的、事务性的」（第 2 个义项：文书与例行事务）；句意：那间屋子不治病人，但它的事务性工作让抢救得以持续。图中可辨识物件：急诊室、走廊、排班表、耗材清单、表格。","pos":[{"tag":"adj.","zh":"行政的；管理的"},{"tag":"adj.","zh":"事务性的；文书性的"},{"tag":"adj.","zh":"（政府）行政部门的"}],"collocations":[{"phrase":"administrative costs","zh":"管理成本"},{"phrase":"administrative staff","zh":"行政人员"},{"phrase":"administrative burden","zh":"行政负担"},{"phrase":"administrative decision","zh":"行政决定"},{"phrase":"administrative leave","zh":"行政休假（停职待查）"}],"forms":[{"label":"原级（形容词）","form":"administrative"},{"label":"副词（加 -ly）","form":"administratively"},{"label":"动词（词基）","form":"administer"},{"label":"名词（行为／机构）","form":"administration"}],"derivatives":[{"word":"administer","pos":"v.","zh":"管理；执行；给予（药物）"},{"word":"administration","pos":"n.","zh":"管理；行政；政府"},{"word":"administrator","pos":"n.","zh":"管理者；行政人员"},{"word":"administratively","pos":"adv.","zh":"在行政上"},{"word":"administrate","pos":"v.","zh":"管理；掌管"}],"senses":[{"no":"01","title":"Relating to the running of an organization","titleCN":"与机构运转有关的","definition":"concerned with managing the affairs of an institution rather than with its primary activity","definitionCN":"指涉及机构事务的管理，而非其核心业务本身","example":"Administrative costs now exceed spending on research.","exampleCN":"管理成本现已超过研究支出。","why":"Administrative comes from Latin administrare, 'to serve'. The word still carries that direction: it names the work of serving an institution so that others can do its real business.","whyCN":"administrative 出自拉丁语 administrare“服务”。这个词仍带着那个方向：它命名“为机构服务”的工作，好让别人去做机构真正的业务。"},{"no":"02","title":"Paperwork and routine procedure","titleCN":"文书与例行事务","definition":"of the forms, records, schedules, and approvals that keep an organization running","definitionCN":"指维持机构运转的表格、记录、排班与审批","example":"Teachers spend hours on administrative tasks each week.","exampleCN":"教师每周要花数小时做事务性工作。","why":"Here the word names texture rather than function: forms, logs, rosters. It is slightly pejorative in this use, because the serving work has grown visible enough to compete with the real work.","whyCN":"这里这个词命名的是质感而不是职能：表格、记录、名册。这种用法略带贬义，因为“服务性工作”已经膨胀到能与“本职工作”争时间。"},{"no":"03","title":"Decided by officials, not courts","titleCN":"由官员而非法院作出的","definition":"in law, of a decision or remedy made by an agency or official rather than by a judge","definitionCN":"法律中指由机构或官员而非法官作出的决定或救济","example":"The fine was an administrative penalty, not a criminal one.","exampleCN":"这笔罚款是行政性处罚，不是刑事处罚。","why":"Law separates the administrative from the judicial: one branch applies rules, the other adjudicates disputes. The adjective marks decisions that come from the executive side of that line.","whyCN":"法律把“行政”与“司法”分开：一边执行规则，一边裁决争议。这个形容词标记来自这条线行政一侧的决定。"},{"no":"04","title":"Belonging to the executive branch","titleCN":"属于政府行政部门的","definition":"of the branch of government that carries out policy, as opposed to the legislative or judicial","definitionCN":"指执行政策的那一支政府权力，区别于立法与司法","example":"Administrative power expanded during the emergency.","exampleCN":"紧急状态期间，行政权力扩大了。","why":"Political theory needs a word for the machinery that executes policy. Administrative here is structural: it names a branch of the state, not a style of office.","whyCN":"政治理论需要一个词来指执行政策的机器。这里的 administrative 是结构性的：它命名国家的一支权力，而不是一种办公风格。"},{"no":"05","title":"A managerial sanction","titleCN":"管理性的处置","definition":"of leave, suspension, or discipline, imposed for organizational reasons rather than as punishment by a court","definitionCN":"指休假、停职或处分因组织原因施加，而非法院判罚","example":"He was placed on administrative leave during the inquiry.","exampleCN":"调查期间他被安排行政休假。","why":"The phrase administrative leave lets an employer act before any finding: the measure is procedural, not punitive. The adjective blurs the moral line by relocating the action to management.","whyCN":"administrative leave 这个说法让雇主在结论之前就能行动：措施是程序性的，不是惩罚性的。这个形容词通过把动作归入“管理”，模糊了道德界线。"},{"no":"06","title":"System privileges","titleCN":"系统管理权限","definition":"in computing, of rights or accounts that control a system rather than use it for ordinary work","definitionCN":"计算中指控制系统而非用于日常工作的权限或账户","example":"Only administrative accounts can install drivers.","exampleCN":"只有管理员账户才能安装驱动。","why":"Computing borrows the institutional distinction: ordinary users work, administrators keep the system working. Privilege is the modern form of the old 'serve the institution' role.","whyCN":"计算机借用这种制度性区分：普通用户干活，管理员让系统能干活。权限是古老的“服务机构”角色在现代的形态。"},{"no":"07","title":"Boundaries drawn for management","titleCN":"为管理而划定的区界","definition":"of districts, regions, or units created for governance rather than for historical or cultural reasons","definitionCN":"指为治理而非历史或文化原因划定的区、地区或单位","example":"The province is an administrative unit, not a cultural one.","exampleCN":"这个省是行政单位，不是文化单位。","why":"A map has two kinds of lines: those people feel and those officials draw. Administrative marks the second, and the word quietly says the boundary exists to be managed, not to be lived.","whyCN":"地图上有两种线：人们感觉得到的，和官员画出来的。administrative 标记第二种，这个词悄悄说明这条界线是为了被管理而存在，不是为了被生活而存在。"},{"no":"08","title":"The burden of procedure","titleCN":"程序造成的负担","definition":"used critically of rules and requirements that consume time without adding value","definitionCN":"批评性地指消耗时间却不增加价值的规则与要求","example":"Small firms complain about the administrative burden of compliance.","exampleCN":"小公司抱怨合规带来的行政负担。","why":"In this use the adjective turns against itself: the serving work is now experienced as a weight. 'Administrative burden' is a phrase that measures the cost of management in the time of the managed.","whyCN":"在这种用法里，形容词反噬自身：原本的服务性工作现在被体验为重量。administrative burden 这个短语，用“被管理者”的时间来计量“管理”的成本。"}],"etymology":{"intro":{"en":"Administrative is administer plus -ive, and its root is a surprise: Latin minister meant 'servant', from minus 'less'. Management began as service.","cn":"administrative 是 administer 加 -ive，而它的词根出人意料：拉丁语 minister 意为“仆人”，出自 minus“较少”。管理最初是服务。"},"items":[{"era":"LATIN","en":"Administrare 'to serve, assist, manage' is ad- 'to' plus ministrare 'to serve', from minister 'servant, assistant', ultimately from minus 'less'. The servant is the lesser one who attends.","cn":"administrare“服务、协助、管理”是 ad-“向”加 ministrare“服务”，出自 minister“仆人、助手”，最终出自 minus“较少”。仆人是那个地位较低、在旁伺候的人。"},{"era":"-IVE","en":"The suffix -ive is Latin -ivus 'tending to'. Attached to the participle administratus, it makes an adjective about the activity of managing, not about a person who manages.","cn":"后缀 -ive 是拉丁语 -ivus“倾向于”。接在分词 administratus 上，它造出关于“管理这一活动”的形容词，而不是关于“管理者这个人”。"},{"era":"14C.","en":"Administer arrives in English through Old French aministrer, already meaning both 'serve' and 'manage'. The religious sense of ministering to the sick survives in 'administer a drug'.","cn":"administer 经古法语 aministrer 进入英语，当时已兼有“服务”与“管理”两义。宗教性的“照顾病人”之义仍活在 administer a drug（给药）里。"},{"era":"17C.","en":"Administrative is formed in the 1600s on the Latin model, as states and companies begin to need a word for the machinery of management.","cn":"17 世纪按拉丁语模式造出 administrative，因为国家与公司开始需要一个词来指管理的机器。"},{"era":"19–20C.","en":"Bureaucracy gives the word its modern tone: administrative law, administrative burden, administrative leave. Service has become procedure, and procedure has become a cost.","cn":"官僚制给了这个词现代色调：administrative law、administrative burden、administrative leave。服务变成了程序，程序又变成了成本。"}]},"similar":{"note":{"en":"The first group shares the administr- shape and divides verb, process, person, and adverb; the second compares adjectives of organizational control.","cn":"第一组共享 administr- 外形，分出动作者、过程、执行者与副词；第二组比较表示“组织控制”的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"administer","ipa":"/əˈdɪnɪstə/","tag":"base verb","definition":"to manage, to carry out, or to give a drug. The adjective describes this activity.","definitionCN":"管理、执行，或给予药物。形容词描述的就是这一活动。"},{"word":"administration","ipa":"/ˌædmɪnɪˈstreɪʃn/","tag":"process/body","definition":"the act of managing, or the body that manages. It names the thing, while administrative names the quality.","definitionCN":"管理的行为，或管理机构。它命名事物，而 administrative 命名性质。"},{"word":"administrator","ipa":"/ˌædmɪnɪˈstreɪtə/","tag":"person","definition":"a person who manages. It is the human role behind the adjective.","definitionCN":"从事管理的人。它是形容词背后的人的角色。"},{"word":"administratively","ipa":"/ˌædmɪnɪˈstrətɪvli/","tag":"adverb","definition":"in administrative terms. It marks the angle from which something is done or judged.","definitionCN":"从行政角度。它标记做事或判断的视角。"}]},{"heading":"NEAR MEANING","entries":[{"word":"managerial","ipa":"/məˈnædʒəriəl/","tag":"business","definition":"relating to managers and their decisions. It is commercial in tone, while administrative is institutional and often official.","definitionCN":"与管理者及其决策有关。它偏商业语调，而 administrative 偏机构与官方。"},{"word":"bureaucratic","ipa":"/ˌbjuːrəˈkrætɪk/","tag":"criticism","definition":"of rule-bound official procedure. It is usually negative in a way administrative only sometimes is.","definitionCN":"指受规则约束的官方程序。它的贬义通常比 administrative 更稳定。"},{"word":"executive","ipa":"/ɪɡˈsekjətɪv/","tag":"authority","definition":"having power to put decisions into effect. It stresses authority, while administrative stresses the work of running.","definitionCN":"有权把决定付诸实施。它强调权力，而 administrative 强调运转的工作。"},{"word":"clerical","ipa":"/ˈklerɪkl/","tag":"office work","definition":"relating to office records and routine desk work. It is narrower: paper, not policy.","definitionCN":"与办公记录和日常案头工作有关。它更窄：只管纸面，不管政策。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on minister as 'servant' and the service-to-procedure drift, then three abstract images about the machinery of an institution.","cn":"先用五个围绕 minister“仆人”与“从服务到程序”漂移的挂钩，再用三个关于“机构机器”的抽象画面。"},"normal":[{"en":"ad- + minister (servant) + -ive = the serving work. Management began as attendance on an institution.","cn":"ad- + minister（仆人）+ -ive = 服务性的工作。管理最初是对机构的侍奉。"},{"en":"The same root gives 'administer a drug': service is still visible in the hospital.","cn":"同一词根给出 administer a drug（给药）：在医院里，“服务”仍然可见。"},{"en":"Administrative costs are the price of being organized: the office that produces nothing and enables everything.","cn":"管理成本是“被组织起来”的代价：那间不生产任何东西、却让一切得以发生的办公室。"},{"en":"'Administrative leave' sounds neutral because the adjective moves the action from punishment to procedure.","cn":"administrative leave 听起来中性，因为这个形容词把动作从“惩罚”挪到了“程序”。"},{"en":"Computing keeps the same distinction: users work, administrators keep the system workable.","cn":"计算机保留了同样的区分：用户干活，管理员让系统能干活。"}],"abstract":[{"en":"An institution that serves itself has inverted its root: the servant has become the purpose.","cn":"一个只服务自己的机构颠倒了词根：仆人变成了目的。"},{"en":"Administrative boundaries are lines drawn to be managed, so they can be redrawn without anyone's consent.","cn":"行政边界是为被管理而画的线，因此可以在无人同意的情况下重画。"},{"en":"Procedures are cheap individually and expensive collectively: each form is one minute, and ten thousand forms are a year.","cn":"程序单件便宜、集体昂贵：一张表是一分钟，一万张表就是一年。"}]},"examples":[{"en":"The university's administrative offices close at five.","cn":"大学的行政办公室五点关门。"},{"en":"The court ruled that the agency had acted beyond its administrative authority.","cn":"法院裁定该机构超越了其行政权限。"},{"en":"Digitizing the forms cut the administrative workload in half.","cn":"表格数字化把事务性工作量减半。"}],"dict_mnemonic":{"note":"ad-（向）+ minister（仆人）+ -ive → 为机构做服务性工作的 → 行政的、事务性的。管理的第一义是“侍奉”。","text":"ad- + minister（仆人）+ -ive → 服务机构的工作 → 行政的；事务性的","word":"administrative"},"root":"拉丁 administrare“服务、管理”（ad- 向 + minister 仆人，出自 minus 较少）+ 拉丁 -ivus → 拉丁 administrativus → 英语 administrative（17 世纪）。","sensesIntro":{"en":"One idea—work that serves an institution—is traced from the office that runs a hospital, through paperwork, official decisions, the executive branch, a managerial sanction, system privileges, drawn boundaries, and finally the burden that serving work becomes.","cn":"同一个观念——为机构服务的工作——从支撑医院的办公室出发，穿过文书、官方决定、行政部门、管理性处置、系统权限、人为划定的边界，最后落到服务性工作变成的负担。"},"semanticMap":{"core":{"en":"A back office where nothing is produced and everything is scheduled","cn":"一间不生产任何东西、却安排一切的幕后办公室"},"chain":["SERVE","MANAGE","DIRECT","PAPERWORK","OFFICIAL","SYSTEM"],"branches":[{"senses":"01 · 03","en":"Running an institution, and the official decisions that running produces.","cn":"运转一个机构，以及运转所产生的官方决定。"},{"senses":"02","en":"ROUTINE PAPERWORK: the forms, records, rosters, and approvals that keep an institution running.","cn":"文书与例行事务：表格、记录、排班与审批。"},{"senses":"04 · 05","en":"Two faces of authority: the state's executive power and an employer's managerial measure.","cn":"权威的两张面孔：国家的行政权力，与雇主的处置措施。"},{"senses":"06 · 07","en":"Boundaries made by administration: permissions in a system, borders on a map.","cn":"行政造成的边界：系统里的权限，地图上的界线。"},{"senses":"08","en":"THE BURDEN: rules and requirements that consume time without adding value.","cn":"程序造成的负担：消耗时间却不增加价值的规则。"}]},"affixes":{"intro":{"en":"Administrative's family is built on administer: the process noun, the person noun, the adverb, and the rare verb administrate.","cn":"administrative 的词族建立在 administer 上：过程名词、指人名词、副词，以及罕见的动词 administrate。"},"latinIntro":{"en":"The root minister has an unexpectedly large family: ministry, minister as a clergyman, and even minestrone through the idea of 'serving a dish'. The '-ster' ending marks an agent of service.","cn":"词根 minister 的家族出乎意料地大：ministry、作为神职人员的 minister，甚至 minestrone（通过“上菜”的观念）。-ster 词尾标记“服务的执行者”。"},"items":[{"word":"administrative","structure":"administr(at) + -ive","meaning":"relating to management","meaningCN":"行政的；管理的","example":"Administrative work is never finished.","exampleCN":"行政工作永远做不完。"},{"word":"administer","structure":"ad- + ministrare (serve)","meaning":"to manage or to give","meaningCN":"管理；给予","example":"A nurse administered the vaccine.","exampleCN":"一名护士接种了疫苗。"},{"word":"administration","structure":"administer + -ation","meaning":"the act or body of management","meaningCN":"管理；行政机构","example":"The administration announced new rules.","exampleCN":"政府宣布了新规。"},{"word":"administrator","structure":"administer + -ator","meaning":"one who manages","meaningCN":"管理者","example":"The hospital administrator approved the budget.","exampleCN":"医院管理者批准了预算。"},{"word":"administratively","structure":"administrative + -ly","meaning":"from a management angle","meaningCN":"在行政上","example":"The case was handled administratively.","exampleCN":"此案按行政程序处理。"},{"word":"administrate","structure":"back-formed from administrator","meaning":"to manage","meaningCN":"管理","example":"Few writers administrate well.","exampleCN":"少有作家善于管理。"},{"word":"minister","structure":"Latin minister (servant)","meaning":"a servant, later a clergyman and a minister of state","meaningCN":"仆人；牧师；部长","example":"The minister opened the session.","exampleCN":"部长宣布会议开始。"},{"word":"ministry","structure":"minister + -y","meaning":"the office or work of serving","meaningCN":"部；牧师职务","example":"The ministry of health issued guidance.","exampleCN":"卫生部发布了指引。"},{"word":"minor","structure":"Latin minor (lesser)","meaning":"smaller or less important","meaningCN":"较小的；次要的","example":"A minor change was made.","exampleCN":"作了一处小改动。"}],"latinEntries":[{"word":"minister","structure":"Latin noun","meaning":"servant, assistant","meaningCN":"仆人；助手","example":"Minister is the heart of administer.","exampleCN":"minister 是 administer 的核心。"},{"word":"ministrare","structure":"minister + -are","meaning":"to serve, attend","meaningCN":"服务；侍奉","example":"Ministrare gives English minister as a verb.","exampleCN":"ministrare 生出英语中作动词的 minister。"},{"word":"administrare","structure":"ad- + ministrare","meaning":"to serve for, to manage","meaningCN":"为……服务；管理","example":"Administrare is the direct source.","exampleCN":"administrare 是直接来源。"}]}},{"word":"advantageous","ipa_uk":"/ˌædvənˈteɪdʒəs/","ipa_us":"/ˌædvənˈteɪdʒəs/","definition_zh":"有利的；有优势的；划算的","definition_en":"giving a benefit or a better position, especially in comparison with an alternative","core_image":"起跑时站在前半个脚掌的位置，别人还在后面","scene":"谈判桌上，一方先拿到对方的成本表。Knowing the other side's costs before the first offer put them in an advantageous position.","sceneCN":"这里 advantageous 是「占优势的、有利的」（第 1 个义项：带来更有利的位置）；句意：在第一次报价前就知道对方的成本，让他们处在有利位置。图中可辨识物件：谈判桌、成本表、双方座位、笔记。","pos":[{"tag":"adj.","zh":"有利的；有好处的"},{"tag":"adj.","zh":"占优势的；条件优越的"},{"tag":"adj.","zh":"（条件、价格）划算的"}],"collocations":[{"phrase":"advantageous position","zh":"有利位置"},{"phrase":"advantageous terms","zh":"有利条件"},{"phrase":"mutually advantageous","zh":"互利互惠的"},{"phrase":"advantageous to","zh":"对……有利"},{"phrase":"strategically advantageous","zh":"战略上占优的"}],"forms":[{"label":"原级（形容词）","form":"advantageous"},{"label":"比较级","form":"more advantageous"},{"label":"最高级","form":"most advantageous"},{"label":"副词（加 -ly）","form":"advantageously"},{"label":"名词（加 -ness）","form":"advantageousness"}],"derivatives":[{"word":"advantage","pos":"n.","zh":"优势；好处"},{"word":"disadvantage","pos":"n.","zh":"劣势；不利条件"},{"word":"advantageously","pos":"adv.","zh":"有利地"},{"word":"disadvantageous","pos":"adj.","zh":"不利的"},{"word":"advantaged","pos":"adj.","zh":"处于优势地位的"}],"senses":[{"no":"01","title":"Giving a better position","titleCN":"带来更有利的位置","definition":"providing an edge over others in a competition or negotiation","definitionCN":"在竞争或谈判中提供胜过他人的优势","example":"The hilltop was an advantageous position for the defenders.","exampleCN":"山顶对防守方是有利位置。","why":"Advantageous is advantage plus -ous. Advantage began as 'being in front', from Latin ante 'before'. The adjective still measures position: not good in itself, but nearer the prize than others.","whyCN":"advantageous 是 advantage 加 -ous。advantage 最初意为“处在前面”，出自拉丁语 ante“在前”。这个形容词仍在量位置：不是本身好，而是比别人更靠近奖品。"},{"no":"02","title":"Beneficial in practice","titleCN":"实际有益","definition":"producing a useful result, especially one that repays the effort or cost","definitionCN":"产生有用结果，尤其是能抵偿投入或成本的结果","example":"Early testing proved advantageous for the whole project.","exampleCN":"早期测试对整个项目都有好处。","why":"Here the comparison is against doing nothing. 'Advantageous' is weaker than 'essential': it says the step pays, not that it is required.","whyCN":"这里的比较对象是“什么都不做”。advantageous 比 essential 弱：它说这一步有回报，而不是说非做不可。"},{"no":"03","title":"Favourable financial terms","titleCN":"划算的财务条件","definition":"of a price, rate, or deal, better than the normal or expected one","definitionCN":"指价格、利率或交易优于正常或预期的条件","example":"They secured an advantageous exchange rate before the currency fell.","exampleCN":"他们在货币贬值前争取到了有利的汇率。","why":"Finance makes the comparison explicit: an advantageous rate is measured against the market. The adjective converts 'in front' into a number, and the number is someone else's loss.","whyCN":"金融把比较显性化：有利汇率是相对市场来衡量的。这个形容词把“在前面”换算成一个数字，而这个数字是别人的损失。"},{"no":"04","title":"Favourable ground or placement","titleCN":"有利的地形或布置","definition":"of terrain, layout, or positioning, making success easier for whoever holds it","definitionCN":"指地形、布局或位置使占据者更容易成功","example":"The narrow pass was advantageous to a small force.","exampleCN":"狭窄的隘口对小队人马有利。","why":"This is the oldest sense and the most literal: high ground, a narrow pass. The advantage is written into the land, and whoever stands there inherits it.","whyCN":"这是最古老也最字面的义项：高地、隘口。优势被写进地形里，谁站在那儿谁就继承它。"},{"no":"05","title":"A trait that helps survival","titleCN":"有利于生存的性状","definition":"in biology, of a feature that improves an organism's chances in its environment","definitionCN":"生物学中指提高生物在其环境中存活机会的特征","example":"Longer legs were advantageous in the open savanna.","exampleCN":"在开阔的稀树草原上，较长的腿是有利性状。","why":"Evolution reuses the word for bodies: a trait is advantageous when it tilts the odds of surviving and reproducing. The comparison is now against other variants, not other firms.","whyCN":"演化把这个词用于身体：性状在倾斜存活与繁殖的概率时才算 advantageous。比较对象变成了其他变体，而不是其他公司。"},{"no":"06","title":"A good moment to act","titleCN":"有利的时机","definition":"of timing, coming at a point that makes an action easier or cheaper","definitionCN":"指时机正好使某项行动更容易或更便宜","example":"It was advantageous to buy before the new tax took effect.","exampleCN":"在新税前买入是有利的。","why":"Time can also be 'in front': acting before others, or before a change, puts you ahead. Timing turns the spatial image into a schedule.","whyCN":"时间也可以是“在前面”：比别人先动、或赶在变化之前动手，就占了先。时机把空间画面变成了日程表。"},{"no":"07","title":"Better than the alternative","titleCN":"比替代方案更划算","definition":"used in explicit comparisons, where one option is shown to yield more benefit than another","definitionCN":"用于明确比较，指某一选择比另一选择带来更多好处","example":"Renting was advantageous compared with buying at those rates.","exampleCN":"在那种利率下，租房比买房划算。","why":"The word almost always hides a comparison. Said alone, it invites the question 'than what?'—which is why contracts and analyses spell out the alternative.","whyCN":"这个词几乎总藏着一个比较。单独说出口时，它会引来“比什么？”这个问题——所以合同与分析都要写明替代方案。"},{"no":"08","title":"A polite word for self-interested","titleCN":"对“有利可图”的委婉说法","definition":"used euphemistically of a match or arrangement that brings material gain to one party","definitionCN":"委婉地指给一方带来物质利益的结合或安排","example":"The biography describes it as an advantageous marriage.","exampleCN":"传记把它描述为一桩有利的婚姻。","why":"Because the adjective speaks of position and profit but not of love or merit, it can excuse self-interest. 'An advantageous marriage' is a polite way of saying the money decided it.","whyCN":"因为这个形容词谈位置与收益，却不谈爱情或品德，它可以为私利开脱。an advantageous marriage 是“钱决定了这件事”的礼貌说法。"}],"etymology":{"intro":{"en":"Advantageous is advantage plus -ous. The base means 'being in front', and its spelling carries a famous error: the -d- was inserted by people who thought it came from Latin ad-.","cn":"advantageous 是 advantage 加 -ous。词基意为“处在前面”，而它的拼写带着一个著名的错误：-d- 是那些以为它出自拉丁语 ad- 的人加进去的。"},"items":[{"era":"LATIN","en":"The base traces to Latin ante 'before', through Vulgar Latin abante 'from before'. The idea is spatial and competitive: to be before someone is to be ahead of them.","cn":"词基上溯到拉丁语 ante“在前”，经俗拉丁语 abante“从前面”。这个观念是空间性的、竞争性的：在某人之前，就是领先于他。"},{"era":"FRENCH","en":"Old French avantage means 'advantage, profit, superiority', from avant 'before'. English borrows it in the late 14th century as avantage.","cn":"古法语 avantage 意为“优势、收益、优越”，出自 avant“在前”。英语于 14 世纪末以 avantage 借入。"},{"era":"-D-","en":"The -d- in advantage is intrusive. It was added in English on the mistaken analogy of Latin ad-, and the spelling has kept the error ever since—a rare case where a false etymology became permanent.","cn":"advantage 里的 -d- 是插入的。英语据拉丁语 ad- 的错误类推加上它，此后拼写就一直保留这个错误——罕见地，一个假词源被永久化了。"},{"era":"-OUS","en":"The suffix -ous comes from Latin -osus 'full of'. Advantageous therefore means 'full of advantage', a possessive adjective rather than a comparative one.","cn":"后缀 -ous 来自拉丁语 -osus“充满”。因此 advantageous 意为“充满优势的”，是领属形容词，而不是比较级形容词。"},{"era":"17C.","en":"Advantageous settles into English in the 1600s for positions, terms, and matches. Its comparative force is grammatical rather than built in: the 'than' is always supplied by context.","cn":"17 世纪 advantageous 在英语中稳定下来，用于位置、条件与婚姻。它的比较力量来自句法而非词内：那个“比”总是由语境补上。"}]},"similar":{"note":{"en":"The first group shares the advant- shape and shows the positive, negative, and personal branches; the second compares adjectives of benefit.","cn":"第一组共享 advant- 外形，展示肯定、否定与指人三条分支；第二组比较表示“有益”的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"advantage","ipa":"/ədˈvæntɪdʒ/","tag":"base noun","definition":"a factor that puts one ahead. The adjective says something confers this factor.","definitionCN":"使人领先的因素。形容词表示某物带来这一因素。"},{"word":"disadvantage","ipa":"/ˌdɪsədˈvæntɪdʒ/","tag":"opposite","definition":"a factor that holds one back. Despite the -ous form, disadvantageous is far rarer than its positive twin.","definitionCN":"使人落后的因素。尽管有 -ous 形式，disadvantageous 远比其肯定形式罕见。"},{"word":"advantaged","ipa":"/ədˈvæntɪdʒd/","tag":"person","definition":"having social or economic advantages. It describes people, usually in policy contexts.","definitionCN":"拥有社会或经济优势的。它描述人，常用于政策语境。"},{"word":"advantageously","ipa":"/ˌædvənˈteɪdʒəsli/","tag":"adverb","definition":"in a way that yields benefit. It modifies how a deal is made or a position is taken.","definitionCN":"以带来好处的方式。它修饰交易怎么做、位置怎么占。"}]},{"heading":"NEAR MEANING","entries":[{"word":"beneficial","ipa":"/ˌbenɪˈfɪʃl/","tag":"benefit","definition":"producing good effects. It is broader and more positive in tone, without the competitive edge.","definitionCN":"产生良好效果。它更宽、语气更正面，没有竞争性的锋芒。"},{"word":"favourable","ipa":"/ˈfeɪvərəbl/","tag":"conditions","definition":"tending to help success. It describes conditions and judgements more than position.","definitionCN":"有助于成功的。它更多描述条件与评价，而不是位置。"},{"word":"profitable","ipa":"/ˈprɒfɪtəbl/","tag":"money","definition":"yielding financial gain. It is narrower: advantageous can be strategic or social.","definitionCN":"产生财务收益。它更窄：advantageous 也可以是战略或社会性的。"},{"word":"expedient","ipa":"/ɪkˈspiːdiənt/","tag":"pragmatic","definition":"useful for a purpose, often at some moral cost. It shares the 'pays off' sense but carries disapproval.","definitionCN":"对目的有用，常带道德代价。它共享“划算”之义，但带有不赞成。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on 'in front' and the false -d-, then three abstract images about advantage as a comparison.","cn":"先用五个围绕“在前面”与假 -d- 的挂钩，再用三个关于“优势即比较”的抽象画面。"},"normal":[{"en":"ante = before. Advantage is literally 'being in front'; advantageous is 'having that front position'.","cn":"ante = 在前。advantage 字面就是“处在前面”；advantageous 是“拥有那个靠前的位置”。"},{"en":"The -d- is a mistake: avantage had no -d-, and people added one thinking of Latin ad-.","cn":"那个 -d- 是个错误：avantage 本没有 -d-，有人想到拉丁语 ad- 就加上去了。"},{"en":"Ask 'than what?'—advantageous is almost always a comparison in disguise.","cn":"问一句“比什么？”——advantageous 几乎总是伪装的比较。"},{"en":"High ground, good exchange rate, longer legs: same word for land, money, and bodies.","cn":"高地、好汇率、长腿：同一个词用于地形、金钱与身体。"},{"en":"An 'advantageous marriage' is a polite way of saying the money decided it.","cn":"an advantageous marriage 是“钱决定了这件事”的礼貌说法。"}],"abstract":[{"en":"Every advantage is someone's disadvantage: the word measures a gap, and a gap has two sides.","cn":"每一份优势都是某人的劣势：这个词量的是差距，而差距有两边。"},{"en":"An advantage that everyone can buy stops being one: the edge erodes as it spreads.","cn":"人人买得到的优势不再是优势：锋刃会随扩散而磨损。"},{"en":"Calling something advantageous hides the agent: it says what pays, not who pays or who is paid.","cn":"把某事称为 advantageous 会隐藏施动者：它说“什么划算”，却不说“谁付账、谁受益”。"}]},"examples":[{"en":"The new route is advantageous for trucks but hard on cars.","cn":"新路线对卡车有利，对轿车却不好走。"},{"en":"They negotiated advantageous terms for the lease.","cn":"他们谈下了有利的租约条件。"},{"en":"A warm, dry spring is advantageous for this crop.","cn":"温暖干燥的春天对这种作物有利。"}],"dict_mnemonic":{"note":"ante（在前）+ -age（名词）+ -ous（充满……的）→ 充满“靠前”优势的 → 有利的。注意 -d- 是后人误加，词源里本来没有。","text":"ante（在前）+ -age + -ous → 占着靠前位置的 → 有利的；占优势的","word":"advantageous"},"root":"拉丁 ante“在前”→ 俗拉丁 abante → 古法语 avantage“优势”（英语误加 -d-）+ 拉丁 -osus“充满” → 英语 advantageous（17 世纪）。","sensesIntro":{"en":"The senses all measure a gap between positions: a hilltop, a paying step, a good rate, a pass held by few, a longer leg, a timely purchase, an explicit comparison, and a marriage where money spoke.","cn":"这些义项都在量两个位置之间的差距：山顶、有回报的一步、好汇率、少数人守住的隘口、更长的腿、及时的买入、明说的比较，以及一桩由钱说话的婚姻。"},"semanticMap":{"core":{"en":"A runner whose front foot is already past the line","cn":"一只前脚已经越过起跑线的跑者"},"chain":["BEFORE","IN FRONT","UPPER HAND","FAVOURABLE","PROFITABLE","EXPEDIENT"],"branches":[{"senses":"01 · 07","en":"A position ahead and a deal better than its alternative.","cn":"靠前的位置，以及优于替代方案的交易。"},{"senses":"02 · 06","en":"Advantage in practice and advantage in timing.","cn":"实践中的好处与时机上的好处。"},{"senses":"03 · 05","en":"Favourable terms in money and in biology.","cn":"金钱上的有利条件与生物学上的有利条件。"},{"senses":"04","en":"GROUND THAT IS HELD: a layout or position that makes success easier for whoever occupies it.","cn":"被占据的地形：布局或位置使占据者更容易成功。"},{"senses":"08","en":"THE EUPHEMISM: an arrangement that brings private gain described as advantageous.","cn":"委婉语：把带来私利的安排说成有利可图。"}]},"affixes":{"intro":{"en":"Advantageous's family is built on advantage: the noun, its negative, the personal adjective, and the adverb.","cn":"advantageous 的词族建立在 advantage 上：名词、否定形式、指人的形容词，以及副词。"},"latinIntro":{"en":"The root ante 'before' is visible across English: antecedent, anticipate, anterior. The suffix -ous from -osus marks fullness, so advantageous is 'full of the front position' rather than 'more in front'.","cn":"词根 ante“在前”在英语中随处可见：antecedent、anticipate、anterior。后缀 -ous 出自 -osus，标记“充满”，因此 advantageous 是“充满靠前位置”，而不是“更靠前”。"},"items":[{"word":"advantageous","structure":"advantage + -ous (full of)","meaning":"giving an edge","meaningCN":"有利的；占优势的","example":"The terms were advantageous.","exampleCN":"条件是有利的。"},{"word":"advantage","structure":"avant (before) + -age","meaning":"a position ahead","meaningCN":"优势；好处","example":"Speed is her advantage.","exampleCN":"速度是她的优势。"},{"word":"disadvantage","structure":"dis- (not) + advantage","meaning":"a position behind","meaningCN":"劣势；不利","example":"The delay was a disadvantage.","exampleCN":"延误是不利因素。"},{"word":"disadvantageous","structure":"disadvantage + -ous","meaning":"giving a worse position","meaningCN":"不利的","example":"The rule is disadvantageous to renters.","exampleCN":"这条规则对租客不利。"},{"word":"advantaged","structure":"advantage + -ed","meaning":"having advantages","meaningCN":"处于优势的","example":"Advantaged students had tutors.","exampleCN":"条件好的学生请了家教。"},{"word":"advantageously","structure":"advantageous + -ly","meaning":"in a beneficial way","meaningCN":"有利地","example":"The land was advantageously placed.","exampleCN":"这块地位置有利。"},{"word":"antecedent","structure":"ante- (before) + cedere (go)","meaning":"something that came before","meaningCN":"先行词；前事","example":"Find the antecedent of the pronoun.","exampleCN":"找出代词的先行词。"},{"word":"anticipate","structure":"ante- + capere (take)","meaning":"to take beforehand","meaningCN":"预期；预先处理","example":"We anticipate a rise in demand.","exampleCN":"我们预期需求上升。"},{"word":"anterior","structure":"ante- + -ior (comparative)","meaning":"further in front","meaningCN":"前部的；先前的","example":"The anterior chamber of the eye.","exampleCN":"眼前房。"}],"latinEntries":[{"word":"ante","structure":"Latin preposition/adverb","meaning":"before, in front of","meaningCN":"在……之前；在……前面","example":"Ante underlies advantage.","exampleCN":"ante 是 advantage 的底层词根。"},{"word":"abante","structure":"ab- + ante (Vulgar Latin)","meaning":"from before","meaningCN":"从前面","example":"Abante became French avant.","exampleCN":"abante 变成法语 avant。"},{"word":"osus","structure":"Latin adjective suffix","meaning":"full of","meaningCN":"充满……的","example":"-osus became English -ous.","exampleCN":"-osus 变成英语 -ous。"}]}},{"word":"aesthetic","ipa_uk":"/esˈθetɪk/","ipa_us":"/esˈθetɪk/","definition_zh":"审美的；美感的；美学（的）；风格","definition_en":"relating to beauty, art, and the experience of sensing something as beautiful; also, a particular style or set of principles","core_image":"光落在陶罐的弧面上，你还没想它好不好用，先被那道弧度打动","scene":"博物馆里一件陶罐，没人用它盛水。Visitors walked around it only to watch how the glaze changed under the light, because what interested them was its aesthetic quality.","sceneCN":"这里 aesthetic 是「审美上的、美感的」（第 1 个义项：与美和艺术有关的）；句意：观众绕着它走，只看釉色在灯下怎么变，因为他们关心的是它的审美品质。图中可辨识物件：博物馆展柜、陶罐、射灯、驻足观众。","pos":[{"tag":"adj.","zh":"审美的；美学上的"},{"tag":"adj.","zh":"美观的；有美感的"},{"tag":"n.","zh":"（一套）美学风格；审美观"}],"collocations":[{"phrase":"aesthetic value","zh":"审美价值"},{"phrase":"aesthetic experience","zh":"审美体验"},{"phrase":"aesthetic judgment","zh":"审美判断"},{"phrase":"aesthetic appeal","zh":"美感吸引力"},{"phrase":"aesthetic taste","zh":"审美趣味"}],"forms":[{"label":"原级（形容词）","form":"aesthetic"},{"label":"名词（学科）","form":"aesthetics"},{"label":"副词（加 -ally）","form":"aesthetically"},{"label":"名词（人）","form":"aesthete"},{"label":"名词（主义）","form":"aestheticism"}],"derivatives":[{"word":"aesthetics","pos":"n.","zh":"美学"},{"word":"aesthetically","pos":"adv.","zh":"在审美上；美观地"},{"word":"aesthete","pos":"n.","zh":"唯美主义者；审美家"},{"word":"aestheticism","pos":"n.","zh":"唯美主义"},{"word":"anaesthetic","pos":"n./adj.","zh":"麻醉剂；感觉缺失的"}],"senses":[{"no":"01","title":"Concerned with beauty and art","titleCN":"与美和艺术有关的","definition":"relating to the appreciation or study of beauty, especially in art","definitionCN":"指与美的欣赏或研究有关，尤指在艺术中","example":"The paper offers an aesthetic reading of the frescoes.","exampleCN":"这篇论文对这些壁画作了审美解读。","why":"Aesthetic comes from Greek aisthanesthai, 'to perceive'. The word began as a claim about the senses, not about beauty: it names the kind of judgement made when you attend to how something looks and feels.","whyCN":"aesthetic 出自希腊语 aisthanesthai“感知”。这个词最初是关于感官的主张，而不是关于美：它命名的是当你关注某物看起来、感觉起来如何时所作的那种判断。"},{"no":"02","title":"Pleasing in appearance","titleCN":"外观上美观的","definition":"of a thing, having a quality that pleases the eye or the taste","definitionCN":"指事物具有悦目或悦趣的品质","example":"The building's aesthetic appeal draws visitors.","exampleCN":"这栋建筑的美感吸引游客。","why":"This is the narrowed, modern use: perception has become judgement of beauty. 'Aesthetic' as a compliment is always relative to a taste, which is why designers can argue about it endlessly.","whyCN":"这是收窄后的现代用法：感知变成了对美的判断。作为赞语的 aesthetic 总是相对于某种趣味，因此设计师可以为它争论不休。"},{"no":"03","title":"A design look or philosophy","titleCN":"设计风格或主张","definition":"characteristic of a style that treats appearance as a guiding principle","definitionCN":"指以外观为统摄原则的某种风格特征","example":"The firm is known for its spare, aesthetic approach.","exampleCN":"这家事务所以克制而讲究外观的手法著称。","why":"Here the adjective marks intent: form is not incidental but the organizing decision. The word signals that somebody chose the look deliberately rather than inherited it.","whyCN":"这里这个形容词标记意图：形式不是附带物，而是组织性的决定。这个词说明有人刻意选择了这个外观，而不是继承来的。"},{"no":"04","title":"A set of principles of beauty","titleCN":"一套美学原则","definition":"as a noun, a coherent set of ideas about what is beautiful or appropriate in a medium","definitionCN":"作名词，指关于某媒介中何为美或得体的成套观念","example":"Modernism brought a new aesthetic to photography.","exampleCN":"现代主义给摄影带来了新的美学。","why":"The countable noun is recent and useful: it packs a philosophy into one word. Aesthetic here is a lens a group shares, and works can be judged as inside or outside it.","whyCN":"这个可数名词出现较晚却很好用：它把一套哲学打包进一个词。这里的 aesthetic 是一个群体共享的透镜，作品可以被判为在其内或在其外。"},{"no":"05","title":"The sensory side of experience","titleCN":"经验的感官维度","definition":"in philosophy, the dimension of experience that comes through the senses rather than through concepts","definitionCN":"哲学中指经验中经由感官而非概念而来的那一维度","example":"Kant separates the aesthetic from the logical in judgement.","exampleCN":"康德在判断中把审美的与逻辑的区分开。","why":"This is the term's technical core. Baumgarten founded 'aesthetics' as the science of sensory cognition, so the aesthetic was originally everything given through the senses—beauty was only one case.","whyCN":"这是术语的技术核心。鲍姆加登把“美学”建立为感性认知的科学，因此 aesthetic 原本指一切经由感官而来者——美只是其中一例。"},{"no":"06","title":"Art valued for form alone","titleCN":"为形式本身而艺术","definition":"of an attitude that prizes beauty and form above moral, social, or practical purposes","definitionCN":"指把美与形式置于道德、社会或实用目的之上的态度","example":"The movement's aesthetic creed was 'art for art's sake'.","exampleCN":"该运动的审美信条是“为艺术而艺术”。","why":"When the adjective hardens into a creed, it becomes a stance: beauty is treated as sufficient justification. The 19th-century aesthetes made the word a flag, and it still carries that provocation.","whyCN":"当这个形容词凝固成信条，它就变成一种立场：美被视为充足的理由。19 世纪的唯美派把这个词做成旗帜，它至今仍带那种挑衅。"},{"no":"07","title":"Cosmetic rather than functional","titleCN":"美容性的而非功能性的","definition":"in medicine and dentistry, concerned with appearance rather than with function or health","definitionCN":"医学与牙科中指关注外观而非功能或健康","example":"Aesthetic dentistry has grown into a large industry.","exampleCN":"美容牙科已发展成一个大产业。","why":"Clinical usage revives the original split between what is perceived and what is necessary. An aesthetic procedure changes how something looks; the body underneath may be no healthier.","whyCN":"临床用法复活了“被感知”与“必需”之间的原初分裂。美容性操作改变的是外观；底下的身体可能并没有更健康。"},{"no":"08","title":"A personal look or vibe","titleCN":"个人风格或调性","definition":"informally, the recognizable visual character of a person, brand, or object","definitionCN":"非正式地指人、品牌或物件可辨识的视觉性格","example":"Warm browns and old film—that is her aesthetic.","exampleCN":"暖棕色与老胶片——那就是她的风格。","why":"Social media turned the noun into a label anyone can claim: a palette, a filter, a mood. The philosophical term has become a way to say 'this is how I want to look', which is the sensory core in miniature.","whyCN":"社交媒体把这个名词变成人人可认领的标签：一组配色、一个滤镜、一种情绪。哲学术语变成了“我想看起来是这样”的说法——这正是感官核心的缩微版。"}],"etymology":{"intro":{"en":"Aesthetic is Greek, not Latin: aisthētikos 'of perception', from aisthanesthai 'to perceive'. Its journey from 'sensory' to 'beautiful' is the story of a whole discipline.","cn":"aesthetic 是希腊语，不是拉丁语：aisthētikos“感知的”，出自 aisthanesthai“感知”。它从“感官的”走到“美的”，是一整门学科的故事。"},"items":[{"era":"GREEK","en":"Aisthanesthai 'to perceive, feel' gives aisthēsis 'perception' and aisthētikos 'of perception, perceptible'. The deeper root is often connected with a PIE sense-word, but the reconstruction is not secure.","cn":"aisthanesthai“感知、感觉”生出 aisthēsis“感知”与 aisthētikos“感知的、可感知的”。更深词根常被联系到某个原始印欧语的感觉词，但这一重构并不可靠。"},{"era":"-IC","en":"The ending -ic is Greek -ikos, the adjective suffix of 'belonging to'. So aisthētikos means 'belonging to perception', not 'beautiful'—a meaning it only acquired much later.","cn":"词尾 -ic 是希腊语 -ikos，表示“属于……的”的形容词后缀。因此 aisthētikos 意为“属于感知的”，而不是“美的”——后一含义是很久以后才获得的。"},{"era":"18C.","en":"Baumgarten's Aesthetica (1750) makes aesthetics the science of sensory cognition, and the term enters German and then English philosophy. Beauty is only one of its objects.","cn":"鲍姆加登的《美学》（1750）把美学确立为感性认知的科学，术语随之进入德国哲学，再进入英语哲学。美只是它的对象之一。"},{"era":"19C.","en":"English narrows the word toward art and beauty. Aesthete and aestheticism appear in the 1880s, and 'aesthetic' becomes a badge for refined, sometimes provocative, taste.","cn":"19 世纪英语把这个词收窄到艺术与美。aesthete 与 aestheticism 出现于 1880 年代，aesthetic 成了精致、有时带挑衅的趣味的徽章。"},{"era":"20C.","en":"Design, marketing, and finally social media generalize it: any look can be 'an aesthetic'. The Greek word for perception ends up naming a curated surface.","cn":"20 世纪，设计、营销，最终是社交媒体把它泛化：任何外观都可以是 an aesthetic。这个意为“感知”的希腊词，最后命名了一个被精心挑选的表面。"}]},"similar":{"note":{"en":"The first group shares the aesthet- shape and shows the discipline, the person, the adverb, and the medical negation; the second compares adjectives of beauty and taste.","cn":"第一组共享 aesthet- 外形，展示学科、人、副词与医学上的否定形式；第二组比较表示“美与趣味”的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"aesthetics","ipa":"/esˈθetɪks/","tag":"discipline","definition":"the branch of philosophy concerned with beauty and sensory experience. As a plural noun it names a field, not a quality.","definitionCN":"研究美与感官经验的哲学分支。作复数名词时它命名一个领域，而不是一种性质。"},{"word":"aesthete","ipa":"/ˈiːsθiːt/","tag":"person","definition":"a person devoted to beauty and refined taste. It can be admiring or mocking.","definitionCN":"献身于美与精致趣味的人。它可以是赞赏，也可以是讥讽。"},{"word":"aesthetically","ipa":"/esˈθetɪkli/","tag":"adverb","definition":"in terms of appearance or beauty. It marks the angle of judgement.","definitionCN":"从外观或美的角度。它标记判断的视角。"},{"word":"anaesthetic","ipa":"/ˌænəsˈθetɪk/","tag":"medical negation","definition":"a drug that removes sensation. The an- prefix means 'without', so the word literally says 'without perception'.","definitionCN":"消除感觉的药物。an- 前缀意为“无”，所以这个词字面就是“没有感知”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"artistic","ipa":"/ɑːˈtɪstɪk/","tag":"skill","definition":"showing skill or taste in art. It stresses the maker's ability, while aesthetic stresses the quality perceived.","definitionCN":"在艺术上显出技巧或品味。它强调制作者的能力，而 aesthetic 强调被感知的品质。"},{"word":"beautiful","ipa":"/ˈbjuːtɪfl/","tag":"beauty","definition":"giving pleasure to the senses. It is the ordinary word that aesthetic dresses up in theory.","definitionCN":"给感官以愉悦。它是 aesthetic 用理论包装起来的日常词。"},{"word":"tasteful","ipa":"/ˈteɪstfl/","tag":"judgement","definition":"showing good judgement in appearance. It carries social approval that aesthetic can leave open.","definitionCN":"在外观上显出良好判断。它带社会认可，而 aesthetic 可以不加评判。"},{"word":"elegant","ipa":"/ˈelɪɡənt/","tag":"style","definition":"graceful and restrained in form. It is a specific aesthetic verdict, not the general term.","definitionCN":"形式优雅而克制。它是一个具体的审美评断，而不是总称。"}]}]},"mnemonics":{"normalIntro":{"en":"Five hooks on Greek 'perceive' and the drift toward beauty, then three abstract images about sensing versus judging.","cn":"先用五个围绕希腊语“感知”与“向美漂移”的挂钩，再用三个关于“感知与判断”的抽象画面。"},"normal":[{"en":"aisthanesthai = to perceive. Aesthetic began as 'of the senses'; beauty came later and took the whole word.","cn":"aisthanesthai = 感知。aesthetic 起初是“感官的”；美后来才来，却占满了整个词。"},{"en":"Anaesthetic is the same root with an-: 'without perception'. A dentist's drug and an art theory are cousins.","cn":"anaesthetic 是同一词根加 an-：“没有感知”。牙医的药与艺术理论是亲戚。"},{"en":"Baumgarten made aesthetics the science of sensory cognition in 1750; Kant then split the aesthetic from the logical.","cn":"鲍姆加登 1750 年把美学立为感性认知的科学；康德随后把审美的与逻辑的分开。"},{"en":"The 1880s aesthetes turned a philosophical term into a badge: art for art's sake.","cn":"1880 年代的唯美派把哲学术语做成徽章：为艺术而艺术。"},{"en":"Now anyone's palette is 'my aesthetic'—the Greek word for perceiving ends up naming a mood board.","cn":"现在任何人的配色都可以是 my aesthetic——意为“感知”的希腊词，最后命名了一块情绪板。"}],"abstract":[{"en":"Aesthetic judgement claims to be universal and behaves like a preference: everybody says 'this is beautiful' and nobody agrees.","cn":"审美判断声称普遍，行为却像偏好：人人都说“这很美”，却没人一致。"},{"en":"When appearance is separated from function, a beautiful thing can be a bad tool, and the word stops caring.","cn":"当外观与功能分离，美的东西可以是坏的工具，而这个词并不在意。"},{"en":"Naming something 'an aesthetic' turns a way of seeing into an object one can buy, copy, or sell.","cn":"把某物叫作 an aesthetic，就把一种观看方式变成了可以购买、复制、出售的物品。"}]},"examples":[{"en":"The restoration was guided by aesthetic rather than historical principles.","cn":"这次修复以审美原则而非历史原则为指导。"},{"en":"His films have a spare, almost monastic aesthetic.","cn":"他的影片有一种克制、近乎修道院式的美学。"},{"en":"Aesthetically, the bridge works; structurally, it worries engineers.","cn":"从审美上看这座桥成立；从结构上，它让工程师担忧。"}],"dict_mnemonic":{"note":"希腊 aisthanesthai（感知）+ -ikos（属于……的）→ 属于感官的 → 审美的。美只是感官经验里最受关注的那一类。","text":"aisthēsis（感知）+ -ic → 属于感官与感受的 → 审美的；美学风格","word":"aesthetic"},"root":"希腊 aisthētikos“感知的”（aisthanesthai 感知 + -ikos 属于……的）→ 德语 Ästhetik（18 世纪）→ 英语 aesthetic。","sensesIntro":{"en":"The senses follow one Greek word from sense perception to beauty: the study of art, pleasing appearance, a deliberate look, a shared set of principles, the sensory dimension of experience, art for its own sake, cosmetic practice, and a personal style.","cn":"这些义项让一个希腊词从感官知觉一路走到美：艺术研究、悦目外观、刻意的外观、共享的原则、经验的感官维度、为艺术而艺术、美容实践，以及个人风格。"},"semanticMap":{"core":{"en":"Light sliding across the curve of a clay jar before you ask what it is for","cn":"光掠过陶罐弧面，在你问它有什么用之前"},"chain":["PERCEIVE","SENSE","BEAUTY","TASTE","STYLE","COSMETIC"],"branches":[{"senses":"01 · 05","en":"The discipline and its technical object: art criticism and the philosophy of sensation.","cn":"学科与其技术对象：艺术批评与感觉的哲学。"},{"senses":"02 · 06","en":"Pleasing appearance, and the creed that appearance is enough.","cn":"悦目的外观，以及“外观即足够”的信条。"},{"senses":"03 · 04","en":"A look chosen by someone, and a set of principles shared by a group.","cn":"某人选定的外观，与一个群体共享的原则。"},{"senses":"07","en":"THE CLINICAL USE: appearance attended to rather than function or health.","cn":"临床：关注外观而非功能或健康。"},{"senses":"08","en":"A PERSONAL SIGNATURE: the recognisable visual character of a person, brand, or object.","cn":"个人调性：人、品牌或物件可辨识的视觉性格。"}]},"affixes":{"intro":{"en":"Aesthetic's family is built on the Greek root for perception: the discipline, the person, the adverb, the movement, and the medical negation anaesthetic.","cn":"aesthetic 的词族建立在希腊语“感知”词根上：学科、人、副词、主义，以及医学上的否定形式 anaesthetic。"},"latinIntro":{"en":"This word is Greek rather than Latin: aisthēsis gives aesthetic, and the same root with an- 'without' gives anaesthesia. The -etic ending comes from Greek -ikos through French.","cn":"这个词是希腊语而非拉丁语：aisthēsis 生出 aesthetic，同一词根加 an-“无”则生出 anaesthesia。-etic 词尾经法语来自希腊语 -ikos。"},"items":[{"word":"aesthetic","structure":"Greek aisthētikos (of perception)","meaning":"relating to beauty or sensory taste","meaningCN":"审美的；美感的","example":"The design has real aesthetic value.","exampleCN":"这个设计有真正的审美价值。"},{"word":"aesthetics","structure":"aesthetic + -s (field name)","meaning":"the philosophy of beauty","meaningCN":"美学","example":"She teaches aesthetics.","exampleCN":"她教美学。"},{"word":"aesthetically","structure":"aesthetic + -ally","meaning":"in terms of beauty","meaningCN":"在审美上","example":"The room is aesthetically pleasing.","exampleCN":"这个房间在审美上令人愉悦。"},{"word":"aesthete","structure":"Greek aisthētēs (one who perceives)","meaning":"a devotee of beauty","meaningCN":"唯美主义者","example":"He lived like an aesthete.","exampleCN":"他像唯美主义者那样生活。"},{"word":"aestheticism","structure":"aesthetic + -ism","meaning":"the doctrine of art for art's sake","meaningCN":"唯美主义","example":"Aestheticism flourished in the 1890s.","exampleCN":"唯美主义在 1890 年代兴盛。"},{"word":"anaesthetic","structure":"an- (without) + aisthēsis","meaning":"a drug that removes sensation","meaningCN":"麻醉剂","example":"The anaesthetic wore off in an hour.","exampleCN":"麻醉一小时后消退。"},{"word":"anaesthesia","structure":"an- + aisthēsis (perception)","meaning":"loss of sensation","meaningCN":"感觉缺失；麻醉","example":"General anaesthesia requires monitoring.","exampleCN":"全身麻醉需要监护。"},{"word":"synesthesia","structure":"syn- (together) + aisthēsis","meaning":"senses crossing over","meaningCN":"联觉","example":"Synesthesia lets her taste colours.","exampleCN":"联觉让她能“尝到”颜色。"},{"word":"perception","structure":"Latin percipere (seize through)","meaning":"the act of sensing and interpreting","meaningCN":"知觉；感知","example":"Perception shapes judgement.","exampleCN":"知觉塑造判断。"}],"latinEntries":[{"word":"aisthēsis","structure":"Greek noun","meaning":"perception, sensation","meaningCN":"感知；感觉","example":"Aisthēsis is the root of aesthetic.","exampleCN":"aisthēsis 是 aesthetic 的词根。"},{"word":"aisthanesthai","structure":"Greek verb","meaning":"to perceive, feel","meaningCN":"感知；感觉","example":"The verb underlies the whole family.","exampleCN":"这个动词支撑整个词族。"},{"word":"aisthētikos","structure":"aisthēsis + -ikos","meaning":"of perception, perceptible","meaningCN":"感知的；可感知的","example":"Aisthētikos became Latin aestheticus.","exampleCN":"aisthētikos 变成拉丁语 aestheticus。"}]}}]);
